-- Pokémon (1025 filas)
INSERT INTO pokemon (numero_nacional, nombre, altura_m, peso_kg, descripcion, url_imagen,
                     id_genero, id_region_origen, es_legendario, es_mitico)
SELECT v.num, v.nombre, v.altura, v.peso, v.descripcion, v.imagen, g.id_genero, r.id_region, v.leg, v.mit
FROM (VALUES
    (1, 'Bulbasaur', 0.7, 6.9, 'Desde que nace, crece alimentándose de los nutrientes que contiene la semilla de su lomo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/1.png', 'Ambos', 'kanto', FALSE, FALSE),
    (2, 'Ivysaur', 1.0, 13.0, 'La luz del sol lo fortalece y hace que le crezca el capullo que tiene en el lomo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/2.png', 'Ambos', 'kanto', FALSE, FALSE),
    (3, 'Venusaur', 2.0, 100.0, 'La flor que tiene en el lomo libera un delicado aroma, que tiene un efecto relajante en combate.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/3.png', 'Ambos', 'kanto', FALSE, FALSE),
    (4, 'Charmander', 0.6, 8.5, 'Este Pokémon nace con una llama en la punta de la cola. Si se le apagara, fallecería.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/4.png', 'Ambos', 'kanto', FALSE, FALSE),
    (5, 'Charmeleon', 1.1, 19.0, 'Si se exalta en combate, expulsa intensas llamaradas que incineran todo a su alrededor.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/5.png', 'Ambos', 'kanto', FALSE, FALSE),
    (6, 'Charizard', 1.7, 90.5, 'Sus potentes alas le permiten volar a una altura de 1400 m. Escupe llamaradas que llegan a alcanzar temperaturas elevadísimas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/6.png', 'Ambos', 'kanto', FALSE, FALSE),
    (7, 'Squirtle', 0.5, 9.0, 'Cuando se siente en peligro, se esconde en su caparazón y escupe chorros de agua por la boca.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/7.png', 'Ambos', 'kanto', FALSE, FALSE),
    (8, 'Wartortle', 1.0, 22.5, 'Utiliza hábilmente sus peludas orejas y la cola para mantener el equilibrio al nadar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/8.png', 'Ambos', 'kanto', FALSE, FALSE),
    (9, 'Blastoise', 1.6, 85.5, 'Dispara chorros de agua a través de los cañones de su caparazón, capaces de agujerear incluso el acero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/9.png', 'Ambos', 'kanto', FALSE, FALSE),
    (10, 'Caterpie', 0.3, 2.9, 'Sus cortas patas están recubiertas de ventosas que le permiten subir incansable por muros y cuestas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/10.png', 'Ambos', 'kanto', FALSE, FALSE),
    (11, 'Metapod', 0.7, 9.9, 'Aunque cuenta con una coraza muy dura, tiene un cuerpo bastante blando. Un ataque violento puede acabar con él.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/11.png', 'Ambos', 'kanto', FALSE, FALSE),
    (12, 'Butterfree', 1.1, 32.0, 'Recoge néctar a diario y se lo adhiere al pelo de las patas para llevarlo a su nido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/12.png', 'Ambos', 'kanto', FALSE, FALSE),
    (13, 'Weedle', 0.3, 3.2, 'El aguijón de la cabeza es muy puntiagudo. Se alimenta de hojas oculto en la espesura de bosques y praderas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/13.png', 'Ambos', 'kanto', FALSE, FALSE),
    (14, 'Kakuna', 0.6, 10.0, 'Aunque es casi incapaz de moverse, en caso de sentirse amenazado puede envenenar a los enemigos con su aguijón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/14.png', 'Ambos', 'kanto', FALSE, FALSE),
    (15, 'Beedrill', 1.0, 29.5, 'Tiene tres aguijones venenosos, dos en las patas anteriores y uno en la parte baja del abdomen, con los que ataca a sus enemigos una y otra vez.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/15.png', 'Ambos', 'kanto', FALSE, FALSE),
    (16, 'Pidgey', 0.3, 1.8, 'Su docilidad es tal que suelen defenderse levantando arena en lugar de contraatacar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/16.png', 'Ambos', 'kanto', FALSE, FALSE),
    (17, 'Pidgeotto', 1.1, 30.0, 'Su extraordinaria vitalidad y resistencia le permiten cubrir grandes distancias del territorio que habita en busca de presas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/17.png', 'Ambos', 'kanto', FALSE, FALSE),
    (18, 'Pidgeot', 1.5, 39.5, 'Este Pokémon vuela a una velocidad de 2 mach en busca de presas. Sus grandes garras son armas muy peligrosas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/18.png', 'Ambos', 'kanto', FALSE, FALSE),
    (19, 'Rattata', 0.3, 3.5, 'Es propenso a hincar los incisivos en cualquier cosa que se le ponga por delante. Si se ve alguno, seguramente haya cuarenta cerca.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/19.png', 'Ambos', 'kanto', FALSE, FALSE),
    (20, 'Raticate', 0.7, 18.5, 'Gracias a las pequeñas membranas de las patas traseras, puede nadar por los ríos para capturar presas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/20.png', 'Ambos', 'kanto', FALSE, FALSE),
    (21, 'Spearow', 0.3, 2.0, 'A la hora de proteger su territorio, compensa su incapacidad para volar a gran altura con una increíble velocidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/21.png', 'Ambos', 'kanto', FALSE, FALSE),
    (22, 'Fearow', 1.2, 38.0, 'Este Pokémon ha existido desde tiempos remotos. Al menor atisbo de peligro, alza el vuelo y huye.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/22.png', 'Ambos', 'kanto', FALSE, FALSE),
    (23, 'Ekans', 2.0, 6.9, 'La longitud de este Pokémon aumenta con el tiempo. Por la noche, se enrosca en las ramas de los árboles para descansar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/23.png', 'Ambos', 'kanto', FALSE, FALSE),
    (24, 'Arbok', 3.5, 65.0, 'Se han llegado a identificar hasta seis variaciones distintas de los espeluznantes dibujos de su piel.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/24.png', 'Ambos', 'kanto', FALSE, FALSE),
    (25, 'Pikachu', 0.4, 6.0, 'Los miembros de esta especie se saludan entre sí uniendo sus colas y transmitiéndose corriente eléctrica.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/25.png', 'Ambos', 'kanto', FALSE, FALSE),
    (26, 'Raichu', 0.8, 30.0, 'Cuando ha descargado las bolsas de las mejillas, levanta la cola y absorbe la carga eléctrica que hay en el ambiente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/26.png', 'Ambos', 'kanto', FALSE, FALSE),
    (27, 'Sandshrew', 0.6, 12.0, 'Excava madrigueras profundas en las que vive. Parte con sus afiladas garras cualquier roca, por dura que sea, que le entorpezca el camino.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/27.png', 'Ambos', 'kanto', FALSE, FALSE),
    (28, 'Sandslash', 1.0, 29.5, 'Trepa a los árboles con sus afiladas garras y deja caer bayas para los Sandshrew que esperan debajo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/28.png', 'Ambos', 'kanto', FALSE, FALSE),
    (29, 'Nidoran♀', 0.4, 7.0, 'Parte las bayas con sus duros incisivos para comérselas. La punta del cuerno de las hembras es más redondeada que la de los machos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/29.png', 'Hembra', 'kanto', FALSE, FALSE),
    (30, 'Nidorina', 0.8, 20.0, 'Cuando el peligro se cierne sobre la manada, los miembros unen fuerzas para defenderse emitiendo un coro de ondas ultrasónicas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/30.png', 'Hembra', 'kanto', FALSE, FALSE),
    (31, 'Nidoqueen', 1.3, 60.0, 'Para mecer a sus crías, las coloca en los huecos que tiene entre las púas dorsales, momento durante el cual no secretan veneno.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/31.png', 'Hembra', 'kanto', FALSE, FALSE),
    (32, 'Nidoran♂', 0.5, 9.0, 'Pequeño pero valiente. Arriesgaría la vida en combate con tal de proteger a su compañera.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/32.png', 'Macho', 'kanto', FALSE, FALSE),
    (33, 'Nidorino', 0.9, 19.5, 'Es nervioso y agresivo por naturaleza. Cuando suben sus niveles de adrenalina, la concentración de toxinas en su veneno aumenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/33.png', 'Macho', 'kanto', FALSE, FALSE),
    (34, 'Nidoking', 1.4, 62.0, 'Presume de su hercúlea fuerza y combate vigorosamente con su robusta cola y su cuerno, con el que hasta puede pulverizar diamantes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/34.png', 'Macho', 'kanto', FALSE, FALSE),
    (35, 'Clefairy', 0.6, 7.5, 'Su adorable grito y comportamiento lo hacen muy popular. Sin embargo, raramente se avista.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/35.png', 'Ambos', 'kanto', FALSE, FALSE),
    (36, 'Clefable', 1.3, 40.0, 'Su oído es tan fino que puede percibir cómo cae una aguja a 1 km de distancia. Por eso suele habitar en lugares tranquilos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/36.png', 'Ambos', 'kanto', FALSE, FALSE),
    (37, 'Vulpix', 0.6, 9.9, 'Su pelaje se va volviendo más suave, lustroso y bello a medida que le crecen las seis colas. Al abrazarlo, emana una ligera calidez.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/37.png', 'Ambos', 'kanto', FALSE, FALSE),
    (38, 'Ninetales', 1.1, 19.9, 'Muy inteligente y vengativo. Agarrar una de sus colas podría traer 1000 años de mala suerte.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/38.png', 'Ambos', 'kanto', FALSE, FALSE),
    (39, 'Jigglypuff', 0.5, 5.5, 'Posee la capacidad de modular su voz a voluntad cambiando la longitud de onda para entonar una melodía misteriosa que provoca adormecimiento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/39.png', 'Ambos', 'kanto', FALSE, FALSE),
    (40, 'Wigglytuff', 1.0, 12.0, 'Se enorgullece de su pelaje fino y sedoso. El rizo de la frente, en especial, posee un tacto sublime.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/40.png', 'Ambos', 'kanto', FALSE, FALSE),
    (41, 'Zubat', 0.8, 7.5, 'Habitan en cuevas donde no llegan los rayos del sol. De día, se acurrucan unos junto a otros para entrar en calor mientras duermen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/41.png', 'Ambos', 'kanto', FALSE, FALSE),
    (42, 'Golbat', 1.6, 55.0, 'Camina con soltura sobre sus pequeñas patas. Se acerca con sigilo a su presa mientras esta duerme y le clava los colmillos para chuparle la sangre.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/42.png', 'Ambos', 'kanto', FALSE, FALSE),
    (43, 'Oddish', 0.5, 5.4, 'Durante el día, se agazapa en el frío subsuelo huyendo del sol. La luz de la luna le hace crecer.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/43.png', 'Ambos', 'kanto', FALSE, FALSE),
    (44, 'Gloom', 0.8, 8.6, 'Lo que parece baba es realmente un néctar muy pegajoso que se adhiere sin remisión al tocarlo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/44.png', 'Ambos', 'kanto', FALSE, FALSE),
    (45, 'Vileplume', 1.2, 18.6, 'Cuanto mayores son sus pétalos, más tóxico es su polen. Le pesa la cabeza y le cuesta mantenerla erguida.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/45.png', 'Ambos', 'kanto', FALSE, FALSE),
    (46, 'Paras', 0.3, 5.4, 'Escarba en el suelo para extraer nutrientes de las raíces de los árboles, que las setas del lomo absorben después casi por completo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/46.png', 'Ambos', 'kanto', FALSE, FALSE),
    (47, 'Parasect', 1.0, 29.5, 'Tras largo tiempo absorbiendo la energía del huésped, la seta parásita del lomo es la que parece controlar la voluntad de este Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/47.png', 'Ambos', 'kanto', FALSE, FALSE),
    (48, 'Venonat', 1.0, 30.0, 'Sus grandes ojos actúan como radares. A plena luz se percibe que son, en realidad, grupos de ojos diminutos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/48.png', 'Ambos', 'kanto', FALSE, FALSE),
    (49, 'Venomoth', 1.5, 12.5, 'Las alas desprenden un polvillo de escamas impregnado de toxinas que se adhiere al contacto y resulta difícil de quitar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/49.png', 'Ambos', 'kanto', FALSE, FALSE),
    (50, 'Diglett', 0.2, 0.8, 'Este Pokémon avanza horadando la tierra a poca profundidad. Resulta fácil localizarlo por los montículos que deja como rastro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/50.png', 'Ambos', 'kanto', FALSE, FALSE),
    (51, 'Dugtrio', 0.7, 33.3, 'Estos trillizos cavan a una profundidad de hasta 100 km. Se desconoce el aspecto de la parte de sus cuerpos que se oculta bajo tierra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/51.png', 'Ambos', 'kanto', FALSE, FALSE),
    (52, 'Meowth', 0.4, 4.2, 'Se lava cuidadosamente la cara para que no se le ensucie la moneda de oro que tiene en la frente. No se lleva nada bien con los Meowth de Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/52.png', 'Ambos', 'kanto', FALSE, FALSE),
    (53, 'Persian', 1.0, 32.0, 'Hace gala de un porte elegante y majestuoso. No congenia con los toscos Perrserker y ambos se profesan un mutuo desprecio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/53.png', 'Ambos', 'kanto', FALSE, FALSE),
    (54, 'Psyduck', 0.8, 19.6, 'Sus dolores de cabeza empeoran a medida que aumenta su nivel de estrés. Su increíble poder psíquico puede causar estragos a su alrededor.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/54.png', 'Ambos', 'kanto', FALSE, FALSE),
    (55, 'Golduck', 1.7, 76.6, 'Cuenta una antigua leyenda que los Golduck arrastraban a quienes contaminaran sus ríos al fondo de las aguas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/55.png', 'Ambos', 'kanto', FALSE, FALSE),
    (56, 'Mankey', 0.5, 28.0, 'Este ágil Pokémon vive en los árboles. Se enfada con facilidad y, cuando lo hace, se abalanza contra todo lo que se encuentre a su alrededor.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/56.png', 'Ambos', 'kanto', FALSE, FALSE),
    (57, 'Primeape', 1.0, 32.0, 'Solo se calma cuando no hay nadie cerca, por lo que llegar a ver ese momento resulta verdaderamente difícil.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/57.png', 'Ambos', 'kanto', FALSE, FALSE),
    (58, 'Growlithe', 0.7, 19.0, 'Extremadamente fiel, ladrará furioso a cualquiera que suponga una amenaza para su Entrenador con tal de defenderlo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/58.png', 'Ambos', 'kanto', FALSE, FALSE),
    (59, 'Arcanine', 1.9, 155.0, 'Muchos han quedado cautivados por su belleza desde la antigüedad. Corre ágilmente como si tuviera alas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/59.png', 'Ambos', 'kanto', FALSE, FALSE),
    (60, 'Poliwag', 0.6, 12.4, 'En ríos de aguas bravas, usa sus gruesos labios a modo de ventosa para adherirse a las rocas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/60.png', 'Ambos', 'kanto', FALSE, FALSE),
    (61, 'Poliwhirl', 1.0, 20.0, 'Secreta un sudor viscoso que le sirve para escurrirse y escapar del agarre de sus enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/61.png', 'Ambos', 'kanto', FALSE, FALSE),
    (62, 'Poliwrath', 1.3, 54.0, 'No solo es un experto nadador, sino que también domina las artes marciales. Propina enérgicos puñetazos gracias a sus musculosos brazos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/62.png', 'Ambos', 'kanto', FALSE, FALSE),
    (63, 'Abra', 0.9, 19.5, 'Puede teletransportarse mientras duerme. Se dice que, cuanto más profundo sea su sueño, mayor será la distancia a la que se desplace.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/63.png', 'Ambos', 'kanto', FALSE, FALSE),
    (64, 'Kadabra', 1.3, 56.5, 'La potencia de su telequinesis es inmensa. Acumula poder psíquico en la estrella de la frente como preparativo de cara a su evolución.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/64.png', 'Ambos', 'kanto', FALSE, FALSE),
    (65, 'Alakazam', 1.5, 48.0, 'Posee unos poderes psíquicos extraordinarios con los que, según se dice, creó las cucharas que lleva en las manos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/65.png', 'Ambos', 'kanto', FALSE, FALSE),
    (66, 'Machop', 0.8, 19.5, 'Siempre rebosante de energía, pasa el tiempo levantando piedras para hacerse aún más fuerte.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/66.png', 'Ambos', 'kanto', FALSE, FALSE),
    (67, 'Machoke', 1.5, 70.5, 'Tiene una complexión tan fuerte que nunca se cansa. Suele ayudar a la gente a cargar objetos pesados.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/67.png', 'Ambos', 'kanto', FALSE, FALSE),
    (68, 'Machamp', 1.6, 130.0, 'Puede dar varios puñetazos de una sola vez gracias a sus cuatro brazos. Golpea más rápido de lo que piensa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/68.png', 'Ambos', 'kanto', FALSE, FALSE),
    (69, 'Bellsprout', 0.7, 4.0, 'Prefiere lugares cálidos y húmedos. Atrapa pequeños Pokémon insectos con sus lianas para devorarlos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/69.png', 'Ambos', 'kanto', FALSE, FALSE),
    (70, 'Weepinbell', 1.0, 6.4, 'Cuando tiene hambre, engulle a todo lo que se mueve. La pobre presa acaba disuelta en sus ácidos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/70.png', 'Ambos', 'kanto', FALSE, FALSE),
    (71, 'Victreebel', 1.7, 15.5, 'Atrae a su presa con un dulce aroma a miel. Una vez atrapada en la boca, la disuelve en tan solo un día, huesos incluidos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/71.png', 'Ambos', 'kanto', FALSE, FALSE),
    (72, 'Tentacool', 0.9, 45.5, 'Su cuerpo está compuesto casi por completo de agua, por lo que resulta muy difícil distinguirlo cuando está sumergido en el mar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/72.png', 'Ambos', 'kanto', FALSE, FALSE),
    (73, 'Tentacruel', 1.6, 55.0, 'Puede estirar y contraer con total libertad sus 80 tentáculos. Con ellos atrapa a sus presas y les inyecta un veneno debilitante.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/73.png', 'Ambos', 'kanto', FALSE, FALSE),
    (74, 'Geodude', 0.4, 20.0, 'Se suele encontrar en senderos de montaña y sitios parecidos. Conviene andar con cuidado para no pisarlo sin querer y provocar su enfado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/74.png', 'Ambos', 'kanto', FALSE, FALSE),
    (75, 'Graveler', 1.0, 105.0, 'Se le suele ver rodando montaña abajo. No evita los obstáculos, sino que los arrolla.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/75.png', 'Ambos', 'kanto', FALSE, FALSE),
    (76, 'Golem', 1.4, 300.0, 'Nada más mudar la piel, su cuerpo se vuelve blando y blanquecino, pero se endurece al poco tiempo de entrar en contacto con el aire.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/76.png', 'Ambos', 'kanto', FALSE, FALSE),
    (77, 'Ponyta', 1.0, 30.0, 'Por extraño que parezca, una vez que alguien se ha hecho merecedor de su confianza, puede tocarle la ardiente crin sin quemarse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/77.png', 'Ambos', 'kanto', FALSE, FALSE),
    (78, 'Rapidash', 1.7, 95.0, 'El ejemplar más rápido se convierte en el líder de la manada y decide tanto el ritmo de galope como su destino.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/78.png', 'Ambos', 'kanto', FALSE, FALSE),
    (79, 'Slowpoke', 1.2, 36.0, 'Hunde la cola en el agua y la usa cual caña de pescar. La sustancia dulce que secreta le sirve de cebo para atraer a sus presas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/79.png', 'Ambos', 'kanto', FALSE, FALSE),
    (80, 'Slowbro', 1.6, 78.5, 'Se volvió bípedo por el impacto que le causó la mordedura del Shellder. Si este se desprende, vuelve a convertirse en un Slowpoke.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/80.png', 'Ambos', 'kanto', FALSE, FALSE),
    (81, 'Magnemite', 0.3, 6.0, 'Se nutre de electricidad. Puede flotar en el aire gracias a las ondas electromagnéticas que emite a través de las unidades de sus extremidades.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/81.png', 'Sin género', 'kanto', FALSE, FALSE),
    (82, 'Magneton', 1.0, 60.0, 'Emite de forma constante una potente fuerza magnética que causa estragos en prácticamente cualquier ordenador al que se acerque.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/82.png', 'Sin género', 'kanto', FALSE, FALSE),
    (83, 'Farfetch’d', 0.8, 15.0, 'Combate empuñando un puerro como arma. La forma de blandirlo es tan variada que ha llegado a generar sus propias escuelas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/83.png', 'Ambos', 'kanto', FALSE, FALSE),
    (84, 'Doduo', 1.4, 39.2, 'Las diminutas alas apenas le permiten volar, pero puede correr a gran velocidad gracias a sus patas hiperdesarrolladas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/84.png', 'Ambos', 'kanto', FALSE, FALSE),
    (85, 'Dodrio', 1.8, 85.2, 'Este Pokémon surge al dividirse una de las cabezas de Doduo. Es capaz de correr por las praderas a 60 km/h.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/85.png', 'Ambos', 'kanto', FALSE, FALSE),
    (86, 'Seel', 1.1, 90.0, 'Le encantan los lugares gélidos y disfruta nadando en aguas a temperaturas en torno a los -10 °C.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/86.png', 'Ambos', 'kanto', FALSE, FALSE),
    (87, 'Dewgong', 1.7, 120.0, 'Su cuerpo es blanco como la nieve. Puede nadar plácidamente en mares gélidos gracias a su resistencia al frío.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/87.png', 'Ambos', 'kanto', FALSE, FALSE),
    (88, 'Grimer', 0.9, 30.0, 'Está hecho de lodo endurecido. Pocos se atreven a tocarlo debido a su pestilencia y composición nociva. Allá por donde pasa no crece la hierba.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/88.png', 'Ambos', 'kanto', FALSE, FALSE),
    (89, 'Muk', 1.2, 30.0, 'Huele tan mal que puede provocar desmayos. Su nariz se ha atrofiado de tal manera que ha perdido por completo el sentido del olfato.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/89.png', 'Ambos', 'kanto', FALSE, FALSE),
    (90, 'Shellder', 0.3, 4.0, 'La concha lo protege de cualquier tipo de ataque. Solo es vulnerable cuando se abre.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/90.png', 'Ambos', 'kanto', FALSE, FALSE),
    (91, 'Cloyster', 1.5, 132.5, 'Una vez que ha cerrado la concha, es imposible abrirla, independientemente de la fuerza que se ejerza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/91.png', 'Ambos', 'kanto', FALSE, FALSE),
    (92, 'Gastly', 1.3, 0.1, 'Con su cuerpo gaseoso puede colarse por donde quiera, aunque con un golpe de viento sale despedido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/92.png', 'Ambos', 'kanto', FALSE, FALSE),
    (93, 'Haunter', 1.6, 0.1, 'Cuando se tiene la sensación de ser observado en la oscuridad sin que haya nadie alrededor, seguro que es porque un Haunter anda cerca.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/93.png', 'Ambos', 'kanto', FALSE, FALSE),
    (94, 'Gengar', 1.5, 40.5, 'Dicen que sale de la oscuridad para robarles el alma a los que se pierden por las montañas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/94.png', 'Ambos', 'kanto', FALSE, FALSE),
    (95, 'Onix', 8.8, 210.0, 'Perfora el suelo a una velocidad de 80 km/h girando y retorciendo su robusto y enorme cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/95.png', 'Ambos', 'kanto', FALSE, FALSE),
    (96, 'Drowzee', 1.0, 32.4, 'Si se duerme siempre en compañía de un Pokémon de esta especie, puede mostrar sueños que haya ingerido con anterioridad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/96.png', 'Ambos', 'kanto', FALSE, FALSE),
    (97, 'Hypno', 1.6, 75.6, 'Conviene evitar el contacto visual en caso de encontrarse con este Pokémon, ya que puede hipnotizar con su péndulo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/97.png', 'Ambos', 'kanto', FALSE, FALSE),
    (98, 'Krabby', 0.4, 6.5, 'Ante el peligro, se camufla con las burbujas que desprende por la boca para parecer más grande.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/98.png', 'Ambos', 'kanto', FALSE, FALSE),
    (99, 'Kingler', 1.3, 60.0, 'Su gran pinza posee una potencia devastadora, pero su peso excesivo la convierte en un estorbo fuera del terreno de combate.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/99.png', 'Ambos', 'kanto', FALSE, FALSE),
    (100, 'Voltorb', 0.5, 10.4, 'Se dice que se camufla como una Poké Ball. Al más mínimo estímulo se autodestruirá.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/100.png', 'Sin género', 'kanto', FALSE, FALSE),
    (101, 'Electrode', 1.2, 66.6, 'Almacena tal cantidad de energía eléctrica en su cuerpo que el más leve impacto puede provocar una gran explosión.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/101.png', 'Sin género', 'kanto', FALSE, FALSE),
    (102, 'Exeggcute', 0.4, 2.5, 'Necesita contar con la totalidad de sus seis miembros para mantener la calma. Si desaparece uno siquiera, le entran ganas de salir huyendo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/102.png', 'Ambos', 'kanto', FALSE, FALSE),
    (103, 'Exeggutor', 2.0, 120.0, 'Puede lanzar ataques psíquicos de gran potencia si sus tres cabezas se ponen de acuerdo. Cuando se nubla el cielo, sus movimientos se ralentizan.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/103.png', 'Ambos', 'kanto', FALSE, FALSE),
    (104, 'Cubone', 0.4, 6.5, 'Lleva puesto el cráneo de su difunta madre. A veces llora en sueños, pero cada lágrima vertida le hace más fuerte.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/104.png', 'Ambos', 'kanto', FALSE, FALSE),
    (105, 'Marowak', 1.0, 45.0, 'Al evolucionar, se ha fusionado con el cráneo de su madre y, además, ha adquirido un carácter agresivo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/105.png', 'Ambos', 'kanto', FALSE, FALSE),
    (106, 'Hitmonlee', 1.5, 49.8, 'Encoge y estira las piernas a su antojo. De hecho, hasta puede propinar una patada a un rival que se encuentre lejos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/106.png', 'Macho', 'kanto', FALSE, FALSE),
    (107, 'Hitmonchan', 1.4, 50.2, 'Sus puñetazos son capaces incluso de cortar el aire, aunque parece necesitar un descanso tras estar luchando durante 3 min.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/107.png', 'Macho', 'kanto', FALSE, FALSE),
    (108, 'Lickitung', 1.2, 65.5, 'Se nutre principalmente de Pokémon insecto, a los que paraliza primero lamiéndolos con su larga lengua y luego engulle de un bocado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/108.png', 'Ambos', 'kanto', FALSE, FALSE),
    (109, 'Koffing', 0.6, 1.0, 'Se nutre de aire contaminado. Al parecer, antaño eran mucho más numerosos en Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/109.png', 'Ambos', 'kanto', FALSE, FALSE),
    (110, 'Weezing', 1.2, 9.5, 'Posee una capacidad de succión inferior a la del Weezing de Galar, pero las toxinas que genera son más potentes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/110.png', 'Ambos', 'kanto', FALSE, FALSE),
    (111, 'Rhyhorn', 1.0, 115.0, 'La cabeza no le da para retener más de una cosa. Si se pone a correr, se le olvida al instante por qué empezó a hacerlo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/111.png', 'Ambos', 'kanto', FALSE, FALSE),
    (112, 'Rhydon', 1.9, 120.0, 'La piel le sirve de escudo protector. Puede vivir en lava líquida a 2000 °C.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/112.png', 'Ambos', 'kanto', FALSE, FALSE),
    (113, 'Chansey', 1.1, 34.6, 'Este Pokémon solía ser lento de reflejos, pero ha desarrollado una gran velocidad para evitar que le roben sus preciados huevos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/113.png', 'Hembra', 'kanto', FALSE, FALSE),
    (114, 'Tangela', 1.0, 35.0, 'Sus lianas despiden una fragancia peculiar. En cierta zona de Galar se usan como aderezo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/114.png', 'Ambos', 'kanto', FALSE, FALSE),
    (115, 'Kangaskhan', 2.2, 80.0, 'Se han documentado casos de Kangaskhan sin crías que han adoptado bebés humanos cuyos padres habían sido víctimas de accidentes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/115.png', 'Hembra', 'kanto', FALSE, FALSE),
    (116, 'Horsea', 0.4, 8.0, 'Nada con la gracilidad de un bailarín, creando remolinos a su paso, y juega con sus congéneres a ver quién forma el más grande.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/116.png', 'Ambos', 'kanto', FALSE, FALSE),
    (117, 'Seadra', 1.2, 25.0, 'Su estrecho morro posee tal fuerza de succión que es capaz de aspirar presas de mayor tamaño y engullirlas enteras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/117.png', 'Ambos', 'kanto', FALSE, FALSE),
    (118, 'Goldeen', 0.6, 15.0, 'La aleta dorsal y las aletas pectorales están tan desarrolladas que actúan como músculos. Puede nadar a una velocidad de cinco nudos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/118.png', 'Ambos', 'kanto', FALSE, FALSE),
    (119, 'Seaking', 1.3, 39.0, 'Perfora las piedras del lecho del río con su cuerno para hacer un nido y que la corriente no arrastre sus huevos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/119.png', 'Ambos', 'kanto', FALSE, FALSE),
    (120, 'Staryu', 0.8, 34.5, 'No le importa que le mordisqueen el cuerpo los Pokémon pez, ya que las partes desgarradas se regeneran casi al instante.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/120.png', 'Sin género', 'kanto', FALSE, FALSE),
    (121, 'Starmie', 1.1, 80.0, 'Starmie absorbe plancton al tiempo que nada por el mar haciendo girar su cuerpo a gran velocidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/121.png', 'Sin género', 'kanto', FALSE, FALSE),
    (122, 'Mr. Mime', 1.3, 54.5, 'Domina con maestría la pantomima. La barrera generada con las ondas que emite por los dedos le permite protegerse de numerosos ataques.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/122.png', 'Ambos', 'kanto', FALSE, FALSE),
    (123, 'Scyther', 1.5, 56.0, 'El territorio de un Scyther se identifica fácilmente por el gran número de árboles talados de forma indiscriminada en una misma zona del bosque.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/123.png', 'Ambos', 'kanto', FALSE, FALSE),
    (124, 'Jynx', 1.4, 40.6, 'Los ejemplares que habitan en Galar poseen una voz tan delicada y hermosa que incluso cuentan con su propio grupo de admiradores.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/124.png', 'Hembra', 'kanto', FALSE, FALSE),
    (125, 'Electabuzz', 1.1, 30.0, 'Al desatarse una tormenta, se reúnen en torno a los árboles de mayor altura y esperan inmóviles a que caiga algún rayo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/125.png', 'Ambos', 'kanto', FALSE, FALSE),
    (126, 'Magmar', 1.3, 44.5, 'Un Pokémon cuyo cuerpo está siempre envuelto en llamas. Es temido porque se lo considera un causante potencial de incendios.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/126.png', 'Ambos', 'kanto', FALSE, FALSE),
    (127, 'Pinsir', 1.5, 55.0, 'Usa la cornamenta a modo de pinza para atrapar a sus presas. Acto seguido, las parte por la mitad o las arroja lejos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/127.png', 'Ambos', 'kanto', FALSE, FALSE),
    (128, 'Tauros', 1.4, 88.4, 'Los Tauros que habitan en la región de Galar son de temperamento irascible y no permiten que los humanos monten en su lomo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/128.png', 'Macho', 'kanto', FALSE, FALSE),
    (129, 'Magikarp', 0.9, 10.0, 'Este Pokémon débil y patético se limita a dejarse llevar por la corriente cuando esta tiene fuerza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/129.png', 'Ambos', 'kanto', FALSE, FALSE),
    (130, 'Gyarados', 6.5, 235.0, 'Cuando monta en cólera, puede quemarlo todo, incluso en medio de la más violenta tormenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/130.png', 'Ambos', 'kanto', FALSE, FALSE),
    (131, 'Lapras', 2.5, 220.0, 'Nada sin problema en aguas heladas gracias a la soberbia resistencia al frío que posee. Su tersa piel es ligeramente fría al tacto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/131.png', 'Ambos', 'kanto', FALSE, FALSE),
    (132, 'Ditto', 0.3, 4.0, 'Cuando se encuentra con otro Ditto, se mueve más rápido de lo normal para intentar adoptar su aspecto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/132.png', 'Sin género', 'kanto', FALSE, FALSE),
    (133, 'Eevee', 0.3, 6.5, 'Su irregular estructura genética alberga el secreto de la capacidad que posee este Pokémon tan especial para adoptar evoluciones muy variadas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/133.png', 'Ambos', 'kanto', FALSE, FALSE),
    (134, 'Vaporeon', 1.0, 29.0, 'La composición celular de su cuerpo es tan similar a la estructura molecular del agua que se vuelve invisible al fundirse en ella.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/134.png', 'Ambos', 'kanto', FALSE, FALSE),
    (135, 'Jolteon', 0.8, 24.5, 'Acumula iones negativos de la atmósfera para lanzar rayos de 10 000 V de potencia.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/135.png', 'Ambos', 'kanto', FALSE, FALSE),
    (136, 'Flareon', 0.9, 25.0, 'Almacena parte del aire que inhala en la saca de fuego de su interior, que llega a calentarse a más de 1700 °C.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/136.png', 'Ambos', 'kanto', FALSE, FALSE),
    (137, 'Porygon', 0.8, 36.5, 'Durante los últimos años, ha estado muy activo en el ciberespacio comprobando que no haya datos sospechosos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/137.png', 'Sin género', 'kanto', FALSE, FALSE),
    (138, 'Omanyte', 0.4, 7.5, 'Un Pokémon de la era prehistórica, ahora extinto. Solía nadar moviendo sus diez tentáculos para desplazarse por el agua como si flotara.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/138.png', 'Ambos', 'kanto', FALSE, FALSE),
    (139, 'Omastar', 1.0, 35.0, 'Posee unos colmillos afilados con los que puede partir piedras, pero solo ataca a presas que se hallan al alcance de sus tentáculos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/139.png', 'Ambos', 'kanto', FALSE, FALSE),
    (140, 'Kabuto', 0.5, 11.5, 'Se consideraba extinto, pero, al parecer, existen determinadas zonas en las que es posible hallar ejemplares con facilidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/140.png', 'Ambos', 'kanto', FALSE, FALSE),
    (141, 'Kabutops', 1.3, 40.5, 'Se desconoce el motivo de la extinción de este feroz Pokémon prehistórico que habitaba en los cálidos mares de antaño.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/141.png', 'Ambos', 'kanto', FALSE, FALSE),
    (142, 'Aerodactyl', 1.8, 59.0, 'Sus colmillos, afilados como sierras, pueden hacer trizas incluso la piel de Pokémon de tipo Acero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/142.png', 'Ambos', 'kanto', FALSE, FALSE),
    (143, 'Snorlax', 2.1, 460.0, 'Este Pokémon tiene un estómago a prueba de bomba, por lo que es capaz de ingerir incluso comida podrida o mohosa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/143.png', 'Ambos', 'kanto', FALSE, FALSE),
    (144, 'Articuno', 1.7, 55.4, 'Posee el poder de controlar el hielo a su antojo. Se dice que este Pokémon habita en montañas de nieves perpetuas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/144.png', 'Sin género', 'kanto', TRUE, FALSE),
    (145, 'Zapdos', 1.6, 52.6, 'Una de las aves legendarias. Dicen que, cuando este Pokémon frota las alas, cae al instante un relámpago del cielo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/145.png', 'Sin género', 'kanto', TRUE, FALSE),
    (146, 'Moltres', 2.0, 60.0, 'Se cuenta que alguna vez ha iluminado el camino con sus alas flamígeras para rescatar a alguien que se había perdido en la montaña.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/146.png', 'Sin género', 'kanto', TRUE, FALSE),
    (147, 'Dratini', 1.8, 3.3, 'Durante mucho tiempo se dudó de su existencia. La pequeña protuberancia de la frente es en realidad un cuerno incipiente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/147.png', 'Ambos', 'kanto', FALSE, FALSE),
    (148, 'Dragonair', 4.0, 16.5, 'Acumula energía en las esferas de la cola para controlar el clima. La sutil aura que lo rodea le confiere un aspecto misterioso y místico.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/148.png', 'Ambos', 'kanto', FALSE, FALSE),
    (149, 'Dragonite', 2.2, 210.0, 'Se lo conoce como el Avatar de la Mar. Muchos barcos lucen una talla de Dragonite como mascarón de proa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/149.png', 'Ambos', 'kanto', FALSE, FALSE),
    (150, 'Mewtwo', 2.0, 122.0, 'Su ADN es casi el mismo que el de Mew. Sin embargo, su tamaño y carácter son muy diferentes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/150.png', 'Sin género', 'kanto', TRUE, FALSE),
    (151, 'Mew', 0.4, 4.0, 'Si se observa a través de un microscopio, puede distinguirse cuán corto, fino y delicado es el pelaje de este Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/151.png', 'Sin género', 'kanto', FALSE, TRUE),
    (152, 'Chikorita', 0.9, 6.4, 'Al luchar, Chikorita agita la hoja que tiene para mantener a raya al rival. Pero, al mismo tiempo, libera una suave fragancia que apacigua el encuentro y crea un ambiente agradable y de amistad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/152.png', 'Ambos', 'johto', FALSE, FALSE),
    (153, 'Bayleef', 1.2, 15.8, 'Bayleef tiene un collar de hojas alrededor del cuello y un brote de un árbol en cada una de ellas. La fragancia que desprenden estos brotes anima a la gente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/153.png', 'Ambos', 'johto', FALSE, FALSE),
    (154, 'Meganium', 1.8, 100.5, 'La fragancia de la flor de Meganium aplaca y suaviza los ánimos. Al luchar, este Pokémon libera mayor cantidad de esencia para disminuir el ánimo de combate de su oponente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/154.png', 'Ambos', 'johto', FALSE, FALSE),
    (155, 'Cyndaquil', 0.5, 7.9, 'Cyndaquil se protege soltando llamas por el lomo. Cuando está enfadado, las llamas son fieras, pero, si está cansado, solo consigue echar algunas chispas que no llegan a cuajar en una completa combustión.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/155.png', 'Ambos', 'johto', FALSE, FALSE),
    (156, 'Quilava', 0.9, 19.0, 'Quilava mantiene a sus rivales a raya con la intensidad de sus llamas y las ráfagas de aire ígneo que producen. También aprovecha su espectacular agilidad para esquivar ataques a la vez que abrasa al rival con sus llamas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/156.png', 'Ambos', 'johto', FALSE, FALSE),
    (157, 'Typhlosion', 1.7, 79.5, 'Typhlosion se oculta tras un trémulo haz de calor que crea mediante sus intensas y sofocantes llamaradas. Este Pokémon causa explosiones de fuego que reducen todo a cenizas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/157.png', 'Ambos', 'johto', FALSE, FALSE),
    (158, 'Totodile', 0.6, 9.5, 'Totodile tiene cuerpo pequeño, pero fuertes mandíbulas. A veces, piensa que solo está dando un mordisquito y hace unas heridas bastante considerables.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/158.png', 'Ambos', 'johto', FALSE, FALSE),
    (159, 'Croconaw', 1.1, 25.0, 'Una vez que Croconaw le ha clavado los colmillos a su presa, es imposible que escape porque los tiene hacia adentro como si fueran anzuelos. Cuando Croconaw hinca los dientes, no hay escapatoria.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/159.png', 'Ambos', 'johto', FALSE, FALSE),
    (160, 'Feraligatr', 2.3, 88.8, 'Feraligatr intimida a sus oponentes abriendo las grandes fauces que tiene. En combate, golpea el suelo bruscamente con las gruesas y fuertes patas traseras que tiene para cargar contra su rival a una velocidad de vértigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/160.png', 'Ambos', 'johto', FALSE, FALSE),
    (161, 'Sentret', 0.8, 6.0, 'Sentret no duerme a menos que otro haga guardia. El que hace de centinela lo despertará al mínimo signo de peligro. Cuando este Pokémon se separa de su manada, es incapaz de echarse a dormir, presa del miedo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/161.png', 'Ambos', 'johto', FALSE, FALSE),
    (162, 'Furret', 1.8, 32.5, 'Furret es de constitución muy delgada. En combate le resulta útil porque puede escabullirse con habilidad por cualquier huequito y escapar. A pesar de que tiene patas cortas, es ágil y veloz.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/162.png', 'Ambos', 'johto', FALSE, FALSE),
    (163, 'Hoothoot', 0.7, 21.2, 'Todos los días empieza a ulular a la misma hora, por lo que algunos Entrenadores lo usan a modo de reloj.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/163.png', 'Ambos', 'johto', FALSE, FALSE),
    (164, 'Noctowl', 1.6, 40.8, 'Cuando necesita pensar, gira la cabeza 180° para agudizar su capacidad intelectual.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/164.png', 'Ambos', 'johto', FALSE, FALSE),
    (165, 'Ledyba', 1.0, 10.8, 'Un Pokémon bastante temeroso. Junto con sus congéneres, protege su nido usando Reflejo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/165.png', 'Ambos', 'johto', FALSE, FALSE),
    (166, 'Ledian', 1.4, 35.6, 'Vuela por el cielo nocturno esparciendo un polvo brillante. Dicen que entrar en contacto con este polvo trae buena suerte.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/166.png', 'Ambos', 'johto', FALSE, FALSE),
    (167, 'Spinarak', 0.5, 8.5, 'El veneno de sus colmillos no es demasiado tóxico, pero basta para mantener inmovilizadas a las presas que caen en sus redes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/167.png', 'Ambos', 'johto', FALSE, FALSE),
    (168, 'Ariados', 1.1, 33.5, 'Captura a sus presas con el hilo que segrega. Al caer la noche, abandona su tela y sale a cazar activamente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/168.png', 'Ambos', 'johto', FALSE, FALSE),
    (169, 'Crobat', 1.8, 75.0, 'Controla de forma independiente cada una de sus cuatro alas. Puede revolotear por cuevas estrechas sin aminorar la velocidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/169.png', 'Ambos', 'johto', FALSE, FALSE),
    (170, 'Chinchou', 0.5, 12.0, 'En el oscuro fondo del océano, su único modo de comunicarse son las luces parpadeantes que emite por las antenas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/170.png', 'Ambos', 'johto', FALSE, FALSE),
    (171, 'Lanturn', 1.2, 22.5, 'Ciega a sus presas con una luz intensa. Si tiene la ocasión, les propina una descarga eléctrica.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/171.png', 'Ambos', 'johto', FALSE, FALSE),
    (172, 'Pichu', 0.3, 2.0, 'Las bolsas de electricidad de sus mejillas son muy pequeñas y, a poco que se desborden, recibe una fuerte descarga.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/172.png', 'Ambos', 'johto', FALSE, FALSE),
    (173, 'Cleffa', 0.3, 3.0, 'Por su inusual forma estrellada, la gente cree que procede de un meteorito que cayó a la tierra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/173.png', 'Ambos', 'johto', FALSE, FALSE),
    (174, 'Igglybuff', 0.3, 1.0, 'Se desplaza dando botes con su cuerpo mullido. Cuando aumenta su temperatura corporal, se va poniendo de un color rosa cada vez más intenso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/174.png', 'Ambos', 'johto', FALSE, FALSE),
    (175, 'Togepi', 0.3, 1.5, 'Se lo considera un símbolo de buena suerte y, según se dice, su cascarón está lleno de alegría.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/175.png', 'Ambos', 'johto', FALSE, FALSE),
    (176, 'Togetic', 0.6, 3.2, 'Si no está con gente amable, se entristece. Puede flotar en el aire sin mover las alas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/176.png', 'Ambos', 'johto', FALSE, FALSE),
    (177, 'Natu', 0.2, 2.0, 'Se desplaza dando saltitos porque sus alas no han crecido lo suficiente. Siempre está mirando algo fijamente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/177.png', 'Ambos', 'johto', FALSE, FALSE),
    (178, 'Xatu', 1.5, 15.0, 'Este extraño Pokémon puede ver el pasado y el futuro. Se pasa el día mirando al sol.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/178.png', 'Ambos', 'johto', FALSE, FALSE),
    (179, 'Mareep', 0.6, 7.8, 'Su lana acumula electricidad estática con la fricción. Al ser tan adorable, la gente se acerca para acariciarlo y se lleva un doloroso chispazo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/179.png', 'Ambos', 'johto', FALSE, FALSE),
    (180, 'Flaaffy', 0.8, 13.3, 'Su lana sedosa acumula tanta electricidad que algunas partes de su cuerpo se han quedado desprovistas de pelo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/180.png', 'Ambos', 'johto', FALSE, FALSE),
    (181, 'Ampharos', 1.4, 61.5, 'Su cola emite un brillo claro e intenso. Se lo venera desde tiempos remotos como guía de los marineros.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/181.png', 'Ambos', 'johto', FALSE, FALSE),
    (182, 'Bellossom', 0.4, 5.8, 'Los Bellossom se reúnen en ocasiones para ejecutar una especie de danza, considerada un ritual para invocar al sol.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/182.png', 'Ambos', 'johto', FALSE, FALSE),
    (183, 'Marill', 0.4, 8.5, 'Su pelaje repele el agua, lo que evita que pase frío al salir de mares gélidos porque se seca al momento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/183.png', 'Ambos', 'johto', FALSE, FALSE),
    (184, 'Azumarill', 0.8, 28.5, 'Crea burbujas llenas de aire con las que cubre a los Azurill cuando juegan en el río.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/184.png', 'Ambos', 'johto', FALSE, FALSE),
    (185, 'Sudowoodo', 1.2, 38.0, 'Finge ser un árbol para evitar que lo ataquen. Odia tanto el agua que desaparecerá si empieza a llover.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/185.png', 'Ambos', 'johto', FALSE, FALSE),
    (186, 'Politoed', 1.1, 33.9, 'Los machos emiten gritos muy potentes. Las hembras sienten predilección por los de voz grave e imponente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/186.png', 'Ambos', 'johto', FALSE, FALSE),
    (187, 'Hoppip', 0.4, 0.5, 'Este Pokémon flota en el aire y se deja llevar. Cuando percibe que el viento va a cambiar a fuerte, Hoppip entrelaza sus hojas con otros Hoppip para hacer resistencia y evitar salir volando por la fuerza de la corriente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/187.png', 'Ambos', 'johto', FALSE, FALSE),
    (188, 'Skiploom', 0.6, 1.0, 'Skiploom florece cuando la temperatura llega a 18 °C. La apertura de los pétalos varía según la temperatura que haga. Por este motivo, la gente lo usa a veces a modo de termómetro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/188.png', 'Ambos', 'johto', FALSE, FALSE),
    (189, 'Jumpluff', 0.8, 3.0, 'Jumpluff se vale de los cálidos vientos del sur para volar a tierras lejanas. Si llega a zonas de aire frío en pleno vuelo, descenderá y tomará tierra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/189.png', 'Ambos', 'johto', FALSE, FALSE),
    (190, 'Aipom', 0.8, 11.5, 'Sube a las copas de los árboles para buscar presas. Si encuentra un Bounsweet, su manjar predilecto, se alboroza y se abalanza sobre él.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/190.png', 'Ambos', 'johto', FALSE, FALSE),
    (191, 'Sunkern', 0.3, 1.8, 'Sunkern intenta moverse lo menos posible para conservar todos los nutrientes que ha guardado en su interior y poder evolucionar. Ni come siquiera; se alimenta solo del rocío de la mañana.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/191.png', 'Ambos', 'johto', FALSE, FALSE),
    (192, 'Sunflora', 0.8, 8.5, 'Sunflora transforma la energía solar en nutrientes. De día, cuando hace calor, está en continuo movimiento. Solo para cuando comienza a anochecer.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/192.png', 'Ambos', 'johto', FALSE, FALSE),
    (193, 'Yanma', 1.2, 38.0, 'Yanma tiene un ángulo de visión de 360° sin mover los ojos. Es un gran volador, experto en hacer repentinas paradas y cambios de dirección en el aire. Aprovecha la habilidad que tiene de volar para lanzarse sobre su presa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/193.png', 'Ambos', 'johto', FALSE, FALSE),
    (194, 'Wooper', 0.4, 8.5, 'Cuando se desplaza en tierra firme, cubre su cuerpo con una membrana mucosa y venenosa para mantener hidratada la piel.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/194.png', 'Ambos', 'johto', FALSE, FALSE),
    (195, 'Quagsire', 1.4, 75.0, 'Su cuerpo siempre resulta escurridizo al tacto. Suele chocarse contra el lecho del río al nadar, pero no le importa demasiado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/195.png', 'Ambos', 'johto', FALSE, FALSE),
    (196, 'Espeon', 0.9, 26.5, 'Lucha con los poderes psíquicos que brotan de la esfera de su frente, que se oscurece cuando su energía disminuye.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/196.png', 'Ambos', 'johto', FALSE, FALSE),
    (197, 'Umbreon', 1.0, 27.0, 'En las noches de luna llena, o cuando se exalta, le empiezan a brillar los anillos de color dorado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/197.png', 'Ambos', 'johto', FALSE, FALSE),
    (198, 'Murkrow', 0.5, 2.1, 'Busca objetos brillantes para su patrón. No cuenta con muchas simpatías, pues la gente lo considera ave de mal agüero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/198.png', 'Ambos', 'johto', FALSE, FALSE),
    (199, 'Slowking', 2.0, 79.5, 'Es capaz de dar respuesta a cualquier cuestión que se le formule, pero, por desgracia, nadie logra descifrar una sola palabra de lo que dice.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/199.png', 'Ambos', 'johto', FALSE, FALSE),
    (200, 'Misdreavus', 0.7, 1.0, 'Disfruta imitando llantos humanos para asustar a la gente. Los valientes no le caen demasiado bien.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/200.png', 'Ambos', 'johto', FALSE, FALSE),
    (201, 'Unown', 0.5, 5.0, 'Estos Pokémon tienen forma de caracteres antiguos. No se sabe qué surgió primero, si la vieja escritura o los distintos Unown. Esta cuestión sigue siendo objeto de estudio, pero aún no se ha averiguado nada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/201.png', 'Sin género', 'johto', FALSE, FALSE),
    (202, 'Wobbuffet', 1.3, 28.5, 'Para mantener oculta su negra cola, vive en silencio en la oscuridad. Nunca ataca primero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/202.png', 'Ambos', 'johto', FALSE, FALSE),
    (203, 'Girafarig', 1.5, 41.5, 'La cabeza trasera de Girafarig tiene un cerebro muy pequeño para pensar, pero, como no le hace falta dormir, al menos puede hacer de centinela las 24 horas del día.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/203.png', 'Ambos', 'johto', FALSE, FALSE),
    (204, 'Pineco', 0.6, 7.2, 'Usa saliva para adherir corteza de árbol a su cuerpo y así aumentar de volumen. Con la edad puede alcanzar un tamaño gigantesco.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/204.png', 'Ambos', 'johto', FALSE, FALSE),
    (205, 'Forretress', 1.2, 125.8, 'El momento en el que engulle a su presa es el único instante donde muestra su cuerpo, pero hasta ahora ningún humano lo ha visto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/205.png', 'Ambos', 'johto', FALSE, FALSE),
    (206, 'Dunsparce', 1.5, 14.0, 'Habita en madrigueras laberínticas. Gracias a su capacidad para ubicarse por el olor de la tierra que lo rodea, nunca se pierde.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/206.png', 'Ambos', 'johto', FALSE, FALSE),
    (207, 'Gligar', 1.1, 64.8, 'Gligar planea por el aire sin hacer ningún ruido, como si fuera patinando. Este Pokémon se agarra a la cara de su rival con las patas traseras, con forma de garra, y las pinzas de las delanteras y le inyecta veneno por el aguijón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/207.png', 'Ambos', 'johto', FALSE, FALSE),
    (208, 'Steelix', 9.2, 400.0, 'Se cree que su cuerpo se ha ido transformando por el hierro acumulado en la tierra que ha ingerido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/208.png', 'Ambos', 'johto', FALSE, FALSE),
    (209, 'Snubbull', 0.6, 7.8, 'A pesar de su aspecto, es muy tímido y afable. A menudo es objeto de burla cuando se junta con Pokémon Perrito.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/209.png', 'Ambos', 'johto', FALSE, FALSE),
    (210, 'Granbull', 1.4, 48.7, 'Es muy popular entre la gente joven, pero su personalidad afable y algo miedosa hacen de él un pésimo guardián.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/210.png', 'Ambos', 'johto', FALSE, FALSE),
    (211, 'Qwilfish', 0.5, 3.9, 'Las pequeñas púas que cubren su cuerpo eran escamas. Inyectan una toxina que hace perder el conocimiento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/211.png', 'Ambos', 'johto', FALSE, FALSE),
    (212, 'Scizor', 1.8, 118.0, 'Su potencia de ataque, que asombra dada su delgadez, se debe a que sus músculos están hechos de metal.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/212.png', 'Ambos', 'johto', FALSE, FALSE),
    (213, 'Shuckle', 0.6, 20.5, 'Las bayas que almacena en su caparazón con forma de vasija se convierten al final en un espeso zumo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/213.png', 'Ambos', 'johto', FALSE, FALSE),
    (214, 'Heracross', 1.5, 54.0, 'Este Pokémon muestra una fuerza hercúlea, que le permite levantar cien veces su propio peso sin inmutarse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/214.png', 'Ambos', 'johto', FALSE, FALSE),
    (215, 'Sneasel', 0.9, 28.0, 'Es un Pokémon de naturaleza astuta y fiera. Se cuela en los nidos de otros Pokémon cuando no están y roba sus huevos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/215.png', 'Ambos', 'johto', FALSE, FALSE),
    (216, 'Teddiursa', 0.6, 8.8, 'A Teddiursa le encanta chuparse las palmas impregnadas de dulce miel. Este Pokémon fabrica su propia miel mezclando frutos y el polen que recoge Beedrill.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/216.png', 'Ambos', 'johto', FALSE, FALSE),
    (217, 'Ursaring', 1.8, 125.8, 'En los bosques habitados por Ursaring, dicen que abundan los arroyos y árboles gigantes en los que guardan su alimento. Este Pokémon se dedica todos los días a pasear por el bosque para buscar comida y guardarla.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/217.png', 'Ambos', 'johto', FALSE, FALSE),
    (218, 'Slugma', 0.7, 35.0, 'Slugma no tiene sangre en su organismo, sino ardiente magma que hace circular por todo el cuerpo los nutrientes y el oxígeno que necesitan sus órganos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/218.png', 'Ambos', 'johto', FALSE, FALSE),
    (219, 'Magcargo', 0.8, 55.0, 'Magcargo tiene una temperatura corporal de 1000 °C aproximadamente. El agua se evapora al contacto con él. Si llueve, las gotas que le rozan se transforman en vapor al instante y crean una densa niebla.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/219.png', 'Ambos', 'johto', FALSE, FALSE),
    (220, 'Swinub', 0.4, 6.5, 'Si percibe un aroma tentador, se lanza de cabeza sin pensárselo dos veces para hallar su origen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/220.png', 'Ambos', 'johto', FALSE, FALSE),
    (221, 'Piloswine', 1.1, 55.8, 'Aunque tiene las patas cortas, sus fuertes pezuñas le permiten caminar por la nieve sin resbalar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/221.png', 'Ambos', 'johto', FALSE, FALSE),
    (222, 'Corsola', 0.6, 5.0, 'Habita en mares cálidos. Antiguamente vivían en las aguas costeras de Galar un gran número de ejemplares.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/222.png', 'Ambos', 'johto', FALSE, FALSE),
    (223, 'Remoraid', 0.6, 12.0, 'Usa su aleta dorsal a modo de ventosa para aferrarse a un Mantine en busca de restos de comida.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/223.png', 'Ambos', 'johto', FALSE, FALSE),
    (224, 'Octillery', 0.9, 28.5, 'Atrapa a sus enemigos con los tentáculos y después los golpea con su dura cabeza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/224.png', 'Ambos', 'johto', FALSE, FALSE),
    (225, 'Delibird', 0.9, 16.0, 'Tiene la costumbre de compartir su comida con todo el mundo, sea humano o Pokémon, por lo que está constantemente en busca de alimento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/225.png', 'Ambos', 'johto', FALSE, FALSE),
    (226, 'Mantine', 2.1, 220.0, 'Mientras nada plácidamente, no le importa que los Remoraid se aferren a él para comerse sus sobras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/226.png', 'Ambos', 'johto', FALSE, FALSE),
    (227, 'Skarmory', 1.7, 50.5, 'Aparece a menudo en escudos heráldicos, pues se pueden forjar espadas a partir de las plumas que pierde.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/227.png', 'Ambos', 'johto', FALSE, FALSE),
    (228, 'Houndour', 0.6, 10.8, 'Los escalofriantes aullidos que profiere justo antes del alba son para señalar la presencia de su manada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/228.png', 'Ambos', 'johto', FALSE, FALSE),
    (229, 'Houndoom', 1.4, 35.0, 'Su rasgo distintivo son los escalofriantes aullidos que profiere. Antiguamente, era temido y considerado un emisario del inframundo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/229.png', 'Ambos', 'johto', FALSE, FALSE),
    (230, 'Kingdra', 1.8, 152.0, 'Las escamas que se le desprenden poseen una calidad tan excelsa y un resplandor tan intenso que han sido ofrecidas a la realeza como regalos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/230.png', 'Ambos', 'johto', FALSE, FALSE),
    (231, 'Phanpy', 0.5, 33.5, 'Phanpy se vale de la trompa para ducharse. Cuando varios se agrupan, se dedican a echarse agua unos a otros. Es muy fácil ver a estos Pokémon secándose cerca del agua.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/231.png', 'Ambos', 'johto', FALSE, FALSE),
    (232, 'Donphan', 1.1, 120.0, 'Si Donphan tuviera que dar un golpe con todo el cuerpo, con lo robusto que es echaría abajo hasta una casa. Estos Pokémon usan su fuerza para ayudar a despejar pasos de montaña cuando hay piedras o lodo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/232.png', 'Ambos', 'johto', FALSE, FALSE),
    (233, 'Porygon2', 0.6, 32.5, 'Al dotarlo de inteligencia artificial, desarrolló un misterioso lenguaje que solo los miembros de su especie son capaces de comprender.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/233.png', 'Sin género', 'johto', FALSE, FALSE),
    (234, 'Stantler', 1.4, 71.2, 'Hace tiempo, se comerciaba con la magnífica cornamenta de Stantler. Se vendía como obra de arte a alto precio. Los interesados en cornamentas de valor incalculable empezaron a cazarlos y casi provocan su extinción.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/234.png', 'Ambos', 'johto', FALSE, FALSE),
    (235, 'Smeargle', 1.2, 58.0, 'Dibuja marcas con el líquido que secreta por la cola. Algunos de sus admiradores han llegado a pagar auténticas fortunas por ellas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/235.png', 'Ambos', 'johto', FALSE, FALSE),
    (236, 'Tyrogue', 0.7, 21.0, 'Su pequeño tamaño no debe ser motivo para subestimarlo, ya que se liará de inmediato a golpes con cualquier rival que estime oportuno.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/236.png', 'Macho', 'johto', FALSE, FALSE),
    (237, 'Hitmontop', 1.4, 48.0, 'Tras hacer el pino para desconcertar a su rival, comienza a propinar sus espectaculares patadas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/237.png', 'Macho', 'johto', FALSE, FALSE),
    (238, 'Smoochum', 0.4, 6.0, 'Este Pokémon rebosante de curiosidad lo toca todo con los labios para determinar qué cosas le gustan y cuáles no.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/238.png', 'Hembra', 'johto', FALSE, FALSE),
    (239, 'Elekid', 0.6, 23.5, 'No se le da bien acumular electricidad, por lo que se cuela en las casas en busca de enchufes para alimentarse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/239.png', 'Ambos', 'johto', FALSE, FALSE),
    (240, 'Magby', 0.7, 21.4, 'Vive en los alrededores de los volcanes. Al final del día, se baña en magma para aliviar el cansancio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/240.png', 'Ambos', 'johto', FALSE, FALSE),
    (241, 'Miltank', 1.2, 75.5, 'Si no se ordeña a Miltank a diario, enferma. El sabor de la leche que produce cambia según la época del año.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/241.png', 'Hembra', 'johto', FALSE, FALSE),
    (242, 'Blissey', 1.5, 46.8, 'Pone unos extraños huevos llenos de felicidad. Dicen que aquellos que los prueban se vuelven amables con todo el mundo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/242.png', 'Hembra', 'johto', FALSE, FALSE),
    (243, 'Raikou', 1.9, 178.0, 'Raikou tiene la velocidad del rayo. Los rugidos de este Pokémon emiten ondas de choque que se esparcen vibrando por el aire y sacuden el suelo como si fueran auténticas descargas de rayo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/243.png', 'Sin género', 'johto', TRUE, FALSE),
    (244, 'Entei', 2.1, 198.0, 'Entei contiene el fulgor del magma en su interior. Se cree que este Pokémon nació de la erupción de un volcán. Escupe numerosas ráfagas de fuego que devoran y reducen a cenizas todo lo que tocan.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/244.png', 'Sin género', 'johto', TRUE, FALSE),
    (245, 'Suicune', 2.0, 187.0, 'Suicune emana la pureza de los manantiales. Suele corretear por el campo con gran elegancia. Este Pokémon tiene el poder de purificar el agua contaminada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/245.png', 'Sin género', 'johto', TRUE, FALSE),
    (246, 'Larvitar', 0.6, 72.0, 'Se alimenta de tierra. Después de devorar el equivalente a una montaña, se duerme y empieza a crecer.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/246.png', 'Ambos', 'johto', FALSE, FALSE),
    (247, 'Pupitar', 1.2, 152.0, 'No se está quieto ni aun siendo una pupa. Sus extremidades ya se han formado bajo su robusta coraza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/247.png', 'Ambos', 'johto', FALSE, FALSE),
    (248, 'Tyranitar', 2.0, 202.0, 'Sus estrepitosos pasos derrumban montañas y hacen que el terreno a su alrededor cambie drásticamente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/248.png', 'Ambos', 'johto', FALSE, FALSE),
    (249, 'Lugia', 5.2, 216.0, 'La fuerza que tiene Lugia en las alas es devastadora; con nada que las bata es capaz de derribar edificios enteros. Por eso mismo, prefiere vivir donde no haya nadie, en lo más profundo del mar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/249.png', 'Sin género', 'johto', TRUE, FALSE),
    (250, 'Ho-Oh', 3.8, 199.0, 'El plumaje de Ho-Oh contiene siete colores que pueden apreciarse según el ángulo desde el que les dé la luz. Dicen que sus plumas dan felicidad a quienes las llevan y, también, que este Pokémon vive a los pies del arco iris.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/250.png', 'Sin género', 'johto', TRUE, FALSE),
    (251, 'Celebi', 0.6, 5.0, 'Vino del futuro haciendo un viaje en el tiempo. Además de curar las heridas, posee la capacidad de revitalizar la hierba y los árboles.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/251.png', 'Sin género', 'johto', FALSE, TRUE),
    (252, 'Treecko', 0.5, 5.0, 'Treecko es tranquilo y tiene gran capacidad de autocontrol; no pierde la calma en ninguna situación. Si algún rival se le queda mirando fijamente, le devolverá la mirada sin ceder ni lo más mínimo de su territorio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/252.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (253, 'Grovyle', 0.9, 21.6, 'Este Pokémon revolotea de rama en rama con maestría. Cuando Grovyle va volando por el bosque, no hay quien lo alcance por muy rápido que sea.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/253.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (254, 'Sceptile', 1.7, 52.2, 'A Sceptile le crecen en la espalda unas semillas llenas de nutrientes que sirven para revitalizar los árboles. De hecho, se dedica a cuidarlos con mimo para que crezcan bien.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/254.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (255, 'Torchic', 0.4, 2.5, 'Torchic tiene un lugar en el interior de su organismo en el que guarda la llama que posee. Si le das un abrazo, arderá encantado. Este Pokémon está recubierto totalmente de sedoso plumón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/255.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (256, 'Combusken', 0.9, 19.5, 'Combusken lucha haciendo uso de las abrasadoras llamas que expulsa por el pico y de unas patadas fulminantes. Este Pokémon emite un sonido muy fuerte y molesto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/256.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (257, 'Blaziken', 1.9, 52.0, 'Blaziken tiene unas piernas tan fuertes que puede saltar por encima de un edificio de 30 pisos con facilidad. Además, da unos puñetazos fulminantes que dejan al oponente chamuscado y lleno de tizne.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/257.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (258, 'Mudkip', 0.4, 7.6, 'En el agua, Mudkip usa las branquias que tiene en los mofletes para respirar. Cuando tiene que enfrentarse a una situación delicada en combate, desata una fuerza asombrosa con la que puede destruir rocas incluso mayores que él.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/258.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (259, 'Marshtomp', 0.7, 28.0, 'Marshtomp se desplaza más rápido por el lodo que por el agua. Los cuartos traseros de este Pokémon muestran un desarrollo más que evidente, lo que le permite andar solo sobre las patas traseras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/259.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (260, 'Swampert', 1.5, 81.9, 'Swampert puede predecir tormentas al percibir con las aletas los sutiles cambios que producen las olas y las corrientes. Si está a punto de estallar una tormenta, empezará a apilar piedras para resguardarse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/260.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (261, 'Poochyena', 0.5, 13.6, 'Poochyena es un Pokémon omnívoro. Se come lo que sea. Le caracteriza el gran tamaño de sus colmillos respecto al resto del cuerpo. Este Pokémon hace que se le erice la cola para intentar intimidar a su rival.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/261.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (262, 'Mightyena', 1.0, 37.0, 'Mightyena se desplaza y vive con su jauría en estado salvaje. Por eso, acostumbrado a esta libertad, obedece al Entrenador al que considere realmente dotado de habilidades superiores al resto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/262.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (263, 'Zigzagoon', 0.4, 17.5, 'El Zigzagoon de Galar desarrolló este aspecto tras adaptarse a otras regiones. Muestra una gran habilidad a la hora de encontrar cosas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/263.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (264, 'Linoone', 0.5, 32.5, 'Abate a sus presas con su vertiginosa velocidad y sus afiladas garras. Los trayectos sinuosos merman notablemente su capacidad para correr.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/264.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (265, 'Wurmple', 0.3, 3.6, 'Wurmple es la presa preferida de Swellow. La forma que tiene de intentar defenderse es apuntar con las púas del lomo al amenazante enemigo y debilitarlo inyectándole veneno.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/265.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (266, 'Silcoon', 0.6, 10.0, 'Se pensaba que Silcoon podía aguantar el hambre y no consumir nada antes de evolucionar. Sin embargo, ahora se cree que sacia su sed bebiendo el agua de la lluvia que se le queda sobre la seda del capullo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/266.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (267, 'Beautifly', 1.0, 28.4, 'Beautifly tiene una boca enorme en espiral que parece una aguja y le resulta muy útil para recolectar polen. Este Pokémon va revoloteando de flor en flor para recogerlo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/267.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (268, 'Cascoon', 0.7, 11.5, 'Si atacan a Cascoon, se queda inmóvil aunque le hayan hecho mucho daño, puesto que, si se moviera, perdería fuerzas para evolucionar. Nunca olvida el daño que le han hecho.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/268.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (269, 'Dustox', 1.2, 31.6, 'Cuando Dustox bate las alas, libera un polvillo fino que en realidad es un peligroso veneno que puede resultar dañino hasta al más fuerte de los fuertes. Las antenas le sirven de radar para buscar comida.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/269.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (270, 'Lotad', 0.5, 2.6, 'El excesivo tamaño y peso de la hoja que tiene en la cabeza ha propiciado que viva flotando en el agua.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/270.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (271, 'Lombre', 1.2, 32.5, 'Vive en las riberas bañadas por el sol. De día duerme sobre un lecho de plantas acuáticas y de noche entra en acción.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/271.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (272, 'Ludicolo', 1.5, 55.0, 'Mover su cuerpo al ritmo de música festiva puede hacer que aumente su fuerza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/272.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (273, 'Seedot', 0.5, 4.0, 'Se cuelga de las ramas con el extremo de la cabeza. A veces se cae cuando soplan vientos fuertes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/273.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (274, 'Nuzleaf', 1.0, 28.0, 'Vive en las oquedades de los árboles grandes. El sonido que emite al usar la hoja de la cabeza como flauta asusta a quienes lo escuchan.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/274.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (275, 'Shiftry', 1.3, 59.6, 'Vive sigiloso en lo más profundo del bosque. Se dice que con sus abanicos puede generar vientos gélidos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/275.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (276, 'Taillow', 0.3, 2.3, 'Taillow es pequeño, está recién salido del nido. Por eso, se siente solo con frecuencia y se pone a piar. Este Pokémon se alimenta de los Wurmple que hay por el bosque.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/276.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (277, 'Swellow', 0.7, 19.8, 'Swellow se preocupa a conciencia del mantenimiento de sus lustrosas alas. Cuando hay dos juntos, el uno se ocupa de limpiarle las alas al otro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/277.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (278, 'Wingull', 0.6, 9.5, 'Aprovecha las corrientes de aire para ganar altura sin necesidad de batir las alas. Anida en acantilados costeros.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/278.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (279, 'Pelipper', 1.2, 28.0, 'Vuela a ras de la superficie marina para llenar su inmenso pico de agua y comida, que se lleva consigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/279.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (280, 'Ralts', 0.4, 6.6, 'Si sus cuernos perciben emociones positivas de personas o Pokémon, su cuerpo se calienta un poco.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/280.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (281, 'Kirlia', 0.8, 20.2, 'Con sus poderes psíquicos puede deformar el espacio a su alrededor y predecir el futuro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/281.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (282, 'Gardevoir', 1.6, 48.4, 'Para proteger a su Entrenador, emplea todo su poder psíquico en crear un pequeño agujero negro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/282.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (283, 'Surskit', 0.5, 1.7, 'Vive en estanques y pantanales donde abunde la flora acuática y compite fieramente con los Dewpider por el territorio y el sustento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/283.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (284, 'Masquerain', 0.8, 3.6, 'Sus grandes antenas en forma de ojos tienden a absorber humedad. Los días de lluvia, se refugia en cavidades de los árboles y espera paciente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/284.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (285, 'Shroomish', 0.4, 4.5, 'Si Shroomish siente peligro, agita el cuerpo y libera esporas venenosas por la cabeza. Estas esporas son tan tóxicas que pueden hacer que se marchiten los árboles y hasta las malas hierbas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/285.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (286, 'Breloom', 1.2, 39.2, 'Las semillas que Breloom tiene prendidas de la cola están formadas por sólidas esporas tóxicas. Comérselas puede resultar fatal. Hasta el más mínimo bocado puede hacerte polvo el estómago.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/286.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (287, 'Slakoth', 0.8, 24.0, 'A Slakoth le late el corazón una vez por minuto. Ya puede pasar lo que pase, que este Pokémon no mueve un dedo. Está todo el día holgazaneando. Es muy raro verlo en movimiento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/287.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (288, 'Vigoroth', 1.4, 46.5, 'A Vigoroth le resulta totalmente imposible estarse quieto. Cuando intenta dormir, la sangre le fluye a velocidad de vértigo y se pone a correr por el bosque de un lado a otro hasta que se calma.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/288.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (289, 'Slaking', 2.0, 130.5, 'Cuando Slaking se instala a vivir en una zona, aparecen círculos de un metro de radio de terreno baldío, pues se come todo el césped que pilla mientras está tumbado boca abajo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/289.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (290, 'Nincada', 0.5, 5.5, 'Pueden pasar más de diez años bajo tierra. Absorben nutrientes de las raíces de los árboles.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/290.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (291, 'Ninjask', 0.8, 12.0, 'Este Pokémon es tan rápido que, según dicen, puede esquivar cualquier ataque. Le encanta alimentarse de la dulce savia de los árboles.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/291.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (292, 'Shedinja', 0.8, 1.2, 'Es un Pokémon muy peculiar: revolotea sin batir las alas, no respira y su cuerpo está hueco por dentro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/292.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (293, 'Whismur', 0.6, 16.3, 'Al chillar, se asusta con su propia voz, lo cual le lleva a gritar más fuerte todavía. Cuando se cansa, se echa a dormir.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/293.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (294, 'Loudred', 1.0, 40.5, 'Su voz no afecta solo al oído. Sus ondas sonoras provocan variaciones de presión en el aire que hacen que sus enemigos salgan despedidos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/294.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (295, 'Exploud', 1.5, 84.0, 'Además de sus bramidos, es capaz de emitir distintos tonos por los tubos de su cuerpo, que le permiten comunicarse con sus semejantes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/295.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (296, 'Makuhita', 1.0, 86.4, 'Dicen que los Entrenadores dan de comer a sus Makuhita un guiso tradicional para que se hagan más fuertes todavía.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/296.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (297, 'Hariyama', 2.3, 253.8, 'No todos los Hariyama son grandotes, recios y fuertes. También los hay de menor tamaño pero mayor agilidad y precisión en los movimientos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/297.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (298, 'Azurill', 0.2, 2.0, 'Es un Pokémon tranquilo, pero, si se le hace enfadar, atacará utilizando la enorme bola que tiene en la cola.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/298.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (299, 'Nosepass', 1.0, 97.0, 'Su potente fuerza magnética le permite atraer a sus presas sin necesidad de moverse, aunque a veces también atrae a sus enemigos naturales.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/299.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (300, 'Skitty', 0.6, 11.0, 'Skitty es conocido por la costumbre que tiene de juguetear y de intentar pillarse la cola. En estado salvaje, habita en las cavidades de los troncos de los árboles del bosque. Es la mascota de muchos por lo dulce que parece.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/300.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (301, 'Delcatty', 1.1, 32.6, 'Delcatty duerme en cualquier lugar sin tener que mantener el nido en un mismo sitio. Si otro Pokémon se le acerca mientras duerme, no se pondrá a luchar con él; simplemente se irá a otro sitio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/301.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (302, 'Sableye', 0.5, 11.0, 'Se alimenta de gemas. En la oscuridad, los ojos le brillan con el destello de las piedras preciosas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/302.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (303, 'Mawile', 0.6, 11.5, 'Sus otrora cuernos de acero se han transformado en grandes fauces con las que muerde a sus enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/303.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (304, 'Aron', 0.4, 60.0, 'Antiguamente se recogía la coraza de acero que este Pokémon desprende al evolucionar y se empleaba para distintos usos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/304.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (305, 'Lairon', 0.9, 120.0, 'Resuelven sus disputas territoriales embistiendo y golpeando con el cuerpo. En sus corazas de acero se pueden apreciar hendiduras y rasguños.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/305.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (306, 'Aggron', 2.1, 360.0, 'En la antigüedad, hubo un monarca que llevaba un casco hecho a imagen de Aggron para que le otorgase fuerza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/306.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (307, 'Meditite', 0.6, 11.2, 'Meditite aumenta su energía interior mediante meditación. Para subsistir le basta con una baya al día. El comer poco entra dentro de su entrenamiento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/307.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (308, 'Medicham', 1.3, 31.5, 'A través de la meditación, Medicham desarrolló su sexto sentido y aprendió a usar poderes psicoquinéticos. Se sabe que este Pokémon puede pasarse un mes meditando y sin comer.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/308.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (309, 'Electrike', 0.6, 15.2, 'Almacena electricidad estática en su pelaje. En estaciones secas, suelta chispas por todo el cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/309.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (310, 'Manectric', 1.5, 40.2, 'Rara vez aparece ante la gente. Dicen que suele colocar su madriguera donde caen rayos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/310.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (311, 'Plusle', 0.4, 4.2, 'Cuando Plusle está animando a su compañero, resplandece y provoca un chisporroteo que le rodea todo el cuerpo. Si su compañero pierde, se pone a chillar a voz en grito.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/311.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (312, 'Minun', 0.4, 4.2, 'Minun empieza a echar chispas cuando está animando a su compañero en pleno combate. Si su compañero está en peligro, el chisporroteo aumenta su intensidad por momentos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/312.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (313, 'Volbeat', 0.7, 17.7, 'La cola de Volbeat brilla como una bombilla. Ante otro de su grupo, la usa para dibujar formas geométricas en la oscuridad del cielo por la noche. Este Pokémon adora el dulce aroma que desprende Illumise.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/313.png', 'Macho', 'hoenn', FALSE, FALSE),
    (314, 'Illumise', 0.6, 17.7, 'Illumise guía en el vuelo a un grupo de iluminados Volbeat para que hagan dibujos en el oscuro cielo. Según dicen, cuanto más complejos sean los dibujos, más le respetan los miembros de su grupo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/314.png', 'Hembra', 'hoenn', FALSE, FALSE),
    (315, 'Roselia', 0.3, 2.0, 'Ataca con sus manos, cada una de las cuales contiene un tipo de veneno diferente. Cuanto más intenso es su aroma, mejor salud tiene.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/315.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (316, 'Gulpin', 0.4, 10.3, 'La mayor parte del cuerpo de Gulpin está ocupado por su estómago. En comparación, el corazón y el cerebro son muy pequeños. Este Pokémon tiene enzimas especiales en el estómago capaces de corroerlo todo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/316.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (317, 'Swalot', 1.7, 80.0, 'Swalot no tiene dientes, así que lo que come se lo traga de una vez; da igual lo que sea. A este Pokémon le cabría un neumático en la boca sin problema.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/317.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (318, 'Carvanha', 0.8, 20.8, 'Los marineros evitan por completo las zonas donde habita este Pokémon de afilados colmillos y fuertes mandíbulas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/318.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (319, 'Sharpedo', 1.8, 88.8, 'Conocido como el Terror de los Mares, ataca sin excepción a todo barco que ose adentrarse en su territorio oceánico.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/319.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (320, 'Wailmer', 2.0, 130.0, 'Cuando traga una gran cantidad de agua marina, se hincha hasta parecer una pelota. Necesita una tonelada de alimento al día.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/320.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (321, 'Wailord', 14.5, 398.0, 'Su descomunal tamaño lo convierte en un Pokémon muy popular. Los enclaves turísticos donde se avistan Wailord son todo un éxito.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/321.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (322, 'Numel', 0.7, 24.0, 'Numel acumula en su interior un magma de 1200 °C. Si se moja, el magma se enfría y se solidifica. Cuando esto ocurre, aumenta su tamaño y se vuelve pesado y lento en sus movimientos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/322.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (323, 'Camerupt', 1.9, 220.0, 'Las jorobas de Camerupt se originaron por una deformación de los huesos. A veces escupen magma líquido, sobre todo cuando el Pokémon se enfada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/323.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (324, 'Torkoal', 0.5, 80.4, 'Se junta con numerosos congéneres para establecer su morada en minas abandonadas, donde se afanan en localizar y extraer carbón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/324.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (325, 'Spoink', 0.7, 30.6, 'Spoink lleva una perla en la cabeza, que sirve para amplificar los poderes psicoquinéticos que tiene. Por eso, está continuamente buscando una perla mayor.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/325.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (326, 'Grumpig', 0.9, 71.5, 'Grumpig utiliza las perlas negras que tiene para usar fantásticos poderes mientras baila de forma muy extraña. Las perlas de este Pokémon están consideradas como valiosas obras de arte.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/326.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (327, 'Spinda', 1.1, 5.0, 'Los dibujos en el pelaje de cada Spinda son diferentes. Esquiva de forma asombrosa los ataques de los rivales gracias a sus tambaleos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/327.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (328, 'Trapinch', 0.7, 15.0, 'Excava fosas cóncavas, de las cuales resulta imposible escapar, y espera a que una presa caiga en su interior.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/328.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (329, 'Vibrava', 1.1, 15.3, 'Para terminar de desarrollar sus alas, se nutre a diario de un gran número de presas, a las que disuelve con ácido antes de devorarlas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/329.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (330, 'Flygon', 2.0, 82.0, 'El batir de sus alas suena como un bello canto de mujer. Se lo conoce como el Alma del Desierto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/330.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (331, 'Cacnea', 0.4, 51.3, 'Cuanto más árido y hostil sea el hábitat de Cacnea, más bonita y aromática será la flor que le crece. Este Pokémon lucha agitando violentamente los brazos cargados de pinchos que tiene.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/331.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (332, 'Cacturne', 1.3, 77.4, 'Cuando alguien se adentra en un desierto por la noche, Cacturne le sigue junto con varios de los suyos. Este Pokémon espera pacientemente a que el viajero se fatigue y no pueda continuar más, vencido por el cansancio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/332.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (333, 'Swablu', 0.4, 1.2, 'Sus alas parecen nubes algodonadas y lo ocultan de sus rivales. Se cree que se volvieron blancas con el paso de las generaciones.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/333.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (334, 'Altaria', 1.1, 20.6, 'Es de carácter amable, pero, si monta en cólera, intimidará al oponente con estridentes chillidos y atacará sin piedad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/334.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (335, 'Zangoose', 1.3, 40.3, 'Zangoose suele caminar a cuatro patas, pero cuando se enfada se pone de pie sobre las traseras y saca las zarpas. Este Pokémon tiene desde hace varias generaciones una áspera rivalidad con Seviper.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/335.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (336, 'Seviper', 2.7, 52.5, 'Seviper tiene una cola que parece una espada y le sirve para dar un sablazo al enemigo y para envenenarlo. Este Pokémon se mantiene firme en la enemistad que siente hacia Zangoose.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/336.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (337, 'Lunatone', 1.0, 168.0, 'Fue descubierto hace 40 años en el lugar donde había caído un meteorito. Le basta fulminar a sus enemigos con la mirada para dormirlos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/337.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (338, 'Solrock', 1.2, 154.0, 'Usa el sol como fuente de energía, por lo que es más poderoso de día. Brilla al rotar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/338.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (339, 'Barboach', 0.4, 1.9, 'Examina los lechos lodosos de los ríos con los largos bigotes que tiene. Está protegido por una capa viscosa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/339.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (340, 'Whiscash', 0.9, 23.6, 'Habita en grandes pantanos. Si se acerca un enemigo, monta en cólera y causa temblores monumentales.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/340.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (341, 'Corphish', 0.6, 11.5, 'Si bien procede del extranjero, ahora se halla en estado salvaje. Puede vivir hasta en los ríos más sucios.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/341.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (342, 'Crawdaunt', 1.1, 32.8, 'Le encanta pelear, debido a su naturaleza. Si alguien se acerca a su madriguera, le propinará una paliza sin ningún tipo de miramiento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/342.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (343, 'Baltoy', 0.5, 21.5, 'Fue hallado en unas ruinas antiguas. Se desplaza girando sobre sí mismo y se mantiene sobre una extremidad incluso cuando duerme.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/343.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (344, 'Claydol', 1.5, 108.0, 'Dicen que surgió de una figurilla de barro hecha por una antigua civilización. Usa telequinesia para levitar y moverse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/344.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (345, 'Lileep', 1.0, 23.8, 'Se ancla a una roca en el lecho marino y atrapa a las presas que se le acercan con sus tentáculos en forma de pétalos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/345.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (346, 'Cradily', 1.5, 60.4, 'Atrapa a sus presas con los tentáculos y enseguida las disuelve con sus jugos gástricos para absorber los nutrientes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/346.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (347, 'Anorith', 0.7, 12.5, 'Puede nadar rápidamente gracias a sus ocho alas que usa a modo de remo. Es uno de los antepasados de los Pokémon insecto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/347.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (348, 'Armaldo', 1.5, 68.2, 'Vive en tierra firme, pero es un hábil nadador. Se zambulle en el agua en busca de presas y las atrapa con sus afiladas pinzas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/348.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (349, 'Feebas', 0.6, 7.4, 'Su apariencia deja bastante que desear, pero es muy resistente y puede sobrevivir con poca agua.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/349.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (350, 'Milotic', 6.2, 162.0, 'Se dice que su hermosa figura puede apaciguar el corazón de aquellos que tengan el ánimo alterado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/350.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (351, 'Castform', 0.3, 0.8, 'El tiempo atmosférico cambia tanto su aspecto como su estado de ánimo. Cuanto más arrecia, más agresivo se vuelve.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/351.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (352, 'Kecleon', 1.0, 22.0, 'Incluso cuando no se está mimetizando, el color de su cuerpo cambia según cómo se encuentre. Un color más intenso indica mayor vitalidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/352.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (353, 'Shuppet', 0.6, 2.3, 'Según un viejo proverbio, conviene mantenerse alejado de aquellas casas a las que se arrime una multitud de Shuppet cuando cae la noche.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/353.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (354, 'Banette', 1.1, 12.5, 'El rencor de haber sido tirado a la basura fue lo que le dio vida. Se dice que puede convertirse de nuevo en muñeco si se le trata con cariño.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/354.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (355, 'Duskull', 0.8, 15.0, 'Se vuelve invisible para acercarse sigilosamente a su presa. Es capaz de atravesar anchos muros.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/355.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (356, 'Dusclops', 1.6, 30.6, 'Busca fuegos fatuos y los absorbe en su cuerpo hueco. Lo que pasa dentro luego es un misterio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/356.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (357, 'Tropius', 2.0, 100.0, 'A la gente le encanta la deliciosa fruta de sus racimos. En las regiones cálidas abundan las granjas que se dedican a criar Tropius.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/357.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (358, 'Chimecho', 0.6, 1.0, 'Cuando hay viento fuerte, Chimecho chilla colgado de la rama de un árbol o de los aleros de un edificio por la ventosa que tiene en la cabeza. Este Pokémon usa la larga cola que tiene para agarrar bayas y comérselas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/358.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (359, 'Absol', 1.2, 47.0, 'Debido a su capacidad para predecir desastres, se lo ha considerado desacertadamente un Pokémon portador de desgracias.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/359.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (360, 'Wynaut', 0.6, 14.0, 'Suelen ir en grupo y, a la hora de dormir, se pegan unos a otros para descansar resguardados en cuevas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/360.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (361, 'Snorunt', 0.7, 16.8, 'Las regiones frías son su hábitat natural. Se encuentra a sus anchas incluso en lugares donde la temperatura alcanza los -100 °C.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/361.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (362, 'Glalie', 1.5, 256.5, 'Congela a sus presas helando en un momento la humedad contenida en el aire que lo rodea.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/362.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (363, 'Spheal', 0.8, 39.5, 'Flota entre las olas para examinar el océano. Si encuentra una presa, avisa enseguida a los Walrein de su manada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/363.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (364, 'Sealeo', 1.1, 87.6, 'Tiene la costumbre de hacer girar en la punta del morro cualquier objeto redondeado, ya sea una Poké Ball o un Spheal.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/364.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (365, 'Walrein', 1.4, 150.6, 'Sus colmillos nunca dejan de crecer. Aunque los pierda en un combate, al cabo de un año ya los habrá regenerado por completo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/365.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (366, 'Clamperl', 0.4, 52.5, 'La perla que contiene vale un potosí. De hecho, su precio puede llegar a ser incluso más de diez veces superior al de la perla de Shellder.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/366.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (367, 'Huntail', 1.7, 27.0, 'Vive en los fondos marinos. Según una leyenda, que un Huntail aparezca varado en la playa es señal de mal augurio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/367.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (368, 'Gorebyss', 1.8, 22.6, 'Absorbe los fluidos corporales de su presa. Los restos que deja caen hasta el lecho marino y se convierten en alimento para otros Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/368.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (369, 'Relicanth', 1.0, 23.4, 'Fue descubierto durante una expedición marina. Se lo considera un fósil viviente, pues no ha cambiado en cien millones de años.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/369.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (370, 'Luvdisc', 0.6, 8.7, 'Vive en los arrecifes de coral de mares cálidos. Dormir entre las ramas de los Corsola es algo por lo que siente una especial predilección.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/370.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (371, 'Bagon', 0.6, 42.1, 'Vive en solitario, sin formar manadas, y posee una cabeza dura como la piedra que le permite hacer añicos rocas enormes de un solo golpe.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/371.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (372, 'Shelgon', 1.1, 110.5, 'Aguanta el hambre sin comer nada. Al parecer, inicia el proceso evolutivo cuando se agota toda la energía que tenía acumulada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/372.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (373, 'Salamence', 1.5, 102.6, 'Feliz de ver cumplido su deseo, surca los cielos con buen ánimo, pero, si se enfada, se vuelve violento e incontrolable.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/373.png', 'Ambos', 'hoenn', FALSE, FALSE),
    (374, 'Beldum', 0.6, 95.2, 'Las células de su cuerpo están hechas de imanes. En lugar de sangre, una fuerza magnética recorre su cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/374.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (375, 'Metang', 1.2, 202.5, 'Levita gracias al magnetismo. Es capaz de sortear escarpadas montañas mientras vuela a altas velocidades en pos de su presa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/375.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (376, 'Metagross', 1.6, 550.0, 'Formado a partir de la unión de dos Metang. Emplea su inteligencia, comparable a la de un superordenador, para derrotar a sus rivales.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/376.png', 'Sin género', 'hoenn', FALSE, FALSE),
    (377, 'Regirock', 1.7, 230.0, 'Su cuerpo rocoso ha sido examinado con las técnicas científicas más avanzadas, pero no se han encontrado ni su cerebro ni su corazón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/377.png', 'Sin género', 'hoenn', TRUE, FALSE),
    (378, 'Regice', 1.8, 175.0, 'Todo su cuerpo está compuesto de hielo. Se dice que surgió bajo una gruesa placa de hielo durante alguna glaciación.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/378.png', 'Sin género', 'hoenn', TRUE, FALSE),
    (379, 'Registeel', 1.9, 205.0, 'Dicen que se formó en el manto terrestre y ascendió a la superficie hace aproximadamente diez mil años.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/379.png', 'Sin género', 'hoenn', TRUE, FALSE),
    (380, 'Latias', 1.4, 40.0, 'Latias tiene un nivel de inteligencia tan alto que es capaz de entender el lenguaje humano. Este Pokémon usa el plumón cristalizado del que está cubierto como peto para refractar la luz y cambiar de aspecto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/380.png', 'Hembra', 'hoenn', TRUE, FALSE),
    (381, 'Latios', 2.0, 60.0, 'Latios solo le abre el corazón a los Entrenadores compasivos. A la hora de volar, este Pokémon pliega las patas delanteras para minimizar la resistencia al aire y supera en velocidad a un avión a reacción.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/381.png', 'Macho', 'hoenn', TRUE, FALSE),
    (382, 'Kyogre', 4.5, 352.0, 'A Kyogre siempre se le ha descrito como el Pokémon que expandió los océanos. Varias leyendas cuentan que libró combates contra Groudon en repetidas ocasiones para tener el control de la energía de la naturaleza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/382.png', 'Sin género', 'hoenn', TRUE, FALSE),
    (383, 'Groudon', 3.5, 950.0, 'Groudon se sirve de la energía de la naturaleza para realizar su Regresión Primigenia y recobrar su apariencia primitiva. Con tal poder, puede crear magma para expandir los continentes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/383.png', 'Sin género', 'hoenn', TRUE, FALSE),
    (384, 'Rayquaza', 7.0, 206.5, 'Rayquaza ha vivido en la capa de ozono durante millones de años, alimentándose de meteoritos. La energía de estos meteoritos se acumula en su cuerpo y le permite megaevolucionar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/384.png', 'Sin género', 'hoenn', TRUE, FALSE),
    (385, 'Jirachi', 0.3, 1.1, 'Se dice que concederá los deseos escritos en las notas de su cabeza cuando se despierte de su sueño milenario.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/385.png', 'Sin género', 'hoenn', FALSE, TRUE),
    (386, 'Deoxys', 1.7, 60.8, 'Deoxys surgió a partir de un virus espacial. Tiene un alto nivel intelectual y poderes psicoquinéticos. Este Pokémon dispara rayos láser por el órgano cristalino que tiene en el torso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/386.png', 'Sin género', 'hoenn', FALSE, TRUE),
    (387, 'Turtwig', 0.4, 10.2, 'Realiza la fotosíntesis para obtener oxígeno. Si tiene sed, las hojas de la cabeza se marchitan.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/387.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (388, 'Grotle', 1.1, 97.0, 'Sabe dónde encontrar manantiales de agua pura y lleva a los Pokémon amigos hasta allí en su lomo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/388.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (389, 'Torterra', 2.2, 310.0, 'Algunos Pokémon pequeños se juntan en su espalda para hacer sus nidos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/389.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (390, 'Chimchar', 0.5, 6.2, 'El fuego que arde en su cola lo generan los gases de su estómago y disminuye cuando está débil.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/390.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (391, 'Monferno', 0.9, 22.0, 'Utiliza techos y paredes para lanzar ataques aéreos. También emplea su cola ígnea como arma.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/391.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (392, 'Infernape', 1.2, 55.0, 'Maneja a sus rivales con tremenda agilidad. En su especial forma de luchar usa todos sus miembros.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/392.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (393, 'Piplup', 0.4, 5.2, 'Es muy orgulloso, por lo que odia aceptar comida de la gente. Su grueso plumón lo protege del frío.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/393.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (394, 'Prinplup', 0.8, 23.0, 'No hace amigos. Puede partir en dos un árbol gigantesco de un fuerte aletazo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/394.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (395, 'Empoleon', 1.7, 84.5, 'Los tres cuernos de su pico son muestra de su fuerza. El líder tiene los cuernos más grandes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/395.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (396, 'Starly', 0.3, 2.0, 'Sobrevuela los campos buscando Pokémon de tipo Bicho. Chilla de forma muy estridente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/396.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (397, 'Staravia', 0.6, 15.5, 'Vive en bosques y campos. Si dos bandadas se encuentran, pelean por el territorio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/397.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (398, 'Staraptor', 1.2, 24.9, 'Al evolucionar a Staraptor deja su bandada y pasa a vivir en soledad. Sus alas son inmensas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/398.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (399, 'Bidoof', 0.5, 20.0, 'Roe constantemente los troncos y las rocas para limarse los dientes. Anida cerca del agua.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/399.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (400, 'Bibarel', 1.0, 31.5, 'Para anidar, crea presas en los ríos con maderas y barro. Tiene fama de trabajador.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/400.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (401, 'Kricketot', 0.3, 2.2, 'Si choca sus antenas, emite un sonido similar al de un xilófono.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/401.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (402, 'Kricketune', 1.0, 25.5, 'Los científicos tratan de estudiar sus melodías, que son reflejo de sus emociones.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/402.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (403, 'Shinx', 0.5, 9.5, 'Su pelaje brilla gracias a la electricidad. Envía señales a sus semejantes agitando la punta luminosa de la cola.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/403.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (404, 'Luxio', 0.9, 30.5, 'Cuando encuentra a un adversario, se prepara para combatir sacando las garras, que emiten una corriente eléctrica de un millón de voltios.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/404.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (405, 'Luxray', 1.4, 42.0, 'Duerme durante largos períodos para recuperar la enorme cantidad de electricidad que consume al usar su capacidad para ver a través de objetos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/405.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (406, 'Budew', 0.2, 1.2, 'Es muy sensible a los cambios de temperatura. Anuncia la llegada inminente de la primavera cuando florece.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/406.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (407, 'Roserade', 0.9, 14.5, 'Las toxinas de la mano derecha son de efecto inmediato, y las de la izquierda, retardado. No obstante, ambas pueden ser letales.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/407.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (408, 'Cranidos', 0.9, 31.5, 'Se caracteriza por la dureza de su cráneo. Derribaba árboles a cabezazos para comerse las bayas maduras que colgaban de ellos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/408.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (409, 'Rampardos', 1.6, 102.5, 'Pokémon prehistórico especializado en dar cabezazos. Una teoría atribuye su extinción a su cerebro pequeño y a su poca inteligencia.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/409.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (410, 'Shieldon', 0.5, 57.0, 'Los fósiles que se han encontrado hasta ahora en estratos prehistóricos pertenecen solo a su cara.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/410.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (411, 'Bastiodon', 1.3, 149.5, 'Un Pokémon con una antigüedad de unos cien millones de años. Su rostro posee una dureza impresionante, superior incluso a la del acero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/411.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (412, 'Burmy', 0.2, 3.4, 'Si su caparazón se rompe en combate, lo rehace rápidamente con lo que tenga a mano.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/412.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (413, 'Wormadam', 0.5, 6.5, 'Cuando Burmy evolucionó, su caparazón pasó a formar parte de este Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/413.png', 'Hembra', 'sinnoh', FALSE, FALSE),
    (414, 'Mothim', 0.9, 23.3, 'Hace vida nocturna. Revolotea y roba la miel de las colmenas de Combee cuando duermen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/414.png', 'Macho', 'sinnoh', FALSE, FALSE),
    (415, 'Combee', 0.3, 5.5, 'Recolecta néctar de sol a sol para entregarlo a la colonia y a Vespiquen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/415.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (416, 'Vespiquen', 1.2, 38.5, 'Cuanto mayor sea la cantidad de feromonas que segregue, mayor será el número de Combee que pueda controlar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/416.png', 'Hembra', 'sinnoh', FALSE, FALSE),
    (417, 'Pachirisu', 0.4, 3.9, 'A veces se ve a dos frotándose las bolsas de las mejillas para compartir electricidad almacenada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/417.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (418, 'Buizel', 0.7, 29.5, 'Hincha el flotador de su cuello para flotar y saca la cabeza de la superficie del agua para explorar sus alrededores.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/418.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (419, 'Floatzel', 1.1, 33.5, 'Su flotador se desarrolló a raíz de perseguir presas acuáticas. También sirve como balsa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/419.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (420, 'Cherubi', 0.4, 3.3, 'Cuanto más rojo sea su cuerpo, más dulce y deliciosa será su pequeña esfera repleta de nutrientes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/420.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (421, 'Cherrim', 0.5, 9.3, 'Al cerrarse, sus pétalos son tan duros que resultan inmunes a los picotazos de los Pokémon pájaro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/421.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (422, 'Shellos', 0.3, 6.3, 'Si se le aprieta muy fuerte, secreta un misterioso fluido morado que, aunque inofensivo, resulta desagradable por su viscosidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/422.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (423, 'Gastrodon', 0.9, 29.9, 'Aunque blando, su cuerpo es tremendamente resistente, ya que dispersa cualquier impacto que recibe dada su flexibilidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/423.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (424, 'Ambipom', 1.2, 20.3, 'Utiliza las dos colas para todo. Cuando abraza a alguien con ellas significa que esa persona se ha ganado por completo su confianza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/424.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (425, 'Drifloon', 0.4, 1.2, 'Está formado por una aglomeración de espíritus. Suele aparecer en grandes números durante las estaciones húmedas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/425.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (426, 'Drifblim', 1.2, 15.0, 'Agarra a gente y a Pokémon para llevárselos a algún sitio, aunque nadie sabe exactamente adónde.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/426.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (427, 'Buneary', 0.4, 5.5, 'Ataca estirando con un fuerte impulso las orejas enrolladas. Cuanto más entrena esta técnica, con más potencia la ejecuta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/427.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (428, 'Lopunny', 1.2, 33.3, 'Cuando acaba la estación más tórrida, le crece un nuevo pelaje muy mullido que lo prepara para el frío.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/428.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (429, 'Mismagius', 0.9, 4.4, 'Murmura conjuros para atormentar al enemigo y provocarle dolores de cabeza insoportables o visiones terroríficas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/429.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (430, 'Honchkrow', 0.9, 27.3, 'Delega el combate en sus leales súbditos y solo se involucra cuando llega la hora de asestarle el golpe de gracia al enemigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/430.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (431, 'Glameow', 0.5, 3.9, 'Dependiendo de su humor, mueve grácilmente su cola, que se asemeja a un lazo de gimnasia rítmica.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/431.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (432, 'Purugly', 1.0, 43.8, 'Para intimidar y parecer más corpulento, se aprieta la cintura con su cola bífida.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/432.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (433, 'Chingling', 0.2, 0.6, 'Tiene una esfera en la boca. Cuando salta, la esfera rebota y emite un tintineo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/433.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (434, 'Stunky', 0.4, 19.2, 'Si levanta la cola y apunta los cuartos traseros, es señal de que se dispone a expulsar un líquido cuyo hedor llega a provocar desmayos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/434.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (435, 'Skuntank', 1.0, 38.0, 'El fluido que expulsa por la punta de la cola emana una hediondez insoportable. Construye sus madrigueras cavando hoyos en la tierra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/435.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (436, 'Bronzor', 0.5, 60.5, 'Se dice que brilla y refleja la verdad al pulirlo, aunque es algo que detesta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/436.png', 'Sin género', 'sinnoh', FALSE, FALSE),
    (437, 'Bronzong', 1.3, 187.0, 'Basándose en los motivos de su cuerpo, muchos eruditos creen que este Pokémon no es originario de Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/437.png', 'Sin género', 'sinnoh', FALSE, FALSE),
    (438, 'Bonsly', 0.5, 15.0, 'Vive en entornos áridos y pedregosos. Cuanto más se secan sus esferas verdes, más destaca su sutil lustre.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/438.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (439, 'Mime Jr.', 0.6, 13.0, 'Su admiración por Mr. Rime, un consumado danzarín, lo lleva a seguirlo para aprender de él e imitar con esmero sus pasos de baile.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/439.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (440, 'Happiny', 0.6, 24.4, 'Les deja su preciada roca redonda a aquellos con los que se lleva bien. Si no se la devuelven, se echa a llorar, presa de una rabieta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/440.png', 'Hembra', 'sinnoh', FALSE, FALSE),
    (441, 'Chatot', 0.5, 1.9, 'Puede imitar el lenguaje humano. Si se juntan varios, todos aprenden las mismas palabras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/441.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (442, 'Spiritomb', 1.0, 108.0, 'Un viajero utilizó un misterioso hechizo para unirlo a una Piedra Espíritu por sus constantes fechorías.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/442.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (443, 'Gible', 0.7, 20.5, 'Ataca indiscriminadamente a cualquier cosa que se mueva y la arrastra a su agujero. Pese a tener una boca enorme, su estómago es pequeño.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/443.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (444, 'Gabite', 1.4, 56.0, 'Entierra gemas en la cueva que le sirve de nido y hace trizas con sus garras y colmillos a cualquier intruso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/444.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (445, 'Garchomp', 1.9, 95.0, 'Se mueve a gran velocidad incluso por tierra. Es capaz de cazar una presa en una montaña nevada y volver a su guarida sin llegar a pasar frío.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/445.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (446, 'Munchlax', 0.6, 105.0, 'Guarda alimentos bajo el pelaje. Compartirá un pequeño bocado de vez en cuando con quien logre ganarse su confianza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/446.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (447, 'Riolu', 0.7, 20.2, 'Percibe los sentimientos de quienes lo rodean, así como las condiciones del entorno, mediante unas ondas conocidas como auras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/447.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (448, 'Lucario', 1.2, 54.0, 'Puede leer los pensamientos de la gente, por lo que establece lazos afectivos únicamente con Entrenadores de corazón noble.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/448.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (449, 'Hippopotas', 0.8, 49.5, 'Este Pokémon de hábitos diurnos se entierra en la arena para dormir cuando la temperatura en el desierto se desploma al caer la noche.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/449.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (450, 'Hippowdon', 2.0, 300.0, 'Puede ser muy agresivo cuando se enfada. Provoca auténticas tempestades de arena al expeler la que ha tragado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/450.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (451, 'Skorupi', 0.8, 12.0, 'Ataca con las pinzas venenosas de la cola. Tras clavarlas, inyecta una toxina que inmoviliza a la presa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/451.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (452, 'Drapion', 1.3, 61.5, 'Su ferocidad le ha granjeado el sobrenombre del Diablo de la Arena, pero en presencia de los Hippowdon se muestra dócil y pacífico.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/452.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (453, 'Croagunk', 0.7, 23.0, 'Su veneno posee propiedades medicinales si se diluye. Se ha vuelto muy popular desde que una empresa farmacéutica lo adoptó como mascota.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/453.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (454, 'Toxicroak', 1.3, 44.4, 'Cuando abate una presa, emite un croar de victoria a pleno pulmón. Está emparentado con los Seismitoad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/454.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (455, 'Carnivine', 1.4, 27.0, 'Se cuelga de los árboles en los pantanos. Atrae a sus presas con su dulce olor y las engulle.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/455.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (456, 'Finneon', 0.4, 7.0, 'Por el día permanece cerca de la superficie y se retira a las profundidades por la noche. Atrae a las presas con sus brillantes aletas caudales.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/456.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (457, 'Lumineon', 1.2, 24.0, 'Nada arrastrándose por el lecho marino. Sus espléndidas aletas brillan como las estrellas del firmamento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/457.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (458, 'Mantyke', 1.0, 65.0, 'Nada con los bancos de Remoraid y lucha junto a ellos cuando los ataca un enemigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/458.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (459, 'Snover', 1.0, 50.5, 'Las bayas con aspecto de helado que le crecen alrededor de la barriga son la comida favorita de los Darumaka que habitan en Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/459.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (460, 'Abomasnow', 2.2, 135.5, 'Posee la capacidad de generar ventiscas. Si agita su enorme cuerpo, el terreno circundante queda inmediatamente cubierto de nieve.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/460.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (461, 'Weavile', 1.1, 34.0, 'Se comunican mediante marcas que tallan con sus garras. Se cree que tienen un repertorio de más de 500.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/461.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (462, 'Magnezone', 1.2, 180.0, 'Se piensa que estuvo expuesto a un campo magnético especial que alteró su estructura molecular e hizo que evolucionara.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/462.png', 'Sin género', 'sinnoh', FALSE, FALSE),
    (463, 'Lickilicky', 1.7, 140.0, 'Es tan diestro con la lengua como un ser humano con las manos. Por el contrario, muestra escasa maña con los dedos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/463.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (464, 'Rhyperior', 2.4, 282.8, 'Repele los ataques usando un Protector y aprovecha el momento en que el rival baja la guardia para perforarlo con su taladro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/464.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (465, 'Tangrowth', 2.0, 128.6, 'Las lianas le crecen más rápidamente si vive en regiones cálidas. Cuando alcanzan cierta longitud, se las corta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/465.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (466, 'Electivire', 1.8, 138.6, 'Es de los Pokémon de tipo Eléctrico que más electricidad producen. Genera una corriente de alta tensión desde las puntas de las colas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/466.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (467, 'Magmortar', 1.6, 68.0, 'Al vivir en un cráter, su cuerpo ha adquirido un aspecto similar al de un volcán y ha desarrollado un órgano parecido a una cámara magmática.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/467.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (468, 'Togekiss', 1.5, 38.0, 'Se dice que es portador de buena suerte. Por ello, su imagen aparece representada en talismanes y amuletos desde la antigüedad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/468.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (469, 'Yanmega', 1.9, 51.5, 'Con sus seis patas puede llevar a un adulto y volar con comodidad. Se equilibra con las alas de su cola.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/469.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (470, 'Leafeon', 1.0, 25.5, 'Se siente muy orgulloso de su cola afilada como una espada, con la que es capaz de cortar en dos el tronco de un árbol grueso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/470.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (471, 'Glaceon', 0.8, 25.9, 'El aire gélido que exhala crea una suerte de cristales de hielo que lo hace muy demandado en las estaciones de esquí.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/471.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (472, 'Gliscor', 2.0, 42.5, 'Vuela sin hacer nada de ruido. Con su larga cola captura a sus presas y las muerde con sus colmillos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/472.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (473, 'Mamoswine', 2.5, 291.0, 'Es tan fuerte como parece. Cuanto más frío hace, más gruesos, largos e imponentes se vuelven sus colmillos de hielo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/473.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (474, 'Porygon-Z', 0.9, 34.0, 'Se dice que evolucionó con la instalación de un nuevo software, pero la comunidad científica está dividida respecto a si es o no una evolución.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/474.png', 'Sin género', 'sinnoh', FALSE, FALSE),
    (475, 'Gallade', 1.6, 52.0, 'Es capaz de percibir al instante cuando alguien está en un aprieto y corre raudo a su lado para prestarle ayuda.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/475.png', 'Macho', 'sinnoh', FALSE, FALSE),
    (476, 'Probopass', 1.4, 340.0, 'Usa sus tres pequeñas unidades para capturar presas o combatir, mientras que el resto de su cuerpo se dedica casi solo a impartir órdenes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/476.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (477, 'Dusknoir', 2.2, 106.6, 'Engulle a los rivales con la boca del estómago y, tras haber devorado el alma, escupe el cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/477.png', 'Ambos', 'sinnoh', FALSE, FALSE),
    (478, 'Froslass', 1.3, 26.6, 'Expulsa un vaho gélido a -50 °C con el que congela a sus presas para luego llevarlas a su morada y colocarlas como adorno.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/478.png', 'Hembra', 'sinnoh', FALSE, FALSE),
    (479, 'Rotom', 0.3, 0.3, 'Su cuerpo de plasma le permite infiltrarse en toda clase de dispositivos electrónicos. Adora sobresaltar a la gente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/479.png', 'Sin género', 'sinnoh', FALSE, FALSE),
    (480, 'Uxie', 0.3, 0.3, 'Se dice que su aparición otorgó a los humanos la inteligencia para mejorar sus vidas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/480.png', 'Sin género', 'sinnoh', TRUE, FALSE),
    (481, 'Mesprit', 0.3, 0.3, 'Duerme en el fondo de un lago. Se dice que su espíritu deja el cuerpo para volar sobre el agua.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/481.png', 'Sin género', 'sinnoh', TRUE, FALSE),
    (482, 'Azelf', 0.3, 0.3, 'Se cree que Uxie, Mesprit y Azelf provienen del mismo huevo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/482.png', 'Sin género', 'sinnoh', TRUE, FALSE),
    (483, 'Dialga', 5.4, 683.0, 'Tiene el poder de controlar el tiempo. Aparece en los mitos de Sinnoh como una vieja deidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/483.png', 'Sin género', 'sinnoh', TRUE, FALSE),
    (484, 'Palkia', 4.2, 336.0, 'Tiene la habilidad de distorsionar el espacio. La mitología de Sinnoh lo describe como una deidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/484.png', 'Sin género', 'sinnoh', TRUE, FALSE),
    (485, 'Heatran', 1.7, 430.0, 'Su sangre fluye ardiendo como si fuera magma. Vive en cráteres de volcanes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/485.png', 'Ambos', 'sinnoh', TRUE, FALSE),
    (486, 'Regigigas', 3.7, 420.0, 'Dicen que creó a otros Pokémon a partir de distintos materiales y que, después, colocó los continentes en su posición actual.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/486.png', 'Sin género', 'sinnoh', TRUE, FALSE),
    (487, 'Giratina', 4.5, 750.0, 'Fue desterrado por su violencia. Observa el mundo en silencio desde el Mundo Distorsión.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/487.png', 'Sin género', 'sinnoh', TRUE, FALSE),
    (488, 'Cresselia', 1.5, 85.6, 'Si alguien se duerme con una pluma suya, tendrá sueños maravillosos. Encarna el creciente lunar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/488.png', 'Hembra', 'sinnoh', TRUE, FALSE),
    (489, 'Phione', 0.4, 3.1, 'Va a la deriva por mares cálidos. Siempre vuelve a donde nació, por mucho que se haya alejado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/489.png', 'Sin género', 'sinnoh', FALSE, TRUE),
    (490, 'Manaphy', 0.3, 1.4, 'Posee un poder singular que hace que entable amistad con casi cualquier Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/490.png', 'Sin género', 'sinnoh', FALSE, TRUE),
    (491, 'Darkrai', 1.5, 50.5, 'Puede adormecer a la gente y hacerles soñar. Está activo en las noches de luna nueva.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/491.png', 'Sin género', 'sinnoh', FALSE, TRUE),
    (492, 'Shaymin', 0.2, 2.1, 'Se dice que, cuando florecen las Gracídeas, Shaymin alza el vuelo para mostrar su gratitud.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/492.png', 'Sin género', 'sinnoh', FALSE, TRUE),
    (493, 'Arceus', 3.2, 320.0, 'La mitología cuenta que este Pokémon nació antes de que el Universo existiera.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/493.png', 'Sin género', 'sinnoh', FALSE, TRUE),
    (494, 'Victini', 0.4, 4.0, 'Cuando Victini comparte su energía ilimitada, esa persona o Pokémon irradia abundante poder.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/494.png', 'Sin género', 'unova', FALSE, TRUE),
    (495, 'Snivy', 0.6, 8.1, 'Sintetiza la luz del sol que recoge con su cola. Esta se le queda abatida cuando le fallan las energías.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/495.png', 'Ambos', 'unova', FALSE, FALSE),
    (496, 'Servine', 0.8, 16.0, 'Cuando su cuerpo está sucio, no puede realizar la fotosíntesis con sus hojas, así que cuida mucho su higiene personal.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/496.png', 'Ambos', 'unova', FALSE, FALSE),
    (497, 'Serperior', 3.3, 63.0, 'Detiene los movimientos del rival con una sola mirada. Expande la energía solar dentro de su cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/497.png', 'Ambos', 'unova', FALSE, FALSE),
    (498, 'Tepig', 0.5, 9.9, 'Le encanta comer bayas tostadas, pero a veces se emociona demasiado y termina churruscándolas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/498.png', 'Ambos', 'unova', FALSE, FALSE),
    (499, 'Pignite', 1.0, 55.5, 'Cuando las llamas de su interior se avivan, aumenta su velocidad y agilidad. Emite humo si está en peligro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/499.png', 'Ambos', 'unova', FALSE, FALSE),
    (500, 'Emboar', 1.6, 150.0, 'Posee una tupida barba fogosa. Es tanto rápido como poderoso, y su principal baza es la lucha cuerpo a cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/500.png', 'Ambos', 'unova', FALSE, FALSE),
    (501, 'Oshawott', 0.5, 5.9, 'Ataca con la vieira de su ombligo. En cuanto para un ataque, pasa al contraataque sin dilación.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/501.png', 'Ambos', 'unova', FALSE, FALSE),
    (502, 'Dewott', 0.8, 24.5, 'Tras un exhaustivo entrenamiento, Dewott puede dominar diversas técnicas para usar con sus vieiras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/502.png', 'Ambos', 'unova', FALSE, FALSE),
    (503, 'Samurott', 1.5, 94.6, 'Derriba a su rival con un solo tajo del sable que lleva en su coraza. Acalla al enemigo con una simple mirada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/503.png', 'Ambos', 'unova', FALSE, FALSE),
    (504, 'Patrat', 0.5, 11.6, 'Aunque es un Pokémon muy precavido y siempre hay uno montando guardia, si se acercan por detrás, no se dará cuenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/504.png', 'Ambos', 'unova', FALSE, FALSE),
    (505, 'Watchog', 1.1, 27.0, 'Ataca lanzando las semillas de las bayas que acumula en sus mofletes. Su cola se tensa al avistar a un enemigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/505.png', 'Ambos', 'unova', FALSE, FALSE),
    (506, 'Lillipup', 0.4, 4.1, 'Muestra una inteligencia muy superior a la media de los niños humanos. No olvida ni el amor ni los malos tratos que recibe.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/506.png', 'Ambos', 'unova', FALSE, FALSE),
    (507, 'Herdier', 0.9, 14.7, 'El pelaje negro que lo recubre es tan denso y elástico que puede repeler incluso los colmillos más afilados.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/507.png', 'Ambos', 'unova', FALSE, FALSE),
    (508, 'Stoutland', 1.2, 61.0, 'Sus impresionantes bigotes son su orgullo. Entre los de su especie se establece una jerarquía según su longitud.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/508.png', 'Ambos', 'unova', FALSE, FALSE),
    (509, 'Purrloin', 0.4, 10.1, 'Una vez que ha logrado distraer al rival mediante sus gestos adorables, lo araña de improviso con las garras mientras muestra un semblante risueño.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/509.png', 'Ambos', 'unova', FALSE, FALSE),
    (510, 'Liepard', 1.1, 37.5, 'Libra disputas territoriales con los Thievul. Se acerca a sus rivales por la espalda sin hacer el menor ruido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/510.png', 'Ambos', 'unova', FALSE, FALSE),
    (511, 'Pansage', 0.6, 10.5, 'Es todo un experto en la búsqueda de bayas y es tan gentil que las comparte con todos sus compañeros.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/511.png', 'Ambos', 'unova', FALSE, FALSE),
    (512, 'Simisage', 1.1, 30.5, 'Pokémon muy temperamental que lucha con su cola revestida de púas. Las hojas de su cabeza están muy amargas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/512.png', 'Ambos', 'unova', FALSE, FALSE),
    (513, 'Pansear', 0.6, 11.0, 'Vive en cuevas volcánicas. El interior de su mata de pelo arde, llegando a alcanzar hasta 300 °C.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/513.png', 'Ambos', 'unova', FALSE, FALSE),
    (514, 'Simisear', 1.0, 28.0, 'Cuando se emociona, echa chispas por la cola y la cabeza, y calienta su cuerpo. Por alguna razón le encantan los dulces.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/514.png', 'Ambos', 'unova', FALSE, FALSE),
    (515, 'Panpour', 0.6, 13.5, 'La acuosidad que acumula en su mata de pelo es rica en nutrientes, ideal para regar plantas y que crezcan mucho.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/515.png', 'Ambos', 'unova', FALSE, FALSE),
    (516, 'Simipour', 1.0, 29.0, 'Le encantan los lugares con agua limpia. Cuando desciende el nivel de agua de su pelo, se abastece a través de su cola.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/516.png', 'Ambos', 'unova', FALSE, FALSE),
    (517, 'Munna', 0.6, 23.3, 'El humo que despide cambia de color en función del sueño que haya consumido. Si es alegre, será rosa, o negruzco en el caso de una pesadilla.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/517.png', 'Ambos', 'unova', FALSE, FALSE),
    (518, 'Musharna', 1.1, 60.5, 'Siempre está soñando o adormecido. Se pone de muy mal humor al despertar, por lo que es mejor no perturbarlo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/518.png', 'Ambos', 'unova', FALSE, FALSE),
    (519, 'Pidove', 0.3, 2.1, 'Es muy olvidadizo y no demasiado avispado, pero muchos Entrenadores le tienen simpatía por su carácter afable y sincero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/519.png', 'Ambos', 'unova', FALSE, FALSE),
    (520, 'Tranquill', 0.6, 15.0, 'Posee una mente ágil y muy buena memoria. Tal vez por eso muchos repartidores lo eligen como compañero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/520.png', 'Ambos', 'unova', FALSE, FALSE),
    (521, 'Unfezant', 1.2, 29.0, 'Es un Pokémon muy inteligente y orgulloso. Se tiene en alta estima a aquellos que se convierten en sus Entrenadores.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/521.png', 'Ambos', 'unova', FALSE, FALSE),
    (522, 'Blitzle', 0.8, 29.8, 'Su crin brilla cuando emite una descarga eléctrica. Se comunica con los suyos mediante el ritmo y el número de brillos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/522.png', 'Ambos', 'unova', FALSE, FALSE),
    (523, 'Zebstrika', 1.6, 79.5, 'Su velocidad se asemeja a la de un rayo. Si corre al máximo, se dejan oír truenos por doquier.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/523.png', 'Ambos', 'unova', FALSE, FALSE),
    (524, 'Roggenrola', 0.4, 18.0, 'Se dirige hacia cualquier sonido que perciba. Es ligeramente cálido al tacto, debido al efecto de su núcleo energético.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/524.png', 'Ambos', 'unova', FALSE, FALSE),
    (525, 'Boldore', 0.9, 102.0, 'Se vale del sonido para percibir el entorno. Si alguien despierta su ira, lo perseguirá sin cambiar la orientación del cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/525.png', 'Ambos', 'unova', FALSE, FALSE),
    (526, 'Gigalith', 1.7, 260.0, 'Las bolas de energía que lanza solo en días soleados son tan potentes que pueden hacer saltar un camión por los aires.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/526.png', 'Ambos', 'unova', FALSE, FALSE),
    (527, 'Woobat', 0.4, 2.1, 'Emite ultrasonidos mientras revolotea en busca de los Pokémon insecto con los que se sustenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/527.png', 'Ambos', 'unova', FALSE, FALSE),
    (528, 'Swoobat', 0.9, 10.5, 'En algunas regiones se venera a este Pokémon, ya que consideran la forma de su nariz como un símbolo de felicidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/528.png', 'Ambos', 'unova', FALSE, FALSE),
    (529, 'Drilbur', 0.3, 8.5, 'Su costumbre de horadar túneles bajo tierra le ha granjeado la antipatía de los agricultores, ya que puede echar a perder cosechas enteras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/529.png', 'Ambos', 'unova', FALSE, FALSE),
    (530, 'Excadrill', 0.7, 40.4, 'Se lo conoce como el Rey del Taladro. Puede horadar túneles bajo tierra a una velocidad de 150 km/h.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/530.png', 'Ambos', 'unova', FALSE, FALSE),
    (531, 'Audino', 1.1, 31.0, 'Un Pokémon gentil que es capaz de comprender los sentimientos y averiguar el estado de salud de todo aquel que toque con sus antenas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/531.png', 'Ambos', 'unova', FALSE, FALSE),
    (532, 'Timburr', 0.6, 12.5, 'Cuando logra transportar una viga de madera que triplica su altura y peso, es señal de que va a evolucionar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/532.png', 'Ambos', 'unova', FALSE, FALSE),
    (533, 'Gurdurr', 1.2, 40.0, 'Blande vigas de acero con gran destreza, pero la construcción no se le da muy bien; de hecho, su especialidad es la demolición.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/533.png', 'Ambos', 'unova', FALSE, FALSE),
    (534, 'Conkeldurr', 1.4, 87.0, 'Cuando decide ponerse en serio, suelta sus pilares de hormigón y se abalanza sobre el rival con solo un puño como arma.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/534.png', 'Ambos', 'unova', FALSE, FALSE),
    (535, 'Tympole', 0.5, 4.5, 'Se comunica con los suyos mediante ondas sonoras. Su grito de alerta es imperceptible para los humanos y el resto de los Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/535.png', 'Ambos', 'unova', FALSE, FALSE),
    (536, 'Palpitoad', 0.8, 17.0, 'A veces emiten un bello canto. Cuanto mayores son las protuberancias del cuerpo, más extenso es su registro vocal.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/536.png', 'Ambos', 'unova', FALSE, FALSE),
    (537, 'Seismitoad', 1.5, 62.0, 'Las vibraciones de sus bultos resultan perfectas para dar masajes, lo que lo ha hecho muy popular entre la tercera edad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/537.png', 'Ambos', 'unova', FALSE, FALSE),
    (538, 'Throh', 1.3, 55.5, 'Entrenan en grupos de cinco individuos. Si alguno es incapaz de seguir el ritmo, arroja el cinturón y abandona la cuadrilla.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/538.png', 'Macho', 'unova', FALSE, FALSE),
    (539, 'Sawk', 1.4, 51.0, 'Cuando un Sawk ha entrenado duro, es capaz de separar las aguas del océano con la potencia de sus técnicas de kárate.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/539.png', 'Macho', 'unova', FALSE, FALSE),
    (540, 'Sewaddle', 0.3, 2.5, 'Usa hojas como material para fabricar su propia ropa, por lo que los diseñadores más famosos los tienen como mascota.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/540.png', 'Ambos', 'unova', FALSE, FALSE),
    (541, 'Swadloon', 0.5, 7.3, 'Se guarece del frío envolviéndose en hojas. Se desplaza por el bosque comiendo a su paso las hojas caídas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/541.png', 'Ambos', 'unova', FALSE, FALSE),
    (542, 'Leavanny', 1.2, 20.5, 'Calienta sus huevos con el calor desprendido por el humus. Hace mantillas con las hojas para Sewaddle.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/542.png', 'Ambos', 'unova', FALSE, FALSE),
    (543, 'Venipede', 0.4, 5.3, 'Sus colmillos contienen un veneno letal. Si encuentra una presa que parece comestible, se abalanza sobre ella sin pensárselo dos veces.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/543.png', 'Ambos', 'unova', FALSE, FALSE),
    (544, 'Whirlipede', 1.2, 58.5, 'Se defiende con su duro caparazón y sus púas venenosas mientras acumula la energía necesaria para evolucionar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/544.png', 'Ambos', 'unova', FALSE, FALSE),
    (545, 'Scolipede', 2.5, 200.5, 'Las disputas territoriales con Centiskorch son extremadamente violentas. El perdedor se convierte en la presa del ganador.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/545.png', 'Ambos', 'unova', FALSE, FALSE),
    (546, 'Cottonee', 0.3, 0.6, 'Combinando los algodones de los Cottonee y Eldegoss se obtiene una tela exquisita, que usan las marcas más exclusivas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/546.png', 'Ambos', 'unova', FALSE, FALSE),
    (547, 'Whimsicott', 0.7, 6.6, 'Su algodón se expande cuando recibe los rayos del sol, pero acaba desprendiéndose si se vuelve demasiado voluminoso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/547.png', 'Ambos', 'unova', FALSE, FALSE),
    (548, 'Petilil', 0.5, 6.6, 'Cuanto más sano está este Pokémon, más intenso se vuelve el color de sus hojas. A veces se asienta en huertos o jardines de flores bien cuidados.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/548.png', 'Hembra', 'unova', FALSE, FALSE),
    (549, 'Lilligant', 1.1, 16.3, 'El aceite esencial que se extrae de su flor emana un aroma sublime, aunque su precio resulta desorbitado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/549.png', 'Hembra', 'unova', FALSE, FALSE),
    (550, 'Basculin', 1.0, 18.0, 'Un alimento básico de la dieta de antaño. A los jóvenes se les daba Basculin de raya roja por su alto contenido en ácidos grasos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/550.png', 'Ambos', 'unova', FALSE, FALSE),
    (551, 'Sandile', 0.7, 15.2, 'Es pequeño, pero cuenta con un tren inferior fuerte. Se desplaza por el desierto abriéndose paso entre la arena, como si nadase.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/551.png', 'Ambos', 'unova', FALSE, FALSE),
    (552, 'Krokorok', 1.0, 33.4, 'Tiene unos ojos especiales que le permiten ver en la oscuridad, pero suele permanecer inmóvil en las frías noches del desierto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/552.png', 'Ambos', 'unova', FALSE, FALSE),
    (553, 'Krookodile', 1.5, 96.3, 'Es de naturaleza violenta, pero también tiene la paciencia necesaria para esperar a su presa oculto en la arena durante varios días.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/553.png', 'Ambos', 'unova', FALSE, FALSE),
    (554, 'Darumaka', 0.6, 37.5, 'Cuando duerme es imposible tumbarlo por más que lo zarandeen. Es muy popular como amuleto de la suerte.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/554.png', 'Ambos', 'unova', FALSE, FALSE),
    (555, 'Darmanitan', 1.3, 92.9, 'Su fuerza aumenta cuanto más se aviva su fuego interior, que puede alcanzar temperaturas superiores a los 1400 °C.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/555.png', 'Ambos', 'unova', FALSE, FALSE),
    (556, 'Maractus', 1.0, 28.0, 'Una vez al año, esparce sus semillas, cuyo alto valor nutritivo las convierte en una inestimable fuente de alimento en el desierto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/556.png', 'Ambos', 'unova', FALSE, FALSE),
    (557, 'Dwebble', 0.3, 14.5, 'Si no encuentra una piedra que sea idónea como morada, se instala en los orificios de algún Hippowdon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/557.png', 'Ambos', 'unova', FALSE, FALSE),
    (558, 'Crustle', 1.4, 200.0, 'Su arma más potente son sus gruesas pinzas, tan duras que pueden abrir una brecha incluso en el Protector de Rhyperior.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/558.png', 'Ambos', 'unova', FALSE, FALSE),
    (559, 'Scraggy', 0.6, 11.8, 'Su robusta piel le sirve de protección. Cuando ya no puede estirarse más, es señal de que va a evolucionar pronto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/559.png', 'Ambos', 'unova', FALSE, FALSE),
    (560, 'Scrafty', 1.1, 30.0, 'A pesar de su carácter agresivo, se muestra muy protector con sus allegados y su territorio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/560.png', 'Ambos', 'unova', FALSE, FALSE),
    (561, 'Sigilyph', 1.4, 14.0, 'Explorando la zona desértica que sobrevuela, se han descubierto los vestigios de lo que parece ser una antigua ciudad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/561.png', 'Ambos', 'unova', FALSE, FALSE),
    (562, 'Yamask', 0.5, 1.5, 'Surgió del alma de una persona que vivió en tiempos remotos. Merodea por las ruinas en busca de alguien que reconozca su rostro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/562.png', 'Ambos', 'unova', FALSE, FALSE),
    (563, 'Cofagrigus', 1.7, 76.5, 'Aparece representado en los muros de antiguas sepulturas como símbolo de riqueza de reyes de antaño.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/563.png', 'Ambos', 'unova', FALSE, FALSE),
    (564, 'Tirtouga', 0.7, 16.5, 'Se piensa que es el antepasado de numerosos Pokémon tortuga. Fue regenerado a partir de un fósil.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/564.png', 'Ambos', 'unova', FALSE, FALSE),
    (565, 'Carracosta', 1.2, 81.0, 'Aunque se mueva con mayor lentitud sobre la superficie terrestre que en el agua, emerge a tierra en busca de presas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/565.png', 'Ambos', 'unova', FALSE, FALSE),
    (566, 'Archen', 0.5, 9.5, 'Se dice que es el antepasado de los Pokémon pájaro. Vivía en las copas de los árboles y se alimentaba de bayas y Pokémon insecto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/566.png', 'Ambos', 'unova', FALSE, FALSE),
    (567, 'Archeops', 1.4, 32.0, 'Si bien era capaz de volar, parece ser que se le daba mucho mejor cazar presas en tierra firme que en el aire.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/567.png', 'Ambos', 'unova', FALSE, FALSE),
    (568, 'Trubbish', 0.6, 31.0, 'Nació a partir de una rebosante bolsa de basura. Los gases nocivos que eructa son un manjar para los Weezing de Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/568.png', 'Ambos', 'unova', FALSE, FALSE),
    (569, 'Garbodor', 1.9, 107.3, 'El veneno líquido que brota de su brazo derecho es tan nocivo que puede acabar con una criatura ya débil al menor contacto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/569.png', 'Ambos', 'unova', FALSE, FALSE),
    (570, 'Zorua', 0.7, 12.5, 'Suele transformarse en personas, sobre todo en niños, y se adentra en pueblos buscando comida.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/570.png', 'Ambos', 'unova', FALSE, FALSE),
    (571, 'Zoroark', 1.6, 81.1, 'Los Entrenadores solitarios le piden a Zoroark que les muestre ilusiones con las que combatir la desazón de la soledad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/571.png', 'Ambos', 'unova', FALSE, FALSE),
    (572, 'Minccino', 0.4, 5.8, 'Se saludan entre sí frotándose la cola. Cuanto más voluminosa es, más orgullosos se muestran.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/572.png', 'Ambos', 'unova', FALSE, FALSE),
    (573, 'Cinccino', 0.5, 7.5, 'Su pelaje está recubierto por una grasa especial que repele los ataques enemigos y por la que se llegan a pagar auténticas fortunas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/573.png', 'Ambos', 'unova', FALSE, FALSE),
    (574, 'Gothita', 0.4, 5.8, 'A veces susurra aunque no haya nadie alrededor. Por eso se cree que tal vez hable con alguien o algo imperceptible para los demás.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/574.png', 'Ambos', 'unova', FALSE, FALSE),
    (575, 'Gothorita', 0.7, 18.0, 'Sus poderes psíquicos alcanzan su apogeo en las noches estrelladas, aunque su posible vínculo con el espacio está envuelto en misterio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/575.png', 'Ambos', 'unova', FALSE, FALSE),
    (576, 'Gothitelle', 1.5, 44.0, 'Los malhechores a los que revela sus últimos momentos pierden la vida el mismo día.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/576.png', 'Ambos', 'unova', FALSE, FALSE),
    (577, 'Solosis', 0.3, 1.0, 'Se cree que la sustancia viscosa que lo envuelve le permite sobrevivir en el espacio exterior.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/577.png', 'Ambos', 'unova', FALSE, FALSE),
    (578, 'Duosion', 0.6, 8.0, 'Las dos partes de su cerebro casi nunca piensan lo mismo, por lo que es imposible predecir sus intenciones.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/578.png', 'Ambos', 'unova', FALSE, FALSE),
    (579, 'Reuniclus', 1.0, 20.1, 'Al parecer, beber su líquido especial otorga un intelecto sin par, pero resulta muy venenoso, excepto para los propios Reuniclus.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/579.png', 'Ambos', 'unova', FALSE, FALSE),
    (580, 'Ducklett', 0.5, 5.5, 'Nada a mayor velocidad de la que puede volar. Se sumerge en el agua para buscar musgo acuático, su comida favorita.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/580.png', 'Ambos', 'unova', FALSE, FALSE),
    (581, 'Swanna', 1.3, 24.2, 'Comienzan a danzar al amanecer. El líder de la bandada se sitúa en el centro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/581.png', 'Ambos', 'unova', FALSE, FALSE),
    (582, 'Vanillite', 0.4, 5.7, 'Este Pokémon nació a partir de un carámbano. Exhala un vaho a -50 °C con el que congela el ambiente para adaptarlo a sus necesidades.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/582.png', 'Ambos', 'unova', FALSE, FALSE),
    (583, 'Vanillish', 1.1, 41.0, 'Congela a sus enemigos con un vaho a -100 °C, pero no llega a arrebatarles la vida debido a su carácter benévolo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/583.png', 'Ambos', 'unova', FALSE, FALSE),
    (584, 'Vanilluxe', 1.3, 57.5, 'Su temperatura corporal ronda los -6 °C. Se dice que nace de la fusión de dos Vanillish.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/584.png', 'Ambos', 'unova', FALSE, FALSE),
    (585, 'Deerling', 0.6, 19.5, 'Durante los cambios de estación, su pelaje y olor cambian. Esto anuncia el comienzo de una estación.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/585.png', 'Ambos', 'unova', FALSE, FALSE),
    (586, 'Sawsbuck', 1.9, 92.5, 'Migra con el cambio de estación, por lo que hay quien considera a Sawsbuck el heraldo de la primavera.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/586.png', 'Ambos', 'unova', FALSE, FALSE),
    (587, 'Emolga', 0.4, 5.0, 'Le encantan las bayas dulces. A veces almacena tanta comida en los carrillos que no puede volar bien.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/587.png', 'Ambos', 'unova', FALSE, FALSE),
    (588, 'Karrablast', 0.5, 5.9, 'Escupe un líquido corrosivo con el que disuelve el caparazón de los Shelmet para luego devorar el contenido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/588.png', 'Ambos', 'unova', FALSE, FALSE),
    (589, 'Escavalier', 1.0, 33.0, 'Ataca a los enemigos con sus lanzas. Aparece representado en pleno duelo contra un Sirfetch’d en un famoso cuadro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/589.png', 'Ambos', 'unova', FALSE, FALSE),
    (590, 'Foongus', 0.2, 1.0, 'Las esporas que expulsa por las extremidades son altamente tóxicas, pero, si se secan bien, sirven como remedio estomacal.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/590.png', 'Ambos', 'unova', FALSE, FALSE),
    (591, 'Amoonguss', 0.6, 10.5, 'Por lo general no se mueve demasiado. Suele permanecer quieto al lado de Poké Balls que haya por el suelo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/591.png', 'Ambos', 'unova', FALSE, FALSE),
    (592, 'Frillish', 1.2, 33.0, 'Cuenta la leyenda que los Frillish son en realidad los habitantes de una antigua ciudad sumergida convertidos en Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/592.png', 'Ambos', 'unova', FALSE, FALSE),
    (593, 'Jellicent', 2.2, 135.0, 'Las noches de luna llena, bancos enteros de Jellicent emergen a la superficie y aguardan la llegada de alguna presa incauta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/593.png', 'Ambos', 'unova', FALSE, FALSE),
    (594, 'Alomomola', 1.2, 31.6, 'Se cree que ayuda a los Pokémon heridos y debilitados de forma que los depredadores naturales de estos no le ataquen a él también.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/594.png', 'Ambos', 'unova', FALSE, FALSE),
    (595, 'Joltik', 0.1, 0.6, 'Se agarra a otros Pokémon para absorber su electricidad estática. Es muy común verlo aferrado a las posaderas de un Yamper.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/595.png', 'Ambos', 'unova', FALSE, FALSE),
    (596, 'Galvantula', 0.8, 14.3, 'Teje una tela con hilo electrificado junto a los nidos de Pokémon pájaro para atrapar a los polluelos que aún no saben volar bien.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/596.png', 'Ambos', 'unova', FALSE, FALSE),
    (597, 'Ferroseed', 0.6, 18.8, 'Prefiere las cuevas de paredes musgosas, ya que las enzimas contenidas en el musgo le permiten desarrollar unas púas grandes y robustas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/597.png', 'Ambos', 'unova', FALSE, FALSE),
    (598, 'Ferrothorn', 1.0, 110.0, 'Sus púas son más duras que el acero. Se aferra y desplaza por paredes rocosas usando las que tiene en los tentáculos como ganchos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/598.png', 'Ambos', 'unova', FALSE, FALSE),
    (599, 'Klink', 0.3, 21.0, 'Se dice que en tiempos remotos los seres humanos se inspiraron en este Pokémon para inventar el mecanismo de engranaje.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/599.png', 'Sin género', 'unova', FALSE, FALSE),
    (600, 'Klang', 0.6, 51.0, 'Muchas empresas de Galar usan su imagen en sus logotipos como símbolo de tecnología industrial.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/600.png', 'Sin género', 'unova', FALSE, FALSE),
    (601, 'Klinklang', 0.6, 81.0, 'Las tres ruedas dentadas giran a gran velocidad. El aro metálico dotado de púas no es materia viva.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/601.png', 'Sin género', 'unova', FALSE, FALSE),
    (602, 'Tynamo', 0.2, 0.3, 'Apenas puede generar energía por sí mismo, pero un banco de Tynamo puede crear violentas descargas eléctricas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/602.png', 'Ambos', 'unova', FALSE, FALSE),
    (603, 'Eelektrik', 1.2, 22.0, 'Pokémon de apetito voraz. En cuanto encuentra una presa, la paraliza con electricidad y la engulle.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/603.png', 'Ambos', 'unova', FALSE, FALSE),
    (604, 'Eelektross', 2.1, 80.5, 'Sale del mar con la fuerza de sus brazos y ataca a sus presas en la costa. Luego se las lleva de vuelta al mar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/604.png', 'Ambos', 'unova', FALSE, FALSE),
    (605, 'Elgyem', 0.5, 9.0, 'Fue descubierto hace aproximadamente 50 años. Posee un cerebro muy desarrollado que le otorga poderes psíquicos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/605.png', 'Ambos', 'unova', FALSE, FALSE),
    (606, 'Beheeyem', 1.0, 34.5, 'Es capaz de manipular los recuerdos del rival. Se lo avista en ocasiones vagando por campos de trigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/606.png', 'Ambos', 'unova', FALSE, FALSE),
    (607, 'Litwick', 0.3, 3.1, 'Cuanto más joven sea la energía vital que ha absorbido, mayor tamaño tendrá la llama de la cabeza y más siniestro será su brillo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/607.png', 'Ambos', 'unova', FALSE, FALSE),
    (608, 'Lampent', 0.6, 13.0, 'Se oculta en entornos urbanos haciéndose pasar por una lámpara corriente. Si se topa con alguien moribundo, lo sigue en silencio.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/608.png', 'Ambos', 'unova', FALSE, FALSE),
    (609, 'Chandelure', 1.0, 34.3, 'Cuentan que, en las mansiones donde se usaba para la iluminación, los funerales se sucedían de forma incesante.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/609.png', 'Ambos', 'unova', FALSE, FALSE),
    (610, 'Axew', 0.6, 18.0, 'Juega con sus congéneres chocando sus enormes colmillos con la tranquilidad de saber que, si se le rompen, se regenerarán enseguida.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/610.png', 'Ambos', 'unova', FALSE, FALSE),
    (611, 'Fraxure', 1.0, 36.0, 'Su piel es dura como una coraza. Su técnica predilecta consiste en embestir al rival para hincarle los colmillos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/611.png', 'Ambos', 'unova', FALSE, FALSE),
    (612, 'Haxorus', 1.8, 105.5, 'Amable por naturaleza, infunde auténtico pavor al enfadarse. Su mayor baza son los colmillos, con los que puede cortar un armazón de acero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/612.png', 'Ambos', 'unova', FALSE, FALSE),
    (613, 'Cubchoo', 0.5, 8.5, 'Antes de ejecutar un movimiento, se sorbe los mocos. El frío intenso de estos constituye la base de sus movimientos de tipo Hielo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/613.png', 'Ambos', 'unova', FALSE, FALSE),
    (614, 'Beartic', 2.6, 260.0, 'Nada plácidamente en mares fríos. Cuando se cansa, congela el agua con su aliento y reposa sobre el hielo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/614.png', 'Ambos', 'unova', FALSE, FALSE),
    (615, 'Cryogonal', 1.1, 148.0, 'Cuando aumenta su temperatura corporal, se convierte en vapor, por lo que es muy difícil de avistar durante el verano.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/615.png', 'Sin género', 'unova', FALSE, FALSE),
    (616, 'Shelmet', 0.4, 7.7, 'Debido a su peculiar constitución, reacciona ante la energía eléctrica. Por alguna misteriosa razón, evoluciona en presencia de Karrablast.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/616.png', 'Ambos', 'unova', FALSE, FALSE),
    (617, 'Accelgor', 0.8, 25.3, 'Tras deshacerse del caparazón, su agilidad ha aumentado. Las membranas que le recubren el cuerpo evitan que se deshidrate.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/617.png', 'Ambos', 'unova', FALSE, FALSE),
    (618, 'Stunfisk', 0.7, 11.0, 'Se desconoce la razón, pero esboza una leve sonrisa al liberar potentes descargas eléctricas a través de las zonas amarillentas de su cuerpo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/618.png', 'Ambos', 'unova', FALSE, FALSE),
    (619, 'Mienfoo', 0.9, 20.0, 'Su apariencia menuda contrasta con su carácter poco afable. Abruma a los rivales que se acercan a él con gráciles oleadas de ataques sucesivos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/619.png', 'Ambos', 'unova', FALSE, FALSE),
    (620, 'Mienshao', 1.4, 35.5, 'Sus veloces patadas, que escapan al ojo humano, son capaces de reducir a escombros incluso rocas de gran tamaño.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/620.png', 'Ambos', 'unova', FALSE, FALSE),
    (621, 'Druddigon', 1.6, 139.0, 'Posee una personalidad despiadada y ladina. Se apropia de los túneles excavados por otros Pokémon y los habita.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/621.png', 'Ambos', 'unova', FALSE, FALSE),
    (622, 'Golett', 1.0, 92.0, 'Fue creado a partir del barro para emplearlo como sirviente. Todavía acata las órdenes que le dio su amo hace milenios.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/622.png', 'Sin género', 'unova', FALSE, FALSE),
    (623, 'Golurk', 2.8, 330.0, 'Se dice que su cuerpo alberga un móvil perpetuo que genera energía, pero no se ha constatado la veracidad de tamaña afirmación.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/623.png', 'Sin género', 'unova', FALSE, FALSE),
    (624, 'Pawniard', 0.5, 10.2, 'Forman grupos encabezados por un Bisharp. Se entrenan a diario soñando con llegar a liderar el grupo algún día.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/624.png', 'Ambos', 'unova', FALSE, FALSE),
    (625, 'Bisharp', 1.6, 70.0, 'Libra encarnizados combates con los Fraxure por el control de los emplazamientos donde se hallan las piedras con las que afila sus cuchillas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/625.png', 'Ambos', 'unova', FALSE, FALSE),
    (626, 'Bouffalant', 1.6, 94.6, 'Forman manadas de unos veinte individuos. Se desconoce el motivo, pero los que traicionan la confianza del grupo pierden la melena.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/626.png', 'Ambos', 'unova', FALSE, FALSE),
    (627, 'Rufflet', 0.5, 10.5, 'Es capaz de partir hasta la baya más dura gracias a la fuerza de sus extremidades. Belicoso por naturaleza, planta cara a cualquiera.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/627.png', 'Macho', 'unova', FALSE, FALSE),
    (628, 'Braviary', 1.5, 41.0, 'Su carácter agresivo e irascible le ha hecho perder su puesto como transportista en Galar en favor de los Corviknight.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/628.png', 'Macho', 'unova', FALSE, FALSE),
    (629, 'Vullaby', 0.5, 9.0, 'Deja en el nido las calaveras que va descartando a medida que crece con celeridad para que las reutilicen futuras generaciones.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/629.png', 'Hembra', 'unova', FALSE, FALSE),
    (630, 'Mandibuzz', 1.2, 39.5, 'Se engalana con los huesos que va recogiendo. Al parecer, la elección no es casual, sino que obedece a los dictados de la moda.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/630.png', 'Hembra', 'unova', FALSE, FALSE),
    (631, 'Heatmor', 1.4, 58.0, 'Usa llamas a modo de lengua para derretir el duro exoesqueleto de los Durant antes de devorarlos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/631.png', 'Ambos', 'unova', FALSE, FALSE),
    (632, 'Durant', 0.3, 33.0, 'Con sus grandes mandíbulas puede destrozar incluso rocas. Lucha en grupo para proteger sus larvas del ataque de los Sandaconda.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/632.png', 'Ambos', 'unova', FALSE, FALSE),
    (633, 'Deino', 0.8, 17.3, 'Al no poder ver, su forma de orientarse y percibir el entorno consiste en chocarse a diestro y siniestro, mordiendo todo lo que se encuentra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/633.png', 'Ambos', 'unova', FALSE, FALSE),
    (634, 'Zweilous', 1.4, 50.0, 'Las dos cabezas se disputan la comida con brutalidad. Por eso siempre está cubierto de heridas, aunque no haya combatido contra nadie.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/634.png', 'Ambos', 'unova', FALSE, FALSE),
    (635, 'Hydreigon', 1.8, 160.0, 'Sus tres cabezas se alternan para dar mordiscos y no cejarán en su ataque hasta que el rival haya caído redondo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/635.png', 'Ambos', 'unova', FALSE, FALSE),
    (636, 'Larvesta', 1.1, 28.8, 'Su cuerpo es cálido. Expulsa llamaradas por los cuernos con el fin de intimidar a sus enemigos y presas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/636.png', 'Ambos', 'unova', FALSE, FALSE),
    (637, 'Volcarona', 1.6, 46.0, 'Nace de una pupa envuelta en llamas. En algunas pinturas rupestres aparece representado como una deidad del fuego.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/637.png', 'Ambos', 'unova', FALSE, FALSE),
    (638, 'Cobalion', 2.1, 250.0, 'Un líder nato. Incluso los Pokémon más agresivos se muestran dóciles en su presencia.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/638.png', 'Sin género', 'unova', TRUE, FALSE),
    (639, 'Terrakion', 1.9, 260.0, 'Las leyendas de Teselia narran la lucha que libró contra los humanos para proteger a los Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/639.png', 'Sin género', 'unova', TRUE, FALSE),
    (640, 'Virizion', 2.0, 200.0, 'Confunde a los enemigos con sus movimientos relampagueantes y luego los rebana sin piedad con sus afilados cuernos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/640.png', 'Sin género', 'unova', TRUE, FALSE),
    (641, 'Tornadus', 1.5, 63.0, 'La energía que desprende de su cola genera violentas tempestades capaces de echar abajo casas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/641.png', 'Macho', 'unova', TRUE, FALSE),
    (642, 'Thundurus', 1.5, 61.0, 'Su gusto por surcar el cielo lanzando rayos y provocando incendios forestales le ha granjeado pocas simpatías.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/642.png', 'Macho', 'unova', TRUE, FALSE),
    (643, 'Reshiram', 3.2, 330.0, 'Cuenta la leyenda que sus llamas reducirán a cenizas todo país cuyas gentes desprecien la verdad y estén mancilladas por la codicia.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/643.png', 'Sin género', 'unova', TRUE, FALSE),
    (644, 'Zekrom', 2.9, 345.0, 'Según las leyendas, la furia de sus rayos fulminará todo país cuyas gentes hayan perdido el sentido de la justicia.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/644.png', 'Sin género', 'unova', TRUE, FALSE),
    (645, 'Landorus', 1.5, 68.0, 'Utiliza energía que obtiene del viento y del relámpago para nutrir el suelo y generar abundantes cosechas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/645.png', 'Macho', 'unova', TRUE, FALSE),
    (646, 'Kyurem', 3.0, 325.0, 'Mantiene su cuerpo congelado con la intensa energía gélida que él mismo produce para estabilizar su estructura celular.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/646.png', 'Sin género', 'unova', TRUE, FALSE),
    (647, 'Keldeo', 1.4, 48.5, 'A base de superar encarnizados combates, su cuerno se fortalece y, entonces, despierta su verdadero poder.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/647.png', 'Sin género', 'unova', FALSE, TRUE),
    (648, 'Meloetta', 0.6, 6.5, 'Controla los sentimientos de los que escuchan las melodías que emite con su singular vocalización.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/648.png', 'Sin género', 'unova', FALSE, TRUE),
    (649, 'Genesect', 1.5, 82.5, 'Un Pokémon de hace 300 millones de años y alterado por el Equipo Plasma, quienes le han equipado con un cañón en el lomo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/649.png', 'Sin género', 'unova', FALSE, TRUE),
    (650, 'Chespin', 0.4, 9.0, 'La robusta coraza que le recubre la cabeza y la espalda lo protege de tal manera que podría chocar contra un camión y permanecer impasible.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/650.png', 'Ambos', 'kalos', FALSE, FALSE),
    (651, 'Quilladin', 0.7, 29.0, 'Chocan contra sus congéneres para fortalecer sus piernas. Debido a su carácter afable, nunca son los que provocan un combate.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/651.png', 'Ambos', 'kalos', FALSE, FALSE),
    (652, 'Chesnaught', 1.6, 90.0, 'Cuando adopta una postura defensiva juntando ambos puños delante de la cara, es capaz de resistir incluso el impacto directo de una bomba.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/652.png', 'Ambos', 'kalos', FALSE, FALSE),
    (653, 'Fennekin', 0.4, 9.4, 'Mordisquea una ramita mientras camina, como si de un aperitivo se tratase. Intimida a su enemigo expulsando aire caliente por las orejas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/653.png', 'Ambos', 'kalos', FALSE, FALSE),
    (654, 'Braixen', 1.0, 14.5, 'Al extraer la rama que tiene en la cola, esta prende debido a la fricción. Usa esa rama candente para enviar señales a sus compañeros.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/654.png', 'Ambos', 'kalos', FALSE, FALSE),
    (655, 'Delphox', 1.5, 39.0, 'Sus poderes psíquicos le permiten controlar vórtices de fuego a 3000 °C que envuelven y calcinan a sus enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/655.png', 'Ambos', 'kalos', FALSE, FALSE),
    (656, 'Froakie', 0.3, 7.0, 'Protege su piel cubriendo el cuerpo con una fina capa de burbujas. Aunque parezca despreocupado, no deja de vigilar con astucia lo que le rodea.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/656.png', 'Ambos', 'kalos', FALSE, FALSE),
    (657, 'Frogadier', 0.6, 10.9, 'Su agilidad no tiene parangón. De hecho, es capaz de escalar una torre de más de 600 metros en tan solo un minuto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/657.png', 'Ambos', 'kalos', FALSE, FALSE),
    (658, 'Greninja', 1.5, 40.0, 'Aparece y desaparece de improvisto, cual ninja. Marea al oponente con su soberbia agilidad y lo hace trizas con sus Shuriken de Agua.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/658.png', 'Ambos', 'kalos', FALSE, FALSE),
    (659, 'Bunnelby', 0.4, 5.0, 'Está en alerta permanente. En cuanto oye el batir de alas de un Corviknight, cava un agujero y se oculta bajo tierra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/659.png', 'Ambos', 'kalos', FALSE, FALSE),
    (660, 'Diggersby', 1.0, 42.4, 'El pelaje de su abdomen es un aislante térmico excelente, tanto que antaño se usaba el que mudaba para confeccionar prendas de abrigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/660.png', 'Ambos', 'kalos', FALSE, FALSE),
    (661, 'Fletchling', 0.3, 1.7, 'Su temperatura corporal aumenta de repente cuando se exalta y puede causar quemaduras al contacto con la piel.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/661.png', 'Ambos', 'kalos', FALSE, FALSE),
    (662, 'Fletchinder', 0.7, 16.0, 'Defienden su territorio con suma agresividad. Se pelean entre sí por el control de las áreas de caza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/662.png', 'Ambos', 'kalos', FALSE, FALSE),
    (663, 'Talonflame', 1.2, 24.5, 'Arremete contra sus presas a una velocidad de 500 km/h y les asesta el golpe de gracia con una patada muy potente, sin dejarles escapatoria.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/663.png', 'Ambos', 'kalos', FALSE, FALSE),
    (664, 'Scatterbug', 0.3, 2.5, 'Gracias al polvo de escamas que lo recubre y regula su temperatura, puede vivir en cualquier región, sin importar las características del terreno o el clima.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/664.png', 'Ambos', 'kalos', FALSE, FALSE),
    (665, 'Spewpa', 0.3, 8.4, 'Su cuerpo es tan duro que ni siquiera los Pokémon pájaro pueden hacerle el menor rasguño con sus picos. Esparce polvo de escamas para defenderse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/665.png', 'Ambos', 'kalos', FALSE, FALSE),
    (666, 'Vivillon', 1.2, 17.0, 'Las alas cambian de motivo según el clima y las características naturales del terreno que habite. Esparce escamas de lo más coloridas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/666.png', 'Ambos', 'kalos', FALSE, FALSE),
    (667, 'Litleo', 0.6, 13.5, 'Este enérgico Pokémon es de naturaleza curiosa e inquieta y, tanto al comienzo de un combate como cuando se enoja, su crin prende fuego.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/667.png', 'Ambos', 'kalos', FALSE, FALSE),
    (668, 'Pyroar', 1.5, 81.5, 'Su aliento alcanza temperaturas de 6000 ºC, aunque no lo emplea contra sus presas, ya que prefiere la carne más bien cruda.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/668.png', 'Ambos', 'kalos', FALSE, FALSE),
    (669, 'Flabébé', 0.1, 0.1, 'Acumula el polen de las flores para confeccionar la tiara que lleva en la cabeza, que cuenta con propiedades curativas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/669.png', 'Hembra', 'kalos', FALSE, FALSE),
    (670, 'Floette', 0.2, 0.9, 'Confiere su poder a las flores y cuida de ellas con mucho esmero; no perdona que destruyan los campos donde estas crecen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/670.png', 'Hembra', 'kalos', FALSE, FALSE),
    (671, 'Florges', 1.1, 10.0, 'Su esperanza de vida asciende a varios siglos y dedica toda su dilatada existencia al cuidado de los jardines.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/671.png', 'Hembra', 'kalos', FALSE, FALSE),
    (672, 'Skiddo', 0.9, 31.0, 'Puede generar energía con las hojas que tiene en la espalda disponiendo tan solo de agua y luz solar. Gracias a ello puede sobrevivir sin comer.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/672.png', 'Ambos', 'kalos', FALSE, FALSE),
    (673, 'Gogoat', 1.7, 91.0, 'Habita en regiones montañosas. El líder de la manada se decide en una demostración de fuerza en la que los contendientes luchan con los cuernos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/673.png', 'Ambos', 'kalos', FALSE, FALSE),
    (674, 'Pancham', 0.6, 8.0, 'Siempre lanza una mirada fulminante al rival para que no lo menosprecie, pero en cuanto se relaja esboza sin querer una sonrisa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/674.png', 'Ambos', 'kalos', FALSE, FALSE),
    (675, 'Pangoro', 2.1, 136.0, 'La hoja que lleva en la boca le permite predecir los movimientos del rival. Puede reducir un camión a chatarra de un solo puñetazo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/675.png', 'Ambos', 'kalos', FALSE, FALSE),
    (676, 'Furfrou', 1.2, 28.0, 'El pelo le crece sin cesar, pero solo deja que se lo corten aquellos de quienes se fía plenamente.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/676.png', 'Ambos', 'kalos', FALSE, FALSE),
    (677, 'Espurr', 0.3, 3.5, 'Es capaz de mandar por los aires a un luchador profesional gracias a sus poderes psíquicos, pero tiene serios problemas para controlarlos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/677.png', 'Ambos', 'kalos', FALSE, FALSE),
    (678, 'Meowstic', 0.6, 8.5, 'El fuerte instinto protector de los machos los lleva a liberar todo su poder cuando se trata de defenderse a sí mismos o a su Entrenador.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/678.png', 'Ambos', 'kalos', FALSE, FALSE),
    (679, 'Honedge', 0.8, 2.0, 'El ojo azul de la empuñadura es su verdadero cuerpo. Absorbe la energía vital de las personas con su paño de aspecto andrajoso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/679.png', 'Ambos', 'kalos', FALSE, FALSE),
    (680, 'Doublade', 0.8, 4.5, 'Su táctica para abatir a las presas consiste en alternar ataque y defensa de forma frenética entre ambas espadas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/680.png', 'Ambos', 'kalos', FALSE, FALSE),
    (681, 'Aegislash', 1.7, 53.0, 'Mediante el control ejercido con su inmenso poder espectral, logró que humanos y Pokémon le forjaran un país a medida de sus necesidades.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/681.png', 'Ambos', 'kalos', FALSE, FALSE),
    (682, 'Spritzee', 0.2, 0.5, 'Su cuerpo emana una fragancia que embelesa a quien la huele. Llegó a ser muy apreciado entre las damas de la nobleza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/682.png', 'Ambos', 'kalos', FALSE, FALSE),
    (683, 'Aromatisse', 0.8, 15.5, 'Puede emanar tanto un olor desagradable para desmotivar al rival como un dulce aroma para reconfortar a los aliados en combate.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/683.png', 'Ambos', 'kalos', FALSE, FALSE),
    (684, 'Swirlix', 0.4, 3.5, 'Su esponjoso pelaje desprende un olor dulzón como el del algodón de azúcar. Escupe hebras pegajosas con las que envuelve a sus enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/684.png', 'Ambos', 'kalos', FALSE, FALSE),
    (685, 'Slurpuff', 0.8, 5.0, 'La gran cantidad de aire acumulada en su pelaje le confiere un tacto aterciopelado y un peso muy inferior al que aparenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/685.png', 'Ambos', 'kalos', FALSE, FALSE),
    (686, 'Inkay', 0.4, 3.5, 'Los destellos de luz intermitente que emite aplacan el ánimo de lucha del enemigo, tras lo que aprovecha para esconderse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/686.png', 'Ambos', 'kalos', FALSE, FALSE),
    (687, 'Malamar', 1.5, 47.0, 'Se dice que sus poderes hipnóticos han influido en grandes acontecimientos que han cambiado el curso de la historia.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/687.png', 'Ambos', 'kalos', FALSE, FALSE),
    (688, 'Binacle', 0.5, 31.0, 'Si no se llevan bien, no consiguen ni atacar ni defenderse de forma eficaz y sus probabilidades de supervivencia se reducen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/688.png', 'Ambos', 'kalos', FALSE, FALSE),
    (689, 'Barbaracle', 1.3, 96.0, 'Los ojos de las manos le permiten ver en todas direcciones. En caso de apuro, sus extremidades se mueven solas para derribar al enemigo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/689.png', 'Ambos', 'kalos', FALSE, FALSE),
    (690, 'Skrelp', 0.5, 7.3, 'Su aspecto de alga podrida le permite ocultarse entre los restos que flotan a la deriva y pasar desapercibido ante sus enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/690.png', 'Ambos', 'kalos', FALSE, FALSE),
    (691, 'Dragalge', 1.8, 81.5, 'Asoma la cresta de la cabeza sobre la superficie del agua y transforma la luz que absorbe del sol en energía dragón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/691.png', 'Ambos', 'kalos', FALSE, FALSE),
    (692, 'Clauncher', 0.5, 8.3, 'Acalla a sus enemigos con balas de agua que dispara haciendo explotar el gas de su pinza derecha.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/692.png', 'Ambos', 'kalos', FALSE, FALSE),
    (693, 'Clawitzer', 1.3, 35.3, 'Con el cañón de su brazo derecho dispara proyectiles de agua marina con tanta potencia que son capaces de hundir un petrolero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/693.png', 'Ambos', 'kalos', FALSE, FALSE),
    (694, 'Helioptile', 0.5, 6.0, 'Es capaz de generar electricidad a partir de la luz del sol. Si lo interrumpen en pleno proceso, se pone nervioso y pierde las fuerzas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/694.png', 'Ambos', 'kalos', FALSE, FALSE),
    (695, 'Heliolisk', 1.0, 21.0, 'Al extender su gorguera y exponerse a la luz solar, genera la energía eléctrica suficiente para cubrir el consumo de una metrópoli entera.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/695.png', 'Ambos', 'kalos', FALSE, FALSE),
    (696, 'Tyrunt', 0.8, 26.0, 'Un Pokémon un tanto egoísta y malcriado. Puede ocasionar graves lesiones a su Entrenador incluso jugando.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/696.png', 'Ambos', 'kalos', FALSE, FALSE),
    (697, 'Tyrantrum', 2.5, 270.0, 'Puede hacer trizas un coche de un solo mordisco gracias a sus potentes mandíbulas. Antaño era considerado un rey.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/697.png', 'Ambos', 'kalos', FALSE, FALSE),
    (698, 'Amaura', 1.3, 25.2, 'Un Pokémon prehistórico extinto. Se han hallado algunos ejemplares conservados bajo el hielo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/698.png', 'Ambos', 'kalos', FALSE, FALSE),
    (699, 'Aurorus', 2.7, 225.0, 'Cuando se deja llevar por la ira, emite un vaho extremadamente gélido que lo congela todo a su alrededor.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/699.png', 'Ambos', 'kalos', FALSE, FALSE),
    (700, 'Sylveon', 1.0, 23.5, 'En un cuento infantil de Galar se narra la victoria de un Sylveon de extraordinaria belleza sobre un temible Pokémon de tipo Dragón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/700.png', 'Ambos', 'kalos', FALSE, FALSE),
    (701, 'Hawlucha', 0.8, 21.5, 'Siempre se exhibe con alguna pose justo antes de propinar el golpe de gracia, momento que algunos rivales aprovechan para contraatacar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/701.png', 'Ambos', 'kalos', FALSE, FALSE),
    (702, 'Dedenne', 0.2, 2.2, 'Su capacidad para producir electricidad es muy limitada, de modo que tiene que robarla de las tomas de corriente o de otros Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/702.png', 'Ambos', 'kalos', FALSE, FALSE),
    (703, 'Carbink', 0.3, 5.7, 'Se cree que en algún lugar de este mundo existe un filón rebosante de Carbink que viven bajo las órdenes de una reina.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/703.png', 'Sin género', 'kalos', FALSE, FALSE),
    (704, 'Goomy', 0.3, 2.8, 'Sus antenas son órganos sensoriales sumamente desarrollados. Poder esconderse nada más detectar enemigos le ha permitido sobrevivir.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/704.png', 'Ambos', 'kalos', FALSE, FALSE),
    (705, 'Sliggoo', 0.8, 17.5, 'La protuberancia del lomo contiene su pequeño cerebro, que solo piensa en buscar comida y huir de los enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/705.png', 'Ambos', 'kalos', FALSE, FALSE),
    (706, 'Goodra', 2.0, 150.5, 'Ataca extendiendo sus largas antenas. La fuerza que despliega es 100 veces superior a la del puñetazo de un boxeador de peso pesado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/706.png', 'Ambos', 'kalos', FALSE, FALSE),
    (707, 'Klefki', 0.2, 3.0, 'Según parece, absorbe iones metálicos por el apéndice de la cabeza para adoptar una forma similar a la de sus amadas llaves.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/707.png', 'Ambos', 'kalos', FALSE, FALSE),
    (708, 'Phantump', 0.4, 7.0, 'Imita el llanto de un niño con la intención de que algún adulto se adentre y se pierda en lo más profundo del bosque.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/708.png', 'Ambos', 'kalos', FALSE, FALSE),
    (709, 'Trevenant', 1.5, 71.0, 'Puede extender las finas raíces que le brotan de las extremidades inferiores para conectarse con el resto de los árboles y controlarlos a voluntad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/709.png', 'Ambos', 'kalos', FALSE, FALSE),
    (710, 'Pumpkaboo', 0.4, 5.0, 'La luz que emite por los orificios de la calabaza hipnotiza a humanos y Pokémon y los deja bajo su control.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/710.png', 'Ambos', 'kalos', FALSE, FALSE),
    (711, 'Gourgeist', 0.9, 12.5, 'Las noches de luna nueva llama a la puerta de las casas y se lleva al otro mundo a quien abra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/711.png', 'Ambos', 'kalos', FALSE, FALSE),
    (712, 'Bergmite', 1.0, 99.5, 'Vive en regiones sumamente frías. Se aferra al lomo de los Avalugg congelando sus propias extremidades.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/712.png', 'Ambos', 'kalos', FALSE, FALSE),
    (713, 'Avalugg', 2.0, 505.0, 'Las fisuras de su cuerpo se agrandan durante el día, pero por la noche vuelven a cerrarse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/713.png', 'Ambos', 'kalos', FALSE, FALSE),
    (714, 'Noibat', 0.5, 8.0, 'Su registro vocal cubre todo el espectro de frecuencias. Ni los Pokémon más grandes soportan las ondas ultrasónicas que emite.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/714.png', 'Ambos', 'kalos', FALSE, FALSE),
    (715, 'Noivern', 1.5, 85.0, 'Vuela en la oscuridad atormentando al enemigo con ondas ultrasónicas capaces de partir rocas antes de rematarlo con sus afilados colmillos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/715.png', 'Ambos', 'kalos', FALSE, FALSE),
    (716, 'Xerneas', 3.0, 215.0, 'Cuando los cuernos de su cabeza brillan en siete colores, se dice que comparte el don de la vida eterna.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/716.png', 'Sin género', 'kalos', TRUE, FALSE),
    (717, 'Yveltal', 5.8, 203.0, 'Cuando su vida se extingue, absorbe la vitalidad de todos los seres vivos y regresa a su forma de crisálida.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/717.png', 'Sin género', 'kalos', TRUE, FALSE),
    (718, 'Zygarde', 5.0, 305.0, 'Según los rumores, puede adoptar una forma aún más poderosa cuando se enfrenta a quienquiera que amenace el ecosistema.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/718.png', 'Sin género', 'kalos', TRUE, FALSE),
    (719, 'Diancie', 0.7, 8.8, 'Puede crear una gran cantidad de diamantes en un instante comprimiendo con las manos el carbono que flota en el aire.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/719.png', 'Sin género', 'kalos', FALSE, TRUE),
    (720, 'Hoopa', 0.5, 9.0, 'Dicen que gracias a sus seis anillos y seis enormes brazos puede robar todo lo que se le antoja. Adquirió una forma reducida cuando alguien selló su poder.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/720.png', 'Sin género', 'kalos', FALSE, TRUE),
    (721, 'Volcanion', 1.7, 195.0, 'Expulsa vapor de agua por los brazos que tiene en la espalda. Sale a tal potencia que sería capaz de arrasar una montaña entera.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/721.png', 'Sin género', 'kalos', FALSE, TRUE),
    (722, 'Rowlet', 0.3, 1.5, 'Durante el día acumula energía mediante la fotosíntesis y, al caer la noche, vuela sin hacer ruido en busca de presas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/722.png', 'Ambos', 'alola', FALSE, FALSE),
    (723, 'Dartrix', 0.7, 16.0, 'Jamás desatiende el cuidado de sus alas, no solo por mera cuestión estética, sino también para mantener las plumas perfectamente afiladas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/723.png', 'Ambos', 'alola', FALSE, FALSE),
    (724, 'Decidueye', 1.6, 36.6, 'Tan solo le lleva una décima de segundo sacar una pluma y disparar al rival, a quien acierta en un punto vital antes de que pueda darse cuenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/724.png', 'Ambos', 'alola', FALSE, FALSE),
    (725, 'Litten', 0.4, 4.3, 'Quien trate de acariciarlo antes de ganarse su plena confianza se arriesga a comprobar de primera mano lo afiladas que están sus garras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/725.png', 'Ambos', 'alola', FALSE, FALSE),
    (726, 'Torracat', 0.7, 25.0, 'Enfrentarse a un adversario formidable aviva tanto su espíritu combativo como la energía térmica de su cascabel.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/726.png', 'Ambos', 'alola', FALSE, FALSE),
    (727, 'Incineroar', 1.8, 83.0, 'A pesar de que a menudo se comporta de forma violenta, tiene un lado amable que se manifiesta cuando ayuda a Pokémon más pequeños.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/727.png', 'Ambos', 'alola', FALSE, FALSE),
    (728, 'Popplio', 0.4, 7.5, 'Entrena con ahínco a diario hasta que por fin es capaz de crear globos de un tamaño y eficacia adecuados.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/728.png', 'Ambos', 'alola', FALSE, FALSE),
    (729, 'Brionne', 0.6, 17.5, 'Las noches en las que el mar está en calma, baila junto a sus congéneres al compás del canto de su líder, Primarina.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/729.png', 'Ambos', 'alola', FALSE, FALSE),
    (730, 'Primarina', 1.8, 44.0, 'Considera el terreno de combate un escenario desde el que encandilar al público con su canto y la coreografía de sus globos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/730.png', 'Ambos', 'alola', FALSE, FALSE),
    (731, 'Pikipek', 0.3, 1.2, 'Pese a su fino aspecto, tiene la musculatura del cuello muy desarrollada: agujerea los árboles a una velocidad de 16 picotazos por segundo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/731.png', 'Ambos', 'alola', FALSE, FALSE),
    (732, 'Trumbeak', 0.6, 14.8, 'Dispara por el pico las semillas de las bayas ingeridas. Al dispersarse por el suelo, de ellas acaban germinando nuevas plantas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/732.png', 'Ambos', 'alola', FALSE, FALSE),
    (733, 'Toucannon', 1.1, 26.0, 'Las parejas de Toucannon son famosas por la armonía que reina entre ellas. Por eso se llevan a las bodas como portadores de buena fortuna.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/733.png', 'Ambos', 'alola', FALSE, FALSE),
    (734, 'Yungoos', 0.4, 6.0, 'Pese a ser omnívoro, siente predilección por los alimentos frescos o incluso seres vivos. Por eso marcha por los caminos en busca de presas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/734.png', 'Ambos', 'alola', FALSE, FALSE),
    (735, 'Gumshoos', 0.7, 14.2, 'Tiene un carácter muy paciente, pero en cuanto avista un Rattata, su manjar predilecto, pierde el control y se lanza sobre él como un poseso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/735.png', 'Ambos', 'alola', FALSE, FALSE),
    (736, 'Grubbin', 0.4, 4.4, 'Cava su madriguera en el lecho boscoso con sus grandes mandíbulas. Le encanta la savia dulce de los árboles.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/736.png', 'Ambos', 'alola', FALSE, FALSE),
    (737, 'Charjabug', 0.5, 10.5, 'Al digerir la hojarasca de la que se alimenta, genera energía eléctrica que almacena en la bolsa que posee para tal efecto.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/737.png', 'Ambos', 'alola', FALSE, FALSE),
    (738, 'Vikavolt', 1.5, 45.0, 'Cuando vuela llevando consigo un Charjabug a modo de batería adicional, puede liberar potentes descargas electromagnéticas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/738.png', 'Ambos', 'alola', FALSE, FALSE),
    (739, 'Crabrawler', 0.6, 7.0, 'A veces trepa por Exeggutor al confundirlo con una palmera de verdad. Este, presa de la ira, se desembaraza de él a sacudidas y lo pisotea.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/739.png', 'Ambos', 'alola', FALSE, FALSE),
    (740, 'Crabominable', 1.7, 180.0, 'No se lo piensa dos veces a la hora de zurrar. Se tiene constancia de que sus puñetazos frenéticos han llegado a detener aludes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/740.png', 'Ambos', 'alola', FALSE, FALSE),
    (741, 'Oricorio', 0.6, 3.4, 'Forma que toma Oricorio al libar Néctar Rojo. Su vehemencia le lleva a ponerse hecho una furia si el Entrenador le imparte la orden equivocada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/741.png', 'Ambos', 'alola', FALSE, FALSE),
    (742, 'Cutiefly', 0.1, 0.2, 'Al percibir el aura del rival, puede predecir sus movimientos y esquivarlos sin problema mientras lanza su contraataque.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/742.png', 'Ambos', 'alola', FALSE, FALSE),
    (743, 'Ribombee', 0.2, 0.5, 'Detesta verse empapado por la lluvia, por lo que rara vez se deja ver en la nubosa región de Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/743.png', 'Ambos', 'alola', FALSE, FALSE),
    (744, 'Rockruff', 0.5, 9.2, 'Intimida a los rivales golpeando contra el suelo las rocas que tiene en el cuello y, tan pronto como retroceden, se abalanza sobre ellos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/744.png', 'Ambos', 'alola', FALSE, FALSE),
    (745, 'Lycanroc', 0.8, 25.0, 'Va acorralando pacientemente a su presa con movimientos raudos para finalmente clavarle los colmillos en sus puntos vitales.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/745.png', 'Ambos', 'alola', FALSE, FALSE),
    (746, 'Wishiwashi', 0.2, 0.3, 'Al sentirse amenazado, le lloran los ojos. La luz que se refleja en sus lágrimas sirve de señal a sus congéneres para agruparse en gran número.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/746.png', 'Ambos', 'alola', FALSE, FALSE),
    (747, 'Mareanie', 0.4, 8.0, 'A diferencia de sus congéneres de Alola, los ejemplares de Galar aún no saben lo deliciosas que están las ramas de Corsola.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/747.png', 'Ambos', 'alola', FALSE, FALSE),
    (748, 'Toxapex', 0.7, 14.5, 'La bolsa de veneno en el interior de su cuerpo contiene toxinas tan potentes que provocarían tres días de dolores intensos hasta a un Wailord.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/748.png', 'Ambos', 'alola', FALSE, FALSE),
    (749, 'Mudbray', 1.0, 110.0, 'Tras recubrir sus patas con el lodo que crea masticando tierra, puede recorrer los peores caminos sin temor a resbalar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/749.png', 'Ambos', 'alola', FALSE, FALSE),
    (750, 'Mudsdale', 2.5, 920.0, 'Su resistencia le permitiría recorrer Galar de punta a punta sin un solo descanso portando cargas de más de diez toneladas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/750.png', 'Ambos', 'alola', FALSE, FALSE),
    (751, 'Dewpider', 0.3, 4.0, 'Vive bajo el agua y, cuando emerge a tierra firme en busca de presas, se recubre la cabeza con una burbuja.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/751.png', 'Ambos', 'alola', FALSE, FALSE),
    (752, 'Araquanid', 1.8, 82.0, 'Cuida de pequeños Dewpider acogiéndolos en su burbuja de agua y dejando que se alimenten de los restos de las presas que ha ingerido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/752.png', 'Ambos', 'alola', FALSE, FALSE),
    (753, 'Fomantis', 0.3, 1.5, 'De día duerme tranquilamente a la luz del sol y, al ocaso, despierta e inicia su actividad nocturna.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/753.png', 'Ambos', 'alola', FALSE, FALSE),
    (754, 'Lurantis', 0.9, 18.5, 'Los pétalos de sus brazos son finos y afilados. Absorbe la luz solar y la concentra para lanzar poderosos rayos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/754.png', 'Ambos', 'alola', FALSE, FALSE),
    (755, 'Morelull', 0.2, 1.5, 'Vive en bosques umbríos. Esparce a su alrededor esporas titilantes que adormecen a sus enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/755.png', 'Ambos', 'alola', FALSE, FALSE),
    (756, 'Shiinotic', 1.0, 11.5, 'Conviene no acercarse si se avistan luces en la espesura del bosque en plena noche, ya que podrían ser las esporas soporíferas de Shiinotic.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/756.png', 'Ambos', 'alola', FALSE, FALSE),
    (757, 'Salandit', 0.6, 4.8, 'Se aproxima a su presa por la espalda y, antes de que pueda advertirlo, la inmoviliza con un gas venenoso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/757.png', 'Ambos', 'alola', FALSE, FALSE),
    (758, 'Salazzle', 1.2, 22.2, 'Libran disputas con sus congéneres cuyo resultado, al parecer, se inclina por quien tenga un séquito de Salandit machos más numeroso.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/758.png', 'Hembra', 'alola', FALSE, FALSE),
    (759, 'Stufful', 0.5, 6.8, 'Cuando patalea para tratar de defenderse resulta adorable, pero conviene no fiarse, ya que su fuerza sería capaz de derribar un árbol.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/759.png', 'Ambos', 'alola', FALSE, FALSE),
    (760, 'Bewear', 2.1, 135.0, 'Después de abatir a su presa con movimientos que harían palidecer a un luchador profesional, la carga en brazos y se la lleva a su madriguera.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/760.png', 'Ambos', 'alola', FALSE, FALSE),
    (761, 'Bounsweet', 0.3, 3.2, 'Cuando lo atacan, produce un sudor dulce y delicioso cuyo aroma atrae a más enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/761.png', 'Hembra', 'alola', FALSE, FALSE),
    (762, 'Steenee', 0.7, 8.2, 'Si un Corvisquire viene a picotearlo, se defiende golpeándolo con el cáliz de la cabeza y con fuertes patadas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/762.png', 'Hembra', 'alola', FALSE, FALSE),
    (763, 'Tsareena', 1.2, 21.4, 'Propina patadas con sus duras y puntiagudas piernas, con las que deja heridas indelebles en el cuerpo y el corazón del adversario.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/763.png', 'Hembra', 'alola', FALSE, FALSE),
    (764, 'Comfey', 0.1, 0.3, 'Este Pokémon libera una agradable fragancia, que varía de individuo a individuo debido a que cada uno se engalana con flores diferentes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/764.png', 'Ambos', 'alola', FALSE, FALSE),
    (765, 'Oranguru', 1.5, 76.0, 'Conoce hasta el último rincón del bosque y, si encuentra un Pokémon herido, va en busca de hierbas medicinales para curarlo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/765.png', 'Ambos', 'alola', FALSE, FALSE),
    (766, 'Passimian', 2.0, 82.8, 'Viven en grupos de unos veinte ejemplares. Cada individuo tiene un rol definido, lo que les permite sobrevivir en entornos hostiles.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/766.png', 'Ambos', 'alola', FALSE, FALSE),
    (767, 'Wimpod', 0.5, 12.0, 'Forman colonias y permanecen siempre alerta. En cuanto perciben a un enemigo, salen huyendo en todas direcciones.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/767.png', 'Ambos', 'alola', FALSE, FALSE),
    (768, 'Golisopod', 2.0, 108.0, 'Vive en cavernas del fondo marino o en barcos hundidos. Lucha contra los Grapploct y el que pierde se convierte en una suculenta presa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/768.png', 'Ambos', 'alola', FALSE, FALSE),
    (769, 'Sandygast', 0.5, 70.0, 'Suele habitar en playas. Aumenta de tamaño al tomar control de todo aquel que se atreva a introducir la mano en su boca.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/769.png', 'Ambos', 'alola', FALSE, FALSE),
    (770, 'Palossand', 1.3, 250.0, 'Habita en las playas, aunque odia el agua. Cuando caen fuertes lluvias, no es capaz de preservar su forma de castillo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/770.png', 'Ambos', 'alola', FALSE, FALSE),
    (771, 'Pyukumuku', 0.3, 1.2, 'La formidable mucosidad que envuelve su piel lo mantiene hidratado y le permite permanecer en tierra firme varios días sin secarse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/771.png', 'Ambos', 'alola', FALSE, FALSE),
    (772, 'Código Cero', 1.9, 120.5, 'Fue creado a imagen de un Pokémon mitológico. Lleva una máscara de contención para evitar que su poder se descontrole.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/772.png', 'Sin género', 'alola', TRUE, FALSE),
    (773, 'Silvally', 2.3, 100.5, 'El factor decisivo que le ha permitido liberar toda su fuerza ha sido el estrecho vínculo y la confianza que profesa a su Entrenador.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/773.png', 'Sin género', 'alola', TRUE, FALSE),
    (774, 'Minior', 0.3, 40.0, 'Lo recubre un duro caparazón que se quiebra en pedazos al impactar con la superficie de la tierra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/774.png', 'Sin género', 'alola', FALSE, FALSE),
    (775, 'Komala', 0.4, 19.9, 'El motivo de su letargo vitalicio es la sustancia somnífera que contienen las hojas de las que se alimenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/775.png', 'Ambos', 'alola', FALSE, FALSE),
    (776, 'Turtonator', 2.0, 212.0, 'El material explosivo de su caparazón está compuesto por el azufre del que se alimenta. Sus excrementos explosivos son muy peligrosos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/776.png', 'Ambos', 'alola', FALSE, FALSE),
    (777, 'Togedemaru', 0.3, 3.3, 'Cuando se encuentra en peligro, se hace una bola, eriza las púas del lomo y propina descargas eléctricas a diestro y siniestro.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/777.png', 'Ambos', 'alola', FALSE, FALSE),
    (778, 'Mimikyu', 0.2, 0.7, 'Un investigador que miró dentro del saco para estudiar a este Pokémon perdió la vida a causa de una misteriosa enfermedad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/778.png', 'Ambos', 'alola', FALSE, FALSE),
    (779, 'Bruxish', 0.9, 19.0, 'Su piel es tan gruesa que ni las espinas de Mareanie pueden perforarla. Con su fuerte dentadura tritura y engulle dichas espinas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/779.png', 'Ambos', 'alola', FALSE, FALSE),
    (780, 'Drampa', 3.0, 185.0, 'Es de naturaleza mansa y amable, pero, si se enfurece, puede desatar fuertes vientos capaces de llevarse cualquier cosa por delante.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/780.png', 'Ambos', 'alola', FALSE, FALSE),
    (781, 'Dhelmise', 3.9, 210.0, 'Acecha a su presa hundiendo el ancla en el mar. Es capaz de drenar la vitalidad incluso de presas del tamaño de un Wailord.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/781.png', 'Sin género', 'alola', FALSE, FALSE),
    (782, 'Jangmo-o', 0.6, 29.7, 'Se comunica con sus congéneres mediante los sonidos que produce al golpear sus escamas, duras como el acero.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/782.png', 'Ambos', 'alola', FALSE, FALSE),
    (783, 'Hakamo-o', 1.2, 47.0, 'Tras hacer sonar sus escamas y proferir su grito de guerra, carga contra el enemigo y lo hace trizas con sus afiladas garras.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/783.png', 'Ambos', 'alola', FALSE, FALSE),
    (784, 'Kommo-o', 1.6, 78.2, 'Se han descubierto antiguas representaciones pictóricas de guerreros que lucían armaduras confeccionadas con escamas de Kommo-o.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/784.png', 'Ambos', 'alola', FALSE, FALSE),
    (785, 'Tapu Koko', 1.8, 20.5, 'El espíritu guardián de Melemele, capaz de blandir el rayo. Su eterna curiosidad le lleva a veces a mostrarse ante las personas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/785.png', 'Sin género', 'alola', TRUE, FALSE),
    (786, 'Tapu Lele', 1.2, 18.6, 'Este espíritu guardián es tan candoroso como despiadado, por lo que se podría decir que es la encarnación de la naturaleza misma.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/786.png', 'Sin género', 'alola', TRUE, FALSE),
    (787, 'Tapu Bulu', 1.9, 45.5, 'El espíritu guardián de Ula-Ula, que gobierna la flora. Hace repicar su cola para alertar de su presencia y prevenir riñas sin sentido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/787.png', 'Sin género', 'alola', TRUE, FALSE),
    (788, 'Tapu Fini', 1.3, 21.2, 'A pesar de ser un espíritu guardián, trae desgracias a aquellos que se le acercan sin la debida cortesía.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/788.png', 'Sin género', 'alola', TRUE, FALSE),
    (789, 'Cosmog', 0.2, 0.1, 'Su escasa prudencia y gran curiosidad lo llevan a menudo a ponerse en peligro. En caso de apuro, se teletransporta para huir.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/789.png', 'Sin género', 'alola', TRUE, FALSE),
    (790, 'Cosmoem', 0.1, 999.9, 'Absorbe impetuoso polvo de la atmósfera y pone todo su empeño en crear en su núcleo la energía necesaria para evolucionar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/790.png', 'Sin género', 'alola', TRUE, FALSE),
    (791, 'Solgaleo', 3.4, 230.0, 'Antiguamente era conocido como la Criatura que se Nutre del Sol. Emite sin cesar una energía luminosa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/791.png', 'Sin género', 'alola', TRUE, FALSE),
    (792, 'Lunala', 4.0, 120.0, 'Devora toda la luz que haya a su alrededor y adopta la forma de una luna llena que ilumina la oscura noche.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/792.png', 'Sin género', 'alola', TRUE, FALSE),
    (793, 'Nihilego', 1.2, 55.5, 'Llegó a este mundo a través de un Ultraumbral. Es un parásito que se aprovecha de Pokémon y personas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/793.png', 'Sin género', 'alola', FALSE, FALSE),
    (794, 'Buzzwole', 2.4, 333.6, 'Uno de los Ultraentes. Posee una musculatura excesivamente desarrollada.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/794.png', 'Sin género', 'alola', FALSE, FALSE),
    (795, 'Pheromosa', 1.8, 25.0, 'Para los seres de este mundo resulta extraño y peligroso, pero en el mundo del que procede es una criatura muy común.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/795.png', 'Sin género', 'alola', FALSE, FALSE),
    (796, 'Xurkitree', 3.8, 100.0, 'Uno de los llamados Ultraentes. Algunos ejemplares plantan sus extremidades en el suelo como si fueran árboles y permanecen inmóviles.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/796.png', 'Sin género', 'alola', FALSE, FALSE),
    (797, 'Celesteela', 9.2, 999.9, 'Para los seres de este mundo resulta extraño y peligroso, pero en el mundo del que procede es una criatura muy común.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/797.png', 'Sin género', 'alola', FALSE, FALSE),
    (798, 'Kartana', 0.3, 0.1, 'Para los seres de este mundo resulta extraño y peligroso, pero en el mundo del que procede es una criatura muy común.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/798.png', 'Sin género', 'alola', FALSE, FALSE),
    (799, 'Guzzlord', 5.5, 888.0, 'Uno de los extraños Ultraentes. Siempre está comiendo algo, como poseído de un hambre insaciable.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/799.png', 'Sin género', 'alola', FALSE, FALSE),
    (800, 'Necrozma', 2.4, 230.0, 'Con sus rayos láser destruye todo a su paso en busca de luz para sustentarse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/800.png', 'Sin género', 'alola', TRUE, FALSE),
    (801, 'Magearna', 1.0, 80.5, 'Pokémon artificial creado por científicos hace unos 500 años. Su verdadera esencia es una pieza llamada Coránima.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/801.png', 'Sin género', 'alola', FALSE, TRUE),
    (802, 'Marshadow', 0.7, 22.2, 'Posee la extraordinaria capacidad de infiltrarse en cualquier sombra, por lo que nadie lo había visto en mucho tiempo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/802.png', 'Sin género', 'alola', FALSE, TRUE),
    (803, 'Poipole', 0.6, 1.8, 'Un Ultraente originario de otro mundo. Se burla del oponente mientras lo rocía de veneno con el aguijón que tiene en la cabeza.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/803.png', 'Sin género', 'alola', FALSE, FALSE),
    (804, 'Naganadel', 3.6, 150.0, 'Uno de los Ultraentes. Su aguijón segrega un líquido tóxico cuya viscosidad le da una apariencia brillante.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/804.png', 'Sin género', 'alola', FALSE, FALSE),
    (805, 'Stakataka', 5.5, 820.0, 'Extraña criatura que podría ser un Ultraente. Parece un muro rocoso hasta que se mueve de repente y ataca.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/805.png', 'Sin género', 'alola', FALSE, FALSE),
    (806, 'Blacephalon', 1.8, 13.0, 'Un Ultraente surgido de un Ultraumbral. Crea una explosión para sorprender al oponente y aprovecha para absorber su energía vital.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/806.png', 'Sin género', 'alola', FALSE, FALSE),
    (807, 'Zeraora', 1.5, 44.5, 'Las almohadillas de sus patas desprenden descargas eléctricas. Cuando corre, hace que caigan rayos y reverberen los truenos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/807.png', 'Sin género', 'alola', FALSE, TRUE),
    (808, 'Meltan', 0.2, 8.0, 'Viven en grupos, pero, llegado el momento, el ejemplar más fuerte absorbe a sus camaradas y evoluciona.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/808.png', 'Sin género', 'alola', FALSE, TRUE),
    (809, 'Melmetal', 2.5, 800.0, 'Gracias a la inercia y la fuerza centrífuga, los puñetazos que propina con sus pesadas tuercas son los más potentes del mundo Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/809.png', 'Sin género', 'alola', FALSE, TRUE),
    (810, 'Grookey', 0.3, 5.0, 'Ataca golpeando sin cesar con su baqueta, con un entusiasmo que crece a medida que acelera el ritmo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/810.png', 'Ambos', 'galar', FALSE, FALSE),
    (811, 'Thwackey', 0.7, 14.0, 'Se concentra tanto en marcar el ritmo que, cuando su rival se debilita en combate, no se da ni cuenta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/811.png', 'Ambos', 'galar', FALSE, FALSE),
    (812, 'Rillaboom', 2.1, 90.0, 'El percusionista con la técnica más depurada se convierte en líder. Son de carácter tranquilo y dan mucha importancia a la armonía del grupo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/812.png', 'Ambos', 'galar', FALSE, FALSE),
    (813, 'Scorbunny', 0.3, 4.5, 'Cuando se prepara para combatir, irradia calor por la punta de la nariz y el pelo que le recubre las patas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/813.png', 'Ambos', 'galar', FALSE, FALSE),
    (814, 'Raboot', 0.6, 9.0, 'Para mejorar su habilidad con los pies, toma bayas de las ramas de los árboles sin usar las manos y juega a darles toques.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/814.png', 'Ambos', 'galar', FALSE, FALSE),
    (815, 'Cinderace', 1.4, 33.0, 'Destaca tanto en ataque como en defensa. Se crece cuando recibe una ovación, pero a veces se luce tanto que termina viéndose en apuros.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/815.png', 'Ambos', 'galar', FALSE, FALSE),
    (816, 'Sobble', 0.3, 4.0, 'Al mojarse, su piel cambia de color y pasa a ser invisible, como si se hubiese camuflado.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/816.png', 'Ambos', 'galar', FALSE, FALSE),
    (817, 'Drizzile', 0.7, 11.5, 'Es inteligente, pero no muestra especial interés por nada. Distribuye trampas por su territorio para mantener alejados a sus enemigos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/817.png', 'Ambos', 'galar', FALSE, FALSE),
    (818, 'Inteleon', 1.9, 45.2, 'Dispara chorros de agua por la punta de los dedos a 3 mach de velocidad. Con su membrana nictitante puede ver los puntos débiles del rival.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/818.png', 'Ambos', 'galar', FALSE, FALSE),
    (819, 'Skwovet', 0.3, 2.5, 'Siempre están comiendo bayas, por lo que son más robustos de lo que aparentan. Frecuentan los huertos en busca de su preciado manjar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/819.png', 'Ambos', 'galar', FALSE, FALSE),
    (820, 'Greedent', 0.6, 6.0, 'Sus incisivos, de fuerza y dureza extraordinarias, le permiten mordisquear incluso las bayas más duras. Es un Pokémon muy común en Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/820.png', 'Ambos', 'galar', FALSE, FALSE),
    (821, 'Rookidee', 0.2, 1.8, 'Su pequeño cuerpo le permite volar a gran velocidad para golpear los puntos débiles de rivales mucho más grandes que él.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/821.png', 'Ambos', 'galar', FALSE, FALSE),
    (822, 'Corvisquire', 0.8, 16.0, 'Tras haber librado combates muy duros, ha desarrollado la habilidad de determinar con precisión la fuerza de su adversario.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/822.png', 'Ambos', 'galar', FALSE, FALSE),
    (823, 'Corviknight', 2.2, 75.0, 'Debido a su excelente capacidad de vuelo y a su gran inteligencia, ejerce de taxi volador en Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/823.png', 'Ambos', 'galar', FALSE, FALSE),
    (824, 'Blipbug', 0.4, 8.0, 'Es habitual verlo en el campo. Los pelos que tiene son sensores con los que percibe lo que ocurre a su alrededor.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/824.png', 'Ambos', 'galar', FALSE, FALSE),
    (825, 'Dottler', 0.4, 19.5, 'Está en constante crecimiento dentro del caparazón. Mientras se prepara para evolucionar, examina el exterior con sus poderes psíquicos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/825.png', 'Ambos', 'galar', FALSE, FALSE),
    (826, 'Orbeetle', 0.4, 40.8, 'Se sirve de sus poderes psíquicos, con los que es capaz de percibir lo que ocurre en un radio de 10 km, para examinar sus alrededores.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/826.png', 'Ambos', 'galar', FALSE, FALSE),
    (827, 'Nickit', 0.6, 8.9, 'Prudente y astuto, borra con la cola las huellas que deja al huir tras robarle el alimento a otro Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/827.png', 'Ambos', 'galar', FALSE, FALSE),
    (828, 'Thievul', 1.2, 19.9, 'Un Pokémon ágil y de afiladas garras que se alimenta de huevos y comida robados. Los Boltund son su enemigo natural.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/828.png', 'Ambos', 'galar', FALSE, FALSE),
    (829, 'Gossifleur', 0.4, 2.2, 'Muchos los crían tras quedar prendados de lo adorables que resultan cuando cantan dando vueltas empujados por la brisa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/829.png', 'Ambos', 'galar', FALSE, FALSE),
    (830, 'Eldegoss', 0.5, 2.5, 'El hilo fabricado a partir de su algodón es muy bello y brillante; uno de los productos estrella de la región de Galar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/830.png', 'Ambos', 'galar', FALSE, FALSE),
    (831, 'Wooloo', 0.6, 6.0, 'Si le crece el pelo demasiado, no puede moverse. Las telas confeccionadas con lana de Wooloo son sorprendentemente resistentes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/831.png', 'Ambos', 'galar', FALSE, FALSE),
    (832, 'Dubwool', 1.3, 43.0, 'Sus espléndidos cuernos sirven de reclamo para atraer al sexo opuesto. No los utiliza como arma.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/832.png', 'Ambos', 'galar', FALSE, FALSE),
    (833, 'Chewtle', 0.3, 8.5, 'El cuerno que tiene en la cabeza es duro como una roca. Lo usa para atacar al rival y, cuando este baja la guardia, lo muerde y no lo suelta.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/833.png', 'Ambos', 'galar', FALSE, FALSE),
    (834, 'Drednaw', 1.0, 115.5, 'Su cuello extensible le permite alcanzar a los rivales a distancia. Hundiendo sus afilados dientes, les da el golpe de gracia.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/834.png', 'Ambos', 'galar', FALSE, FALSE),
    (835, 'Yamper', 0.3, 13.5, 'Son muy glotones, por lo que ayudan a la gente a cambio de comida. Echan chispas al correr.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/835.png', 'Ambos', 'galar', FALSE, FALSE),
    (836, 'Boltund', 1.0, 34.0, 'La electricidad le confiere una enorme fuerza en las patas. Su velocidad punta puede superar los 90 km/h sin problema.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/836.png', 'Ambos', 'galar', FALSE, FALSE),
    (837, 'Rolycoly', 0.3, 12.0, 'Recorre incluso los caminos más impracticables y pedregosos como si de un monociclo se tratase. La combustión de carbón es su fuente vital.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/837.png', 'Ambos', 'galar', FALSE, FALSE),
    (838, 'Carkol', 1.1, 78.0, 'Gira las patas a gran velocidad para correr a unos 30 km/h. Emite llamas a una temperatura de 1000 °C.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/838.png', 'Ambos', 'galar', FALSE, FALSE),
    (839, 'Coalossal', 2.8, 310.5, 'Cuando se enzarza en un combate, la montaña de carbón arde al rojo vivo y esparce chispas que calcinan todo lo que le rodea.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/839.png', 'Ambos', 'galar', FALSE, FALSE),
    (840, 'Applin', 0.2, 0.5, 'Nada más nacer se refugia en una manzana, cuyo interior va devorando a medida que crece. El sabor de la fruta determina la evolución.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/840.png', 'Ambos', 'galar', FALSE, FALSE),
    (841, 'Flapple', 0.3, 1.0, 'Escupe una saliva sumamente ácida y vuela con sus alas compuestas por piel de manzana, cuyo aspecto es capaz de adoptar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/841.png', 'Ambos', 'galar', FALSE, FALSE),
    (842, 'Appletun', 0.4, 13.0, 'Su cuerpo está recubierto de néctar. La piel de la espalda es tan dulce que los niños de antaño solían tomarla como merienda.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/842.png', 'Ambos', 'galar', FALSE, FALSE),
    (843, 'Silicobra', 2.2, 7.6, 'Expulsa arena por los orificios nasales. Una vez que aturde al enemigo, aprovecha la ocasión para ocultarse bajo tierra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/843.png', 'Ambos', 'galar', FALSE, FALSE),
    (844, 'Sandaconda', 3.8, 65.5, 'La manera tan particular que tiene de enrollarse sobre sí mismo le permite expulsar con mayor eficacia la arena que almacena en la bolsa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/844.png', 'Ambos', 'galar', FALSE, FALSE),
    (845, 'Cramorant', 0.8, 18.0, 'Traga Arrokuda enteros debido a su glotonería, tan notable que en ocasiones ingiere hasta otros Pokémon sin querer.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/845.png', 'Ambos', 'galar', FALSE, FALSE),
    (846, 'Arrokuda', 0.5, 1.0, 'Cuando tiene el estómago lleno, le cuesta moverse y corre el riesgo de ser engullido por algún Cramorant.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/846.png', 'Ambos', 'galar', FALSE, FALSE),
    (847, 'Barraskewda', 1.3, 30.0, 'Hace girar su aleta caudal para impulsarse y arremeter contra la presa, a la que ensarta a una velocidad que supera los 100 nudos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/847.png', 'Ambos', 'galar', FALSE, FALSE),
    (848, 'Toxel', 0.4, 11.0, 'Provoca una reacción química para generar energía eléctrica con sus toxinas. Aunque de bajo voltaje, puede causar entumecimiento.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/848.png', 'Ambos', 'galar', FALSE, FALSE),
    (849, 'Toxtricity', 1.6, 40.0, 'Posee un carácter belicoso e irascible. Bebe una gran cantidad de agua estancada para absorber sus toxinas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/849.png', 'Ambos', 'galar', FALSE, FALSE),
    (850, 'Sizzlipede', 0.7, 1.0, 'Oprime a sus presas con su cuerpo candente. Una vez bien tostadas, las devora con fruición.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/850.png', 'Ambos', 'galar', FALSE, FALSE),
    (851, 'Centiskorch', 3.0, 120.0, 'Posee una naturaleza agresiva. El peligro que entraña su cuerpo candente es considerable, aunque sus afilados colmillos no le van a la zaga.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/851.png', 'Ambos', 'galar', FALSE, FALSE),
    (852, 'Clobbopus', 0.6, 4.0, 'Su inteligencia es similar a la de un niño de tres años. Sus tentáculos se desprenden a menudo, pero ni se inmuta, ya que se regeneran solos.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/852.png', 'Ambos', 'galar', FALSE, FALSE),
    (853, 'Grapploct', 1.6, 39.0, 'Se aventura en tierra firme para buscar rivales contra los que luchar para medir su valía. Tras terminar el combate, regresa al mar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/853.png', 'Ambos', 'galar', FALSE, FALSE),
    (854, 'Sinistea', 0.1, 0.2, 'La taza de té donde se hospeda forma parte de una antigua y valiosa vajilla, de la que circulan numerosas falsificaciones.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/854.png', 'Sin género', 'galar', FALSE, FALSE),
    (855, 'Polteageist', 0.2, 0.4, 'Si avista una taza de té abandonada a su suerte, la rellena vertiendo parte de su propio cuerpo para generar otro Polteageist.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/855.png', 'Sin género', 'galar', FALSE, FALSE),
    (856, 'Hatenna', 0.4, 3.4, 'Siente predilección por los lugares despoblados. Si percibe una emoción intensa, emprende la huida a toda prisa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/856.png', 'Hembra', 'galar', FALSE, FALSE),
    (857, 'Hattrem', 0.6, 4.8, 'Silencia al objetivo atizándole con los mechones. Despliega una potencia devastadora capaz de noquear a un boxeador profesional.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/857.png', 'Hembra', 'galar', FALSE, FALSE),
    (858, 'Hatterene', 2.1, 5.1, 'Recibe el apodo de Hechicera del Bosque. Quienes arman demasiado barullo se exponen a ser despedazados por las garras de su tentáculo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/858.png', 'Hembra', 'galar', FALSE, FALSE),
    (859, 'Impidimp', 0.4, 5.5, 'Se infiltra en las casas para hurtar a sus anchas y, por si fuera poco, nutrirse de la energía negativa que liberan sus contrariados habitantes.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/859.png', 'Macho', 'galar', FALSE, FALSE),
    (860, 'Morgrem', 0.8, 12.5, 'De noche, atrae con astucia a su objetivo hasta el bosque. Al parecer, tiene la capacidad de hacer crecer productos agrícolas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/860.png', 'Macho', 'galar', FALSE, FALSE),
    (861, 'Grimmsnarl', 1.5, 61.0, 'Su cabello desempeña una función similar a la de fibras musculares. Al soltárselo, su movimiento tentacular le permite reducir a su objetivo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/861.png', 'Macho', 'galar', FALSE, FALSE),
    (862, 'Obstagoon', 1.6, 46.0, 'Evoluciona tras haber librado numerosas peleas. El grito de guerra que profiere mientras pone los brazos en cruz atemoriza a cualquier rival.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/862.png', 'Ambos', 'galar', FALSE, FALSE),
    (863, 'Perrserker', 0.8, 28.0, 'Su devoción por la lucha ha propiciado que evolucionara y le ha conferido unas peligrosas garras que se convierten en dagas al extenderse.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/863.png', 'Ambos', 'galar', FALSE, FALSE),
    (864, 'Cursola', 1.0, 0.4, 'Conviene tener cuidado con el cuerpo espectral que recubre su alma, pues quien lo toque podría acabar inerte como una piedra.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/864.png', 'Ambos', 'galar', FALSE, FALSE),
    (865, 'Sirfetch’d', 0.8, 117.0, 'Repele ataques con las hojas de su duro puerro y contraataca con su tallo afilado. El puerro que le sirve de armamento sigue siendo comestible.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/865.png', 'Ambos', 'galar', FALSE, FALSE),
    (866, 'Mr. Rime', 1.5, 58.2, 'Se ha granjeado la simpatía de todo el mundo por sus cómicos movimientos. Emite poderes psíquicos por el motivo de su barriga.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/866.png', 'Ambos', 'galar', FALSE, FALSE),
    (867, 'Runerigus', 1.6, 66.6, 'Su cuerpo, similar a una sombra, no debe tocarse bajo ningún concepto o se visualizarán los horribles recuerdos impregnados en la imagen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/867.png', 'Ambos', 'galar', FALSE, FALSE),
    (868, 'Milcery', 0.2, 0.3, 'Se dice que las pastelerías donde ha aparecido Milcery tienen casi todas las papeletas para saborear las mieles del éxito.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/868.png', 'Hembra', 'galar', FALSE, FALSE),
    (869, 'Alcremie', 0.3, 0.5, 'La nata que le brota de las manos es más dulce y sustanciosa cuando está feliz.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/869.png', 'Hembra', 'galar', FALSE, FALSE),
    (870, 'Falinks', 3.0, 62.0, 'Este Pokémon está formado por seis individuos que cambian de formación al luchar, haciendo gala de un notable espíritu de equipo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/870.png', 'Sin género', 'galar', FALSE, FALSE),
    (871, 'Pincurchin', 0.3, 1.0, 'Acumula electricidad en cada una de sus púas. Aunque estas se rompan, son capaces de seguir descargando energía durante 3 h.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/871.png', 'Ambos', 'galar', FALSE, FALSE),
    (872, 'Snom', 0.3, 3.8, 'Se nutre de la nieve acumulada en el terreno. Cuanta más ingiere, más imponentes se vuelven las púas que presenta en el lomo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/872.png', 'Ambos', 'galar', FALSE, FALSE),
    (873, 'Frosmoth', 1.3, 42.0, 'No muestra la menor compasión con quien asole el campo: lo escarmienta batiendo sus gélidas alas para provocar una ventisca.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/873.png', 'Ambos', 'galar', FALSE, FALSE),
    (874, 'Stonjourner', 2.5, 520.0, 'Una vez al año y en una fecha concreta, tienen la costumbre de aparecer de la nada para reunirse y formar un círculo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/874.png', 'Ambos', 'galar', FALSE, FALSE),
    (875, 'Eiscue', 1.4, 89.0, 'Se enfría constantemente la cara con hielo por su escasa resistencia al calor. Utiliza el pelo de la cabeza para pescar en el mar.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/875.png', 'Ambos', 'galar', FALSE, FALSE),
    (876, 'Indeedee', 0.9, 28.0, 'Con sus cuernos percibe las emociones de los seres vivos que se hallen cerca. Los sentimientos positivos constituyen su fuente de energía.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/876.png', 'Ambos', 'galar', FALSE, FALSE),
    (877, 'Morpeko', 0.3, 3.0, 'Siempre tiene apetito, sin importar lo mucho que coma. Lleva con sumo cuidado las semillas que ha tostado con su propia electricidad.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/877.png', 'Ambos', 'galar', FALSE, FALSE),
    (878, 'Cufant', 1.2, 100.0, 'Realiza tareas que requieren de esfuerzo físico, es su fuerte. Con la lluvia, su cuerpo de cobre se oxida y adquiere una tonalidad verde intensa.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/878.png', 'Ambos', 'galar', FALSE, FALSE),
    (879, 'Copperajah', 3.0, 650.0, 'Viven en manadas. La fuerza prensil de su trompa es tan extraordinaria que le permite hacer añicos incluso grandes rocas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/879.png', 'Ambos', 'galar', FALSE, FALSE),
    (880, 'Dracozolt', 1.8, 190.0, 'Produce electricidad con la robusta musculatura de la cola. El tamaño de la parte superior del cuerpo palidece en comparación con la inferior.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/880.png', 'Sin género', 'galar', FALSE, FALSE),
    (881, 'Arctozolt', 2.3, 150.0, 'Antiguamente vivía en el mar y usaba el hielo del cuerpo para conservar los alimentos. Su extrema lentitud, sin embargo, lo condenó a la extinción.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/881.png', 'Sin género', 'galar', FALSE, FALSE),
    (882, 'Dracovish', 2.3, 215.0, 'Exhibe con orgullo su inmensa capacidad motriz, que le permite superar los 60 km/h, pero solo puede respirar bajo el agua.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/882.png', 'Sin género', 'galar', FALSE, FALSE),
    (883, 'Arctovish', 2.0, 175.0, 'Aunque la piel de su rostro era capaz de resistir cualquier ataque, su dificultad para respirar acabó provocando su extinción.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/883.png', 'Sin género', 'galar', FALSE, FALSE),
    (884, 'Duraludon', 1.8, 40.0, 'Hace gala de una agilidad extraordinaria, ya que su cuerpo está compuesto de un metal especial. Detesta la lluvia, por lo que habita en cuevas.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/884.png', 'Ambos', 'galar', FALSE, FALSE),
    (885, 'Dreepy', 0.5, 2.0, 'En solitario es tan débil que no sería rival ni para un niño, pero, al entrenarse con sus congéneres, evoluciona y se vuelve más fuerte.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/885.png', 'Ambos', 'galar', FALSE, FALSE),
    (886, 'Drakloak', 1.4, 11.0, 'Si no lleva un Dreepy del que cuidar encima de la cabeza, se intranquiliza y trata de sustituirlo con otro Pokémon.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/886.png', 'Ambos', 'galar', FALSE, FALSE),
    (887, 'Dragapult', 3.0, 50.0, 'Al parecer, los Dreepy que residen en sus cuernos esperan con ilusión el momento de ser propulsados a velocidad supersónica.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/887.png', 'Ambos', 'galar', FALSE, FALSE),
    (888, 'Zacian', 2.8, 110.0, 'Hay quien lo considera una suerte de figura fraterna a la par que rival de Zamazenta, un Pokémon sumido en un profundo letargo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/888.png', 'Sin género', 'galar', TRUE, FALSE),
    (889, 'Zamazenta', 2.9, 210.0, 'Con la apariencia de una estatua de piedra, este Pokémon se sumió en un letargo tan profundo que acabó cayendo en el olvido.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/889.png', 'Sin género', 'galar', TRUE, FALSE),
    (890, 'Eternatus', 20.0, 950.0, 'Fue hallado en el interior de un meteorito caído hace 20 000 años. Por lo visto, está relacionado con el misterio que rodea al fenómeno Dinamax.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/890.png', 'Sin género', 'galar', TRUE, FALSE),
    (891, 'Kubfu', 0.6, 12.0, 'Al tirar de los mechones blancos de la cabeza, acrecienta su espíritu luchador y empieza a acumular fuerza en el órgano de su bajo vientre.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/891.png', 'Ambos', 'galar', TRUE, FALSE),
    (892, 'Urshifu', 1.9, 105.0, 'Vive en zonas montañosas en áreas recónditas, donde entrena corriendo por escarpados riscos para fortalecer sus piernas y refinar su técnica.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/892.png', 'Ambos', 'galar', TRUE, FALSE),
    (893, 'Zarude', 1.8, 70.0, 'Las lianas que le brotan del cuerpo nutren y fertilizan el mantillo del bosque cuando se le desprenden.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/893.png', 'Sin género', 'galar', FALSE, TRUE),
    (894, 'Regieleki', 1.2, 145.0, 'Todo su cuerpo es un órgano electrógeno, cuya potencia sería suficiente para abastecer la región de Galar por completo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/894.png', 'Sin género', 'galar', TRUE, FALSE),
    (895, 'Regidrago', 2.1, 200.0, 'Todo su cuerpo es una gema de energía dragón cristalizada. Se cree que posee los poderes de todos los Pokémon dragón.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/895.png', 'Sin género', 'galar', TRUE, FALSE),
    (896, 'Glastrier', 2.2, 800.0, 'Cuenta con una fuerza física sobrecogedora. La máscara de hielo que le cubre el rostro es cien veces más dura que el diamante.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/896.png', 'Sin género', 'galar', TRUE, FALSE),
    (897, 'Spectrier', 2.0, 44.5, 'Amante de la quietud y la soledad, galopa por las tinieblas nocturnas absorbiendo la energía vital de toda criatura que esté durmiendo.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/897.png', 'Sin género', 'galar', TRUE, FALSE),
    (898, 'Calyrex', 1.1, 7.7, 'Legendario monarca del antiguo Galar. Posee el poder de sanar el espíritu y de hacer brotar la vegetación.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/898.png', 'Sin género', 'galar', TRUE, FALSE),
    (899, 'Wyrdeer', 1.8, 95.1, NULL, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/899.png', 'Ambos', 'galar', FALSE, FALSE),
